INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "升高", "is_correct": true, "explanation": "正确：「升高」与「降低」意思相反，指数值、温度等变高。"}, {"text": "写作", "is_correct": false, "explanation": "与「降低」没有反义关系，「写作」指写文章。"}, {"text": "修理", "is_correct": false, "explanation": "与「降低」没有反义关系，「修理」指把坏了的东西弄好。"}, {"text": "旅行", "is_correct": false, "explanation": "与「降低」没有反义关系，「旅行」指到外地去游览。"}], "correct_answer": "升高", "explanations": {"升高": "正确：「升高」与「降低」意思相反，指数值、温度等变高。", "写作": "与「降低」没有反义关系，「写作」指写文章。", "修理": "与「降低」没有反义关系，「修理」指把坏了的东西弄好。", "旅行": "与「降低」没有反义关系，「旅行」指到外地去游览。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西落下去或变得少一些。", "primary_collocate": null, "pronunciation": "jiàng dī", "ipa": "tɕiaŋ˥˩ ti˥", "syllable_count": 2, "sentences": [{"text": "这家店东西太贵，他想降低价格。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "请把音乐的声音降低一点。", "target_word": "降低", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "晚上气温会降低到十度。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家店降低了价格，所以买的人多了。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "多运动可以降低生病的风险。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂想办法降低成本，让产品更便宜。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车时要降低速度，不能太快。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了降低噪音，学校在路边种了很多树。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师没有降低要求，大家要继续努力。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "医生说吃药可以降低血压。", "target_word": "降低", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "降低了", "label": "体标"}, {"form": "降低过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使价格、温度、速度、水平等变低或变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '447b2f2c-611b-4adc-a6ed-b618209aaf2e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "提高", "is_correct": false, "explanation": "语义：「提高」指往上升，与「东西太贵」的意思矛盾。"}, {"text": "降低", "is_correct": true, "explanation": "正确：「降低」表示变低，与「东西太贵，他想……价格」呼应。"}, {"text": "增加", "is_correct": false, "explanation": "语义：「增加」指数量变多，与「东西太贵」的意思矛盾。"}, {"text": "印刷", "is_correct": false, "explanation": "搭配：「印刷」不能直接和「价格」搭配，说不通。"}], "explanations": {"提高": "语义：「提高」指往上升，与「东西太贵」的意思矛盾。", "降低": "正确：「降低」表示变低，与「东西太贵，他想……价格」呼应。", "增加": "语义：「增加」指数量变多，与「东西太贵」的意思矛盾。", "印刷": "搭配：「印刷」不能直接和「价格」搭配，说不通。"}, "sentence_index": 0, "correct_answer": "降低"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他降低了运动，身体变好了。", "explanation": "这里应该用〈增加〉。「降低」是变少，与「身体变好了」矛盾；多运动要说〈增加〉。"}, {"text": "这家店降低了顾客。", "explanation": "这里应该用〈减少〉。「降低」用于价格、温度、水平等量，说顾客变少要用〈减少〉。"}, {"text": "他的性格降低了，变得很安静。", "explanation": "这里应该用〈平和〉。「降低」指数量、价格、温度等变少或变低，用来说性格变得温和、安静不对；形容性格要用〈平和〉之类的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "欣赏", "is_correct": false, "explanation": "搭配：「欣赏」一般用于风景、艺术，不能和「速度」搭配。"}, {"text": "加快", "is_correct": false, "explanation": "语义：「加快」是变快，与后面的「不能太快」矛盾。"}, {"text": "降低", "is_correct": true, "explanation": "正确：「降低」表示变慢，与「不能太快」一致。"}, {"text": "保养", "is_correct": false, "explanation": "搭配：「保养」用于机器、皮肤等，不能和「速度」搭配。"}], "explanations": {"欣赏": "搭配：「欣赏」一般用于风景、艺术，不能和「速度」搭配。", "加快": "语义：「加快」是变快，与后面的「不能太快」矛盾。", "降低": "正确：「降低」表示变慢，与「不能太快」一致。", "保养": "搭配：「保养」用于机器、皮肤等，不能和「速度」搭配。"}, "sentence_index": 6, "correct_answer": "降低"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个方法可以降低工作速度，让工作更快完成。", "explanation": "这里应该用〈提高〉。「降低」是变慢，与「让工作更快完成」矛盾；要提高效率应说〈提高〉。"}, {"text": "我们降低了两公里的路，终于到了山顶。", "explanation": "这里应该用〈缩短〉。「降低」用于价格、温度、血压等量，说路程变短要用〈缩短〉。"}, {"text": "他降低了大家的心情，所以大家都笑了。", "explanation": "这里应该用〈提高〉。「降低」是变低，与「大家都笑了」矛盾；让大家高兴要说〈提高〉心情。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工厂很降低了成本，产品更便宜了。", "corrected_sentence": "工厂大大降低了成本，产品更便宜了。", "error_description": "错误：「很降低了成本」；正确：「大大降低了成本」。「很」是程度副词，只修饰形容词，不能修饰动词「降低」；表示程度深的动作要用「大大」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20634, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个月的油价降低地很快，司机都很高兴。", "corrected_sentence": "这个月的油价降低得很快，司机都很高兴。", "error_description": "错误：「降低地很快」；正确：「降低得很快」。「得」引出动词后面表示程度的补语，「地」用来修饰动词，这里要用「得」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6a458cc-0e81-446e-9b52-8645627b3211') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
