INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20640, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "致使某人或某事产生某种状态或结果。", "primary_collocate": null, "pronunciation": "shǐ", "ipa": "ʂɨ˨˩˦", "syllable_count": 1, "sentences": [{"text": "这个好消息使大家都很高兴。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话使我想起了小时候。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "运动能使人身体健康。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师的鼓励使他有了信心。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "噪音使她睡不着觉。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事使我明白了很多道理。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大雨使比赛推迟了。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音乐使人心情放松。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的努力使全家过上了好日子。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "突然的响声使孩子吓了一跳。", "target_word": "使", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "使得", "label": "复合"}], "register": "书面", "sense_fingerprint": "动词：致使，让某人或某事产生某种变化或结果", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7c970757-3a26-48dc-826e-19d56f34238d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20640, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案：使（shǐ）是动词，表示致使某人或某事产生某种结果"}, {"text": "市", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是城市"}, {"text": "诗", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是诗"}, {"text": "十", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是十"}, {"text": "死", "is_correct": false, "explanation": "sǐ 与 shǐ 声母不同（s 与 sh），声调相同，意思是死亡"}], "explanations": {"使": "正确答案：使（shǐ）是动词，表示致使某人或某事产生某种结果", "市": "shì（第四声）与 shǐ（第三声）声调不同，意思是城市", "诗": "shī（第一声）与 shǐ（第三声）声调不同，意思是诗", "十": "shí（第二声）与 shǐ（第三声）声调不同，意思是十", "死": "sǐ 与 shǐ 声母不同（s 与 sh），声调相同，意思是死亡"}, "sentence_index": null, "correct_answer": "使"}, "level_3": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案。此句的“使”表示致使，“好消息”使大家产生“很高兴”的结果"}, {"text": "惹", "is_correct": false, "explanation": "语义：“惹”多指引起麻烦或不快，与“好消息”和“很高兴”矛盾"}, {"text": "吓", "is_correct": false, "explanation": "语义：“吓”表示使人害怕，与后面的“很高兴”结果矛盾"}, {"text": "拖", "is_correct": false, "explanation": "搭配：“拖”后接能被拖动的东西，不能拖“大家”作致使的对象"}], "explanations": {"使": "正确答案。此句的“使”表示致使，“好消息”使大家产生“很高兴”的结果", "惹": "语义：“惹”多指引起麻烦或不快，与“好消息”和“很高兴”矛盾", "吓": "语义：“吓”表示使人害怕，与后面的“很高兴”结果矛盾", "拖": "搭配：“拖”后接能被拖动的东西，不能拖“大家”作致使的对象"}, "sentence_index": 0, "correct_answer": "使"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "请使我进去吧，外面太冷了。", "explanation": "这里应该用〈让〉。请求或允许别人做某事要用“让”，“使”只表示致使产生某种结果"}, {"text": "这本书使我弄丢了。", "explanation": "这里应该用〈让〉。表示被动、遭受的“让”不能换成“使”，“使”只表示致使某人做某事"}, {"text": "他使着一本书走进了教室。", "explanation": "这里应该用〈抱〉。拿着书要说“抱”，“使”不用于这类动作"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20640, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案：使（shǐ）是动词，表示致使某人或某事产生某种结果"}, {"text": "施", "is_correct": false, "explanation": "shī（第一声）与 shǐ（第三声）声调不同，意思是施行、施加"}, {"text": "时", "is_correct": false, "explanation": "shí（第二声）与 shǐ（第三声）声调不同，意思是时间"}, {"text": "是", "is_correct": false, "explanation": "shì（第四声）与 shǐ（第三声）声调不同，意思是是、对"}, {"text": "死", "is_correct": false, "explanation": "sǐ 与 shǐ 声母不同（s 与 sh），声调相同，意思是死亡"}], "explanations": {"使": "正确答案：使（shǐ）是动词，表示致使某人或某事产生某种结果", "施": "shī（第一声）与 shǐ（第三声）声调不同，意思是施行、施加", "时": "shí（第二声）与 shǐ（第三声）声调不同，意思是时间", "是": "shì（第四声）与 shǐ（第三声）声调不同，意思是是、对", "死": "sǐ 与 shǐ 声母不同（s 与 sh），声调相同，意思是死亡"}, "sentence_index": null, "correct_answer": "使"}, "level_3": {"options": [{"text": "使", "is_correct": true, "explanation": "正确答案。此句的“使”表示致使，“一场大雨”造成“比赛推迟”的结果"}, {"text": "劝", "is_correct": false, "explanation": "配价：“劝”要求以人为对象，“大雨”不能劝“比赛”推迟"}, {"text": "请", "is_correct": false, "explanation": "配价：“请”的宾语是人，不能说“一场大雨请比赛推迟”"}, {"text": "抢", "is_correct": false, "explanation": "语义：“抢”表示争夺，与“大雨”造成比赛推迟的结果不符"}], "explanations": {"使": "正确答案。此句的“使”表示致使，“一场大雨”造成“比赛推迟”的结果", "劝": "配价：“劝”要求以人为对象，“大雨”不能劝“比赛”推迟", "请": "配价：“请”的宾语是人，不能说“一场大雨请比赛推迟”", "抢": "语义：“抢”表示争夺，与“大雨”造成比赛推迟的结果不符"}, "sentence_index": 6, "correct_answer": "使"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他使着一个包去上学。", "explanation": "这里应该用〈挎〉。挎包是挂在肩上的，不能说“使包”，“使”不用于这类动作"}, {"text": "她使着一件红裙子。", "explanation": "这里应该用〈穿〉。衣服要说“穿”，不能说“使”"}, {"text": "妈妈使着水果去看朋友。", "explanation": "这里应该用〈拿〉。水果要说“拿”，“使”不用于拿东西"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20640, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事使了我们很担心。", "corrected_sentence": "这件事使我们很担心。", "error_description": "错误：“使了我们”，在兼语动词“使”后面加了“了”；正确：“使我们”，“使”后直接接兼语“我们”，不加“了”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20640, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件事使没我们担心。", "corrected_sentence": "这件事没使我们担心。", "error_description": "错误：“使没”，否定词“没”放在了动词“使”之后；正确：“没使”，否定词要放在“使”之前", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '38f8333b-0010-4ada-9ff4-55b9725ee229') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
