INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20654, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "教别人，让他学会。", "primary_collocate": null, "pronunciation": "jiāo huì", "ipa": "tɕjɑʊ˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "姐姐教会了我用筷子。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用一个月教会了小狗握手。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教会我们写自己的名字。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爷爷耐心地教会我下象棋。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "谁教会你说这么好的中文？", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想教会妈妈用手机付钱。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "教练教会孩子们踢足球。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他一点一点教会我开车。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我来教会你用这台机器。", "target_word": "教会", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他教了三天，还没教会我游泳。", "target_word": "教会", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "教会了", "label": "完成体"}, {"form": "教会过", "label": "经历体"}, {"form": "教會", "label": "繁体"}], "register": "中性", "sense_fingerprint": "教人并让其学会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f4f3f8c-c61e-4ff7-96cb-69e0e2aa330f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20654, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：教会（jiāo huì），意思是教别人使其学会。"}, {"text": "将会", "is_correct": false, "explanation": "jiāng 与 jiāo 韵母不同（ang 与 ao），“将会”表示将要发生，不是教人学会。"}, {"text": "交回", "is_correct": false, "explanation": "huí（第二声）与 huì（第四声）声调不同，“交回”意思是交还。"}, {"text": "叫回", "is_correct": false, "explanation": "jiào 与 jiāo 声调不同，huí 与 huì 声调也不同，“叫回”意思是叫…回来。"}], "explanations": {"教会": "正确：教会（jiāo huì），意思是教别人使其学会。", "将会": "jiāng 与 jiāo 韵母不同（ang 与 ao），“将会”表示将要发生，不是教人学会。", "交回": "huí（第二声）与 huì（第四声）声调不同，“交回”意思是交还。", "叫回": "jiào 与 jiāo 声调不同，huí 与 huì 声调也不同，“叫回”意思是叫…回来。"}, "sentence_index": null, "correct_answer": "教会"}, "level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：“教会”表示教到对方学会，与“用筷子”搭配，说明我已经学会。"}, {"text": "送", "is_correct": false, "explanation": "配价：“送”后不能接“我用筷子”这样的小句，句子不通。"}, {"text": "收藏", "is_correct": false, "explanation": "语义：“收藏”的对象是物品，不能用来指教人某种动作。"}, {"text": "聆听", "is_correct": false, "explanation": "搭配：“聆听”要接声音、讲话，不与“用筷子”这类动作搭配。"}], "explanations": {"教会": "正确：“教会”表示教到对方学会，与“用筷子”搭配，说明我已经学会。", "送": "配价：“送”后不能接“我用筷子”这样的小句，句子不通。", "收藏": "语义：“收藏”的对象是物品，不能用来指教人某种动作。", "聆听": "搭配：“聆听”要接声音、讲话，不与“用筷子”这类动作搭配。"}, "sentence_index": 0, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我教会了他三个月，他还是不会下棋。", "explanation": "这里应该用〈教〉。“教会”表示教到对方已经学会，与后面的“还是不会”矛盾；只说教的过程时用“教”。"}, {"text": "导游教会了这座古城。", "explanation": "这里应该用〈解说〉。“教会”的宾语应是要学会的知识或技能，古城不能被“教会”，导游应“解说”古城。"}, {"text": "老师教会了一遍，我还是不会。", "explanation": "这里应该用〈示范〉。“示范”只表示做给对方看，不保证对方学会；“教会”表示对方已学会，与“我还是不会”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20654, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：教会（jiāo huì），意思是教别人使其学会。"}, {"text": "教坏", "is_correct": false, "explanation": "huài 与 huì 韵母不同（ai 与 ui），“教坏”意思是把人教得变坏。"}, {"text": "交换", "is_correct": false, "explanation": "huàn 与 huì 韵母不同（uan 与 ui），“交换”意思是互相给予。"}, {"text": "交互", "is_correct": false, "explanation": "hù 与 huì 韵母不同，“交互”意思是相互。"}], "explanations": {"教会": "正确：教会（jiāo huì），意思是教别人使其学会。", "教坏": "huài 与 huì 韵母不同（ai 与 ui），“教坏”意思是把人教得变坏。", "交换": "huàn 与 huì 韵母不同（uan 与 ui），“交换”意思是互相给予。", "交互": "hù 与 huì 韵母不同，“交互”意思是相互。"}, "sentence_index": null, "correct_answer": "教会"}, "level_3": {"options": [{"text": "教会", "is_correct": true, "explanation": "正确：“教会”表示教到孩子们学会踢足球。"}, {"text": "批改", "is_correct": false, "explanation": "语义：“批改”针对作业或作文，不能用于体育动作的教学。"}, {"text": "装订", "is_correct": false, "explanation": "语义：“装订”指把纸张或书本订在一起，与“踢足球”无关。"}, {"text": "测量", "is_correct": false, "explanation": "搭配：“测量”的对象是长度、重量等，不能与“踢足球”搭配。"}], "explanations": {"教会": "正确：“教会”表示教到孩子们学会踢足球。", "批改": "语义：“批改”针对作业或作文，不能用于体育动作的教学。", "装订": "语义：“装订”指把纸张或书本订在一起，与“踢足球”无关。", "测量": "搭配：“测量”的对象是长度、重量等，不能与“踢足球”搭配。"}, "sentence_index": 6, "correct_answer": "教会"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "奶奶教会了我的饮食。", "explanation": "这里应该用〈照顾〉。“教会”的宾语应是要学会的知识或技能，“饮食”要照顾，不能用“教会”。"}, {"text": "老师教会了我写字的姿势，我还是没学会。", "explanation": "这里应该用〈指点〉。“指点”只指给出意见，不保证对方学会；“教会”表示对方已学会，与“我还是没学会”矛盾。"}, {"text": "我们教会了这道题的答案。", "explanation": "这里应该用〈讨论〉。“教会”指教别人学会，不能用于讨论答案这类交流。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20654, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "奶奶教会着我包饺子。", "corrected_sentence": "奶奶教会了我包饺子。", "error_description": "体标错误：表示完成的“教会”后应用“了”，不能用“着”，应说“教会了我包饺子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20654, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "哥哥很教会了我修自行车。", "corrected_sentence": "哥哥教会了我修自行车。", "error_description": "程度副词误用：“很”修饰形容词或状态，不能修饰动作动词“教会”，应删去“很”，说“哥哥教会了我修自行车”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
