INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西碎了或者破了。", "primary_collocate": null, "pronunciation": "dǎ pò", "ipa": "ta˨˩˦ pʰwo˥˩", "syllable_count": 2, "sentences": [{"text": "弟弟不小心打破了一个杯子。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小心点，别把盘子打破了。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "球飞过来，打破了教室的玻璃。", "target_word": "打破", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把妈妈最爱的碗打破了。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小猫跳上桌子，打破了花瓶。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上都是碎玻璃，是谁打破的？", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我手滑了一下，打破了一个鸡蛋。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用石头打破了窗户。", "target_word": "打破", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个杯子很结实，不容易打破。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "打破镜子的人是我的同学。", "target_word": "打破", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "打破了", "label": "体标"}, {"form": "打破过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使杯子、玻璃等具体物品碎裂或破损", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8732c7-e609-4f0d-a53d-cb81e17c8e1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "打破", "is_correct": true, "explanation": "正确。“弟弟不小心打破了一个杯子”，打破指使杯子碎裂。"}, {"text": "吃", "is_correct": false, "explanation": "语义：杯子不能被吃，句子说的是杯子破了。"}, {"text": "唱", "is_correct": false, "explanation": "语义：杯子不能被唱，与“不小心”的意外损坏无关。"}, {"text": "骑", "is_correct": false, "explanation": "搭配：“骑”搭配车、马，不能说骑杯子。"}], "explanations": {"打破": "正确。“弟弟不小心打破了一个杯子”，打破指使杯子碎裂。", "吃": "语义：杯子不能被吃，句子说的是杯子破了。", "唱": "语义：杯子不能被唱，与“不小心”的意外损坏无关。", "骑": "搭配：“骑”搭配车、马，不能说骑杯子。"}, "sentence_index": 0, "correct_answer": "打破"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她去食堂打破了两份饭。", "explanation": "这里应该用〈打饭〉。打饭指从食堂把饭盛出来，这是“打”的盛取义，不能用“打破”。"}, {"text": "他不小心打破了一跤。", "explanation": "这里应该用〈摔〉。摔指跌倒或掉下，一跤要说摔，不能说打破。"}, {"text": "事故打破了他的身体。", "explanation": "这里应该用〈伤害〉。伤害指使身体或物品受损，身体受损要说伤害，不能说打破。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "打破", "is_correct": true, "explanation": "正确。“我手滑了一下，打破了一个鸡蛋”，打破指鸡蛋碎了。"}, {"text": "写", "is_correct": false, "explanation": "搭配：“写”搭配文字，不能说写鸡蛋。"}, {"text": "戴", "is_correct": false, "explanation": "搭配：“戴”搭配帽子、眼镜等，不能说戴鸡蛋。"}, {"text": "讲", "is_correct": false, "explanation": "语义：鸡蛋不能讲，“手滑”说的是意外弄破东西。"}], "explanations": {"打破": "正确。“我手滑了一下，打破了一个鸡蛋”，打破指鸡蛋碎了。", "写": "搭配：“写”搭配文字，不能说写鸡蛋。", "戴": "搭配：“戴”搭配帽子、眼镜等，不能说戴鸡蛋。", "讲": "语义：鸡蛋不能讲，“手滑”说的是意外弄破东西。"}, "sentence_index": 6, "correct_answer": "打破"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他打破了那个谜语。", "explanation": "这里应该用〈破解〉。破解指解开谜底，谜语要说破解，“打破”只用于东西破损，不能用于谜语。"}, {"text": "他认真地打破了房间。", "explanation": "这里应该用〈打扫〉。打扫指清理，房间要说打扫，不能说打破。"}, {"text": "他打破了那个消息。", "explanation": "这里应该用〈打听〉。打听指询问，问到的消息不能说“打破”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟把那个杯子打破了了。", "corrected_sentence": "弟弟把那个杯子打破了。", "error_description": "错误：“打破了”后面多加了一个“了”，“了”在这里只能用一次。正确：“弟弟把那个杯子打破了。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20658, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他狠狠地打破了地窗户。", "corrected_sentence": "他狠狠地打破了窗户。", "error_description": "错误：多余的“地”出现在动词“打破了”与名词“窗户”之间，状语“地”只应紧跟在修饰的“狠狠”之后。正确：“他狠狠地打破了窗户。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。"}, {"text": "维持", "is_correct": false, "explanation": "无关：维持是保持某种状态，与“扩散”的任何义项都不构成反义。"}, {"text": "等待", "is_correct": false, "explanation": "无关：等待是停下来等候，与“扩散”没有反义关系。"}, {"text": "运输", "is_correct": false, "explanation": "无关：运输是把货物从一处送到另一处，与“扩散”没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。", "维持": "无关：维持是保持某种状态，与“扩散”的任何义项都不构成反义。", "等待": "无关：等待是停下来等候，与“扩散”没有反义关系。", "运输": "无关：运输是把货物从一处送到另一处，与“扩散”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "集中", "is_correct": true, "explanation": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。"}, {"text": "掩盖", "is_correct": false, "explanation": "无关：掩盖是遮住某物使其不被看见，与“扩散”没有反义关系。"}, {"text": "煮沸", "is_correct": false, "explanation": "无关：煮沸是把液体加热至沸腾，与“扩散”没有反义关系。"}, {"text": "栽培", "is_correct": false, "explanation": "无关：栽培是种植培育植物，与“扩散”之间没有反义关系。"}], "correct_answer": "集中", "explanations": {"集中": "反义：扩散是向外散布，集中是聚拢到一处，二者互为反义。", "掩盖": "无关：掩盖是遮住某物使其不被看见，与“扩散”没有反义关系。", "煮沸": "无关：煮沸是把液体加热至沸腾，与“扩散”没有反义关系。", "栽培": "无关：栽培是种植培育植物，与“扩散”之间没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "东西向四周散开。", "primary_collocate": null, "pronunciation": "kuò sàn", "ipa": "kʰwɔ˥˩ sɑn˥˩", "syllable_count": 2, "sentences": [{"text": "红墨水在水里慢慢扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "烟从窗口向外扩散。", "target_word": "扩散", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "油滴在水面上扩散开来。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "香水的味道在房间里扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "石头掉进水里，波纹向四周扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "热量从火炉向四周扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雾气在山谷里慢慢扩散。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "咖啡的香味扩散到了楼下。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "蓝色的颜料在纸上扩散开来。", "target_word": "扩散", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "声波在空气中向四周扩散。", "target_word": "扩散", "complexity_tier": "T3", "furigana": "shēng bō zài kōng qì zhōng xiàng sì zhōu kuò sàn", "sentence_source": "generated"}], "morphological_forms": [{"form": "扩散了", "label": "完成体"}, {"form": "扩散着", "label": "持续体"}, {"form": "扩散开来", "label": "复合"}, {"form": "擴散", "label": "繁体"}], "register": "中性", "sense_fingerprint": "物质向四周散开", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f4f3f8c-c61e-4ff7-96cb-69e0e2aa330f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扩散", "is_correct": true, "explanation": "正确。“扩散”指东西向四周散开，红墨水在水中慢慢散开，语义相合。"}, {"text": "凝固", "is_correct": false, "explanation": "语义：墨水在水里不会凝固，句子语义不通。"}, {"text": "生长", "is_correct": false, "explanation": "配价：“生长”要求有生命的主语，墨水没有生命，不能生长。"}, {"text": "发芽", "is_correct": false, "explanation": "语义：只有种子才能发芽，红墨水不能发芽。"}], "explanations": {"扩散": "正确。“扩散”指东西向四周散开，红墨水在水中慢慢散开，语义相合。", "凝固": "语义：墨水在水里不会凝固，句子语义不通。", "生长": "配价：“生长”要求有生命的主语，墨水没有生命，不能生长。", "发芽": "语义：只有种子才能发芽，红墨水不能发芽。"}, "sentence_index": 0, "correct_answer": "扩散"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个公园的面积扩散了三倍。", "explanation": "这里应该用〈扩大〉。扩散指东西向四周散开，面积、范围的扩大要用扩大。"}, {"text": "今年班里的人数扩散了不少。", "explanation": "这里应该用〈增加〉。扩散指向四周散开，人数这类数量的增长要用增加。"}, {"text": "这条公路扩散到了山顶。", "explanation": "这里应该用〈延伸〉。公路是线状向前伸展，扩散强调由中心向四周散开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扩散", "is_correct": true, "explanation": "正确。“扩散”指雾气向四周散开，在山谷里慢慢散开，语义相合。"}, {"text": "装订", "is_correct": false, "explanation": "语义：装订是把纸张整理成册，雾气不能被装订。"}, {"text": "批发", "is_correct": false, "explanation": "语义：批发是大批量售卖商品，雾气不能被批发。"}, {"text": "咀嚼", "is_correct": false, "explanation": "配价：咀嚼要求有嘴的主体和食物作宾语，“雾气”不能咀嚼。"}], "explanations": {"扩散": "正确。“扩散”指雾气向四周散开，在山谷里慢慢散开，语义相合。", "装订": "语义：装订是把纸张整理成册，雾气不能被装订。", "批发": "语义：批发是大批量售卖商品，雾气不能被批发。", "咀嚼": "配价：咀嚼要求有嘴的主体和食物作宾语，“雾气”不能咀嚼。"}, "sentence_index": 6, "correct_answer": "扩散"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她在新班级扩散了很多朋友。", "explanation": "这里应该用〈结交〉。扩散指东西向四周散布，结识朋友要用结交。"}, {"text": "我们在市中心扩散了一座新图书馆。", "explanation": "这里应该用〈建造〉。扩散指东西向四周散开，建造建筑要用建造。"}, {"text": "老板决定扩散一个新部门。", "explanation": "这里应该用〈设立〉。扩散强调向四周散开，设立机构、部门要用设立。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "墨水慢慢向扩散开了。", "corrected_sentence": "墨水慢慢扩散开了。", "error_description": "介词误用：“向”后须接处所宾语，不能直接放在动词“扩散”前，应删去“向”，说“墨水慢慢扩散开了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20662, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "蒸汽很快向四周很扩散了。", "corrected_sentence": "蒸汽很快向四周扩散了。", "error_description": "程度副词误用：“很”不能修饰动作动词“扩散”，应删去“很”，说“蒸汽很快向四周扩散了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ad51416c-eb5d-4259-86be-cae2a7259b6e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
