INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20668, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变成新的样子。", "primary_collocate": null, "pronunciation": "chóng sù", "ipa": "ʈʂʰʊŋ˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "这家公司想重塑自己的形象。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的教育可以重塑一个人的想法。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新技术重塑了我们的生活。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用三年时间重塑了自己的身体。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场比赛重塑了球队的信心。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "设计师想把老房子重塑成现代的样子。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市正在重塑自己的样子。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "互联网重塑了人们买东西的方式。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经过这次失败，他重塑了对工作的看法。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅行有时会重塑我们的看法。", "target_word": "重塑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "重塑了", "label": "体标（了）"}, {"form": "重塑着", "label": "体标（着）"}, {"form": "重塑过", "label": "体标（过）"}], "register": "中性", "sense_fingerprint": "重新塑造，使事物或想法变成新的样子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3365f9ac-881d-493f-88dc-1a13db791d52') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20668, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "重塑", "is_correct": true, "explanation": "正确：“重塑”指重新塑造，使公司的形象变成新的样子，与句意相符。"}, {"text": "购买", "is_correct": false, "explanation": "搭配：“购买”的对象是商品，不能说购买自己的形象。"}, {"text": "参观", "is_correct": false, "explanation": "语义：“参观”是到某处实地看，形象不能被去参观，句意不通。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的对象是食物，不能说吃自己的形象。"}], "explanations": {"重塑": "正确：“重塑”指重新塑造，使公司的形象变成新的样子，与句意相符。", "购买": "搭配：“购买”的对象是商品，不能说购买自己的形象。", "参观": "语义：“参观”是到某处实地看，形象不能被去参观，句意不通。", "吃": "搭配：“吃”的对象是食物，不能说吃自己的形象。"}, "sentence_index": 0, "correct_answer": "重塑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位画家重塑了一幅原创作品。", "explanation": "这里应该用〈创作〉。重塑指把已有的东西重新塑造成新样子，原创作品是从无到有，要用创作。"}, {"text": "我用三天重塑了那台坏掉的电脑。", "explanation": "这里应该用〈修理〉。重塑是改变事物的样子或形象，坏电脑要修好，应该用修理。"}, {"text": "学校重塑了一个新社团。", "explanation": "这里应该用〈创建〉。重塑是把已有事物改成新样子，新社团是从无到有成立的，要用创建。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20668, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "重塑", "is_correct": true, "explanation": "正确：“重塑”指重新塑造城市的样子，“正在”表示进行，与句意相符。"}, {"text": "具有", "is_correct": false, "explanation": "体貌：“具有”是状态动词，不表示进行，不能与“正在”搭配。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”的对象是食物，不能说吃自己的样子，句子不通。"}, {"text": "修葺", "is_correct": false, "explanation": "语域：“修葺”是书面词，多指修缮房屋建筑，不用来说城市的样子。"}], "explanations": {"重塑": "正确：“重塑”指重新塑造城市的样子，“正在”表示进行，与句意相符。", "具有": "体貌：“具有”是状态动词，不表示进行，不能与“正在”搭配。", "吃": "语义：“吃”的对象是食物，不能说吃自己的样子，句子不通。", "修葺": "语域：“修葺”是书面词，多指修缮房屋建筑，不用来说城市的样子。"}, "sentence_index": 6, "correct_answer": "重塑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂重塑了去年的产量。", "explanation": "这里应该用〈提高〉。产量是数字，改变产量的高低要用提高，重塑用于样子或形象。"}, {"text": "他在考试中重塑了成绩。", "explanation": "这里应该用〈取得〉。成绩是考试的结果，要说取得好成绩，重塑不能用于成绩。"}, {"text": "我们公司重塑了一个新部门。", "explanation": "这里应该用〈成立〉。新部门是从无到有设立的，要用成立，重塑指把已有事物改成新样子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20668, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们把旧仓库重塑了成文化空间。", "corrected_sentence": "他们把旧仓库重塑成了文化空间。", "error_description": "错误：“重塑了成”。结果补语“成”应紧跟动词“重塑”，“了”放在“成”之后，应写作“重塑成了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20668, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "明年，这座老城会重塑了自己的样子。", "corrected_sentence": "明年，这座老城会重塑自己的样子。", "error_description": "错误：“会重塑了”。“会”表示将来的动作，句中已有将来的意思，动态助词“了”不能用在“重塑”后，应写作“会重塑自己的样子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6b9e4da-c487-4ed1-b041-32c7a850e850') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
