INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20672, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做东西或买东西时花的钱。", "primary_collocate": null, "pronunciation": "chéng běn", "ipa": "ʈʂʰɤŋ˧˥ pən˨˩˦", "syllable_count": 2, "sentences": [{"text": "这家工厂想办法降低成本。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "原料贵了，成本也高了。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做这个蛋糕的成本不到十块钱。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板算了一下，每件衣服的成本是五十元。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成本太高，所以价格不能便宜。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他开店前先算好了房租和成本。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电费涨了，公司的成本也跟着涨了。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网上开店的成本比实体店低很多。", "target_word": "成本", "complexity_tier": "T3", "furigana": "wǎng shàng kāi diàn de chéng běn bǐ shí tǐ diàn dī hěn duō", "sentence_source": "generated"}, {"text": "为了节约成本，我们少用了一些纸。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件产品的成本和卖价差不多。", "target_word": "成本", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "生产成本", "label": "复合"}, {"form": "成本价", "label": "复合"}], "register": "中性", "sense_fingerprint": "生产或购买东西所花的费用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20672, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "成本", "is_correct": true, "explanation": "“成本”指生产或买卖所花的费用，可以被降低。"}, {"text": "工厂", "is_correct": false, "explanation": "配价：“降低”的对象应是数量或费用，“工厂”是地点实体，不能被降低。"}, {"text": "办法", "is_correct": false, "explanation": "搭配：“办法”是方式，不是能被“降低”的数量，应说“想办法”。"}, {"text": "天空", "is_correct": false, "explanation": "语义：“天空”是自然空间，不能被“降低”。"}], "explanations": {"成本": "“成本”指生产或买卖所花的费用，可以被降低。", "工厂": "配价：“降低”的对象应是数量或费用，“工厂”是地点实体，不能被降低。", "办法": "搭配：“办法”是方式，不是能被“降低”的数量，应说“想办法”。", "天空": "语义：“天空”是自然空间，不能被“降低”。"}, "sentence_index": 0, "correct_answer": "成本"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一个成本很高的人，大家都很喜欢他。", "explanation": "“成本”指生产或买卖所花的费用，不能用来形容人。"}, {"text": "这家店把成本卖给了顾客。", "explanation": "“卖”的对象应是商品，“成本”是花出去的钱，不能卖。"}, {"text": "这家公司今年靠成本赚了一千万元。", "explanation": "“赚”的应是收入或利润，“成本”是花出去的钱，不能用来赚钱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20672, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "成本", "is_correct": true, "explanation": "“成本”是生产经营的费用，电费上涨会使它跟着上涨。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是人的身体重量，公司没有体重，不能“涨了”。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”是气象状况，与“公司的……涨了”不搭。"}, {"text": "头发", "is_correct": false, "explanation": "体貌：“头发”是人身体的部位，公司没有头发，不能“涨了”。"}], "explanations": {"成本": "“成本”是生产经营的费用，电费上涨会使它跟着上涨。", "体重": "体貌：“体重”是人的身体重量，公司没有体重，不能“涨了”。", "天气": "语义：“天气”是气象状况，与“公司的……涨了”不搭。", "头发": "体貌：“头发”是人身体的部位，公司没有头发，不能“涨了”。"}, "sentence_index": 6, "correct_answer": "成本"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件产品的成本是红色的，很好看。", "explanation": "“成本”是一笔费用，没有颜色，不能说“红色的”。"}, {"text": "这件产品的成本很甜，顾客都很喜欢。", "explanation": "“成本”是钱，没有味道，不能说“很甜”。"}, {"text": "这件产品的成本很结实，用了三年还不坏。", "explanation": "“结实”形容物品的质地，不能用来形容“成本”（花出去的钱）；应说“产品很结实”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20672, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们投入了一只很大的成本。", "corrected_sentence": "我们投入了一笔很大的成本。", "error_description": "“成本”是抽象的钱款，量词应用“笔”；“只”用于动物等，不能用于“成本”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20672, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这件产品的成本的很低。", "corrected_sentence": "这件产品的成本很低。", "error_description": "“成本”作主语后面直接接谓语，“很低”前不能加“的”，应说“这件产品的成本很低”，多出的“的”不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
