INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20678, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "很多新东西突然一起出现。", "primary_collocate": null, "pronunciation": "yǒng xiàn", "ipa": "jʊŋ˨˩ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "雨停以后，路边涌现出很多小摊。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "天一黑，星星一下子涌现出来。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "下雪以后，街上突然涌现出许多卖热饮的人。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这首歌，过去的回忆一下子涌现在眼前。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机一发布，各种新功能的介绍就涌现了。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "春雨过后，山坡上涌现出一片片新绿。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游戏上线后，网上马上涌现出很多玩家的视频。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新规定一公布，各种问题便涌现出来。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，湖边突然涌现出许多萤火虫。", "target_word": "涌现", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师一提问，同学们的想法马上涌现出来。", "target_word": "涌现", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "涌现了", "label": "体标"}, {"form": "涌现过", "label": "体标"}], "register": "书面", "sense_fingerprint": "很多东西或景象在短时间内一下子冒出来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e32064-d416-4770-b286-114418f6799b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20678, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "涌现", "is_correct": true, "explanation": "「涌现」表示很多东西一下子冒出来，与「雨停以后」「路边」「很多小摊」搭配。"}, {"text": "挖出", "is_correct": false, "explanation": "搭配：「挖出」针对埋在地下的东西，小摊不是这样出现的。"}, {"text": "清出", "is_correct": false, "explanation": "语义：清出是清理掉，与小摊出现的句意相反。"}, {"text": "拆出", "is_correct": false, "explanation": "语义：拆出指拆卸零件，不能说把小摊拆出来，句意不通。"}], "explanations": {"涌现": "「涌现」表示很多东西一下子冒出来，与「雨停以后」「路边」「很多小摊」搭配。", "挖出": "搭配：「挖出」针对埋在地下的东西，小摊不是这样出现的。", "清出": "语义：清出是清理掉，与小摊出现的句意相反。", "拆出": "语义：拆出指拆卸零件，不能说把小摊拆出来，句意不通。"}, "sentence_index": 0, "correct_answer": "涌现"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "一个熟悉的声音突然涌现在我耳边。", "explanation": "这里应该用〈出现〉。涌现强调很多东西一下子同时冒出，只有一个声音时用〈出现〉。"}, {"text": "一只小猫突然涌现在窗台上。", "explanation": "这里应该用〈出现〉。涌现指很多东西一下子冒出，单个动物突然到来要用〈出现〉。"}, {"text": "雨停以后，路边的小摊一下子涌现得越来越少。", "explanation": "〈涌现〉表示很多东西突然一起冒出，不能用来描述数量越来越少，前后语义矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20678, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "涌现", "is_correct": true, "explanation": "「涌现」表示很多东西一下子大量出现，与「游戏上线后」「马上」「很多玩家的视频」搭配。"}, {"text": "删除", "is_correct": false, "explanation": "语义：删除是去掉，与「马上涌现出很多」的增加义相反。"}, {"text": "回收", "is_correct": false, "explanation": "搭配：「回收」多接废品，视频不能这样回收。"}, {"text": "清空", "is_correct": false, "explanation": "语义：清空指变没有，与「涌现出很多」的句意相矛盾。"}], "explanations": {"涌现": "「涌现」表示很多东西一下子大量出现，与「游戏上线后」「马上」「很多玩家的视频」搭配。", "删除": "语义：删除是去掉，与「马上涌现出很多」的增加义相反。", "回收": "搭配：「回收」多接废品，视频不能这样回收。", "清空": "语义：清空指变没有，与「涌现出很多」的句意相矛盾。"}, "sentence_index": 6, "correct_answer": "涌现"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师一下子涌现出几个优秀的同学。", "explanation": "这里应该用〈挑选〉。涌现的事物是自己冒出来的，没有施事者；老师主动选出学生要用〈挑选〉。"}, {"text": "这个小镇的人一下子涌现到了街上。", "explanation": "〈涌现〉指很多东西一下子冒出，不表示人向某处聚集，这里应该用〈涌向〉。"}, {"text": "春天一下子涌现了。", "explanation": "这里应该用〈降临〉。季节是到来，〈涌现〉强调很多东西一下子冒出，不能用于春天。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
