INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20678, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "考试一结束，同学们的疑问马上涌现进来。", "corrected_sentence": "考试一结束，同学们的疑问马上涌现出来。", "error_description": "错误：趋向补语错误。「涌现」后应接「出来」，「进来」表示由外向内，与句意不符。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20680, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "友谊", "is_correct": false, "explanation": "与「高效率」没有反义关系，「友谊」是人与人之间的情感，与做事快慢无关。"}, {"text": "音乐", "is_correct": false, "explanation": "与「高效率」没有反义关系，「音乐」是艺术形式，与做事效率无关。"}, {"text": "低效率", "is_correct": true, "explanation": "正确。「低效率」与「高效率」构成反义，指做事慢、浪费时间。"}, {"text": "海洋", "is_correct": false, "explanation": "与「高效率」没有反义关系，「海洋」是自然地理事物。"}], "correct_answer": "低效率", "explanations": {"友谊": "与「高效率」没有反义关系，「友谊」是人与人之间的情感，与做事快慢无关。", "音乐": "与「高效率」没有反义关系，「音乐」是艺术形式，与做事效率无关。", "低效率": "正确。「低效率」与「高效率」构成反义，指做事慢、浪费时间。", "海洋": "与「高效率」没有反义关系，「海洋」是自然地理事物。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
