INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20680, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做事情很快，不浪费时间。", "primary_collocate": null, "pronunciation": "gāo xiào lǜ", "ipa": "kau̯˥ ɕiau̯˥˩ ly˥˩", "syllable_count": 3, "sentences": [{"text": "她一向用高效率的方式做事。", "target_word": "高效率", "complexity_tier": "T3", "furigana": "gāo xiào lǜ", "sentence_source": "generated"}, {"text": "他做事从不拖，一直保持高效率。", "target_word": "高效率", "complexity_tier": "T3", "furigana": "gāo xiào lǜ", "sentence_source": "generated"}, {"text": "老师夸他总是用高效率的方法学习。", "target_word": "高效率", "complexity_tier": "T3", "furigana": "gāo xiào lǜ", "sentence_source": "generated"}, {"text": "高效率的人不会浪费时间。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想学会高效率地做家务。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈高效率地做好了晚饭。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "想要高效率，就要先做最重要的事。", "target_word": "高效率", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "小王用高效率的方法，一上午就写完了报告。", "target_word": "高效率", "complexity_tier": "T3", "furigana": "gāo xiào lǜ", "sentence_source": "generated"}, {"text": "他用高效率的方法整理房间，半小时就好了。", "target_word": "高效率", "complexity_tier": "T3", "furigana": "gāo xiào lǜ", "sentence_source": "generated"}, {"text": "她把时间分好，所以每天都能保持高效率。", "target_word": "高效率", "complexity_tier": "T3", "furigana": "gāo xiào lǜ", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "做事快且不浪费时间", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ca8732c7-e609-4f0d-a53d-cb81e17c8e1e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20680, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "游戏", "is_correct": false, "explanation": "语义：「用游戏的方式做事」是把事情当玩乐，与「做事很快、不浪费时间」的意思相反。"}, {"text": "高效率", "is_correct": true, "explanation": "正确。「高效率的方式」指做事快、不浪费时间，与句意相符。"}, {"text": "拖延", "is_correct": false, "explanation": "语义：「拖延的方式」与「做事很快」的意思相反。"}, {"text": "懒散", "is_correct": false, "explanation": "语义：「懒散」指做事松散、不紧凑，与「高效率」的意思相反。"}], "explanations": {"游戏": "语义：「用游戏的方式做事」是把事情当玩乐，与「做事很快、不浪费时间」的意思相反。", "高效率": "正确。「高效率的方式」指做事快、不浪费时间，与句意相符。", "拖延": "语义：「拖延的方式」与「做事很快」的意思相反。", "懒散": "语义：「懒散」指做事松散、不紧凑，与「高效率」的意思相反。"}, "sentence_index": 0, "correct_answer": "高效率"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他这次跑步的高效率很快。", "explanation": "这里应该用〈速度〉。高效率指做事快且不浪费时间，跑步的快慢要用「速度」。"}, {"text": "这台机器的高效率很长。", "explanation": "这里应该用〈寿命〉。高效率指做事快、不浪费时间，机器能用多久要用「寿命」。"}, {"text": "这幅画的高效率很鲜艳。", "explanation": "这里应该用〈颜色〉。高效率指做事快、不浪费时间，画面的色彩要用「颜色」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20680, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浪费", "is_correct": false, "explanation": "语义：想要「浪费」，就不会先做最重要的事，与后半句矛盾。"}, {"text": "高效率", "is_correct": true, "explanation": "正确。「想要高效率」指想做事快、不浪费时间，与「先做最重要的事」相符。"}, {"text": "慌张", "is_correct": false, "explanation": "语义：「慌张」是忙乱不安，与「做事快、不浪费时间」的劝导意思不符，句子说不通。"}, {"text": "发呆", "is_correct": false, "explanation": "语义：「发呆」是不做事，与「先做最重要的事」矛盾。"}], "explanations": {"浪费": "语义：想要「浪费」，就不会先做最重要的事，与后半句矛盾。", "高效率": "正确。「想要高效率」指想做事快、不浪费时间，与「先做最重要的事」相符。", "慌张": "语义：「慌张」是忙乱不安，与「做事快、不浪费时间」的劝导意思不符，句子说不通。", "发呆": "语义：「发呆」是不做事，与「先做最重要的事」矛盾。"}, "sentence_index": 6, "correct_answer": "高效率"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他这个月的高效率是五千元。", "explanation": "这里应该用〈工资〉。高效率指做事快、不浪费时间，每月拿到的钱要用「工资」。"}, {"text": "这家公司的高效率是每股五十元。", "explanation": "这里应该用〈股价〉。高效率指做事快、不浪费时间，一股股票的价格要用「股价」。"}, {"text": "这次工程的高效率很长。", "explanation": "这里应该用〈工期〉。高效率指做事快、不浪费时间，从开工到完工所用的时间要用「工期」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20680, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他用高效率地方式读书。", "corrected_sentence": "他用高效率的方式读书。", "error_description": "错误：修饰名词「方式」时应用「的」，不能用「地」。「地」修饰动词，「高效率的方式」才正确。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20680, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她写作业时一直保持一个高效率，很少出错。", "corrected_sentence": "她写作业时一直保持高效率，很少出错。", "error_description": "错误：「高效率」是抽象名词，前面不能直接加数量词「一个」计量。正确：去掉「一个」，写作「一直保持高效率」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ee1813ad-4e9b-4dea-8c46-1fd73d6115f0') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
