INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20688, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "市井就是人们住在一起、买东西和聊天的地方。", "primary_collocate": null, "pronunciation": "shì jǐng", "ipa": "ʂɻ̩˥˩ tɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "市井是人们买东西、聊天的地方。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我喜欢在市井里走一走，看大家买菜聊天。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条老街是一个热闹的市井。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市井里的人见面就打招呼。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "早上的市井里，摊贩吆喝，人们挑菜聊天。", "target_word": "市井", "complexity_tier": "T3", "furigana": "shì jǐng", "sentence_source": "generated"}, {"text": "奶奶住在市井里，邻居都很熟。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "傍晚的市井里，大人聊天，小孩玩耍。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个小镇的市井很安静，没有大商场。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在市井里挑了几样新鲜的水果。", "target_word": "市井", "complexity_tier": "T3", "furigana": "shì jǐng", "sentence_source": "generated"}, {"text": "外国游客想看真正的市井，就来这条街。", "target_word": "市井", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "市井生活", "label": "复合"}, {"form": "市井小民", "label": "复合"}], "register": "书面", "sense_fingerprint": "人们聚居、买东西、聊天的热闹地方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd7e32064-d416-4770-b286-114418f6799b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20688, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市井", "is_correct": true, "explanation": "正确：市井指人们聚居、买东西、聊天的地方，与定义相符。"}, {"text": "医院", "is_correct": false, "explanation": "语义：医院是看病的地方，不是人们买东西、聊天的场所。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校是学习的场所，与“买东西”的功能不符。"}, {"text": "课堂", "is_correct": false, "explanation": "搭配：“买东西”的场所多指街市或店铺，课堂不能用来买东西。"}], "explanations": {"市井": "正确：市井指人们聚居、买东西、聊天的地方，与定义相符。", "医院": "语义：医院是看病的地方，不是人们买东西、聊天的场所。", "学校": "语义：学校是学习的场所，与“买东西”的功能不符。", "课堂": "搭配：“买东西”的场所多指街市或店铺，课堂不能用来买东西。"}, "sentence_index": 0, "correct_answer": "市井"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的市井见面就打招呼。", "explanation": "这里应该用〈邻居〉。市井指地方，不指人，说人见面要用“邻居”。"}, {"text": "我们去市井打了一桶水。", "explanation": "这里应该用〈水井〉。市井指人们买东西、聊天的地方，不是取水的井，打水应说“水井”。"}, {"text": "我们在市井里看完了一场电影。", "explanation": "这里应该用〈电影院〉。市井指人们买东西、聊天的地方，不放映电影，看电影应说“电影院”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20688, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市井", "is_correct": true, "explanation": "正确：市井指街市，傍晚时大人聊天、小孩玩耍，与句意相符。"}, {"text": "手术室", "is_correct": false, "explanation": "语义：手术室是做手术的地方，大人聊天、小孩玩耍与之不符。"}, {"text": "墓园", "is_correct": false, "explanation": "语义：墓园是安葬逝者的地方，不适合小孩玩耍。"}, {"text": "考场", "is_correct": false, "explanation": "语义：考场是考试的地方，大人聊天、小孩玩耍与之不符。"}], "explanations": {"市井": "正确：市井指街市，傍晚时大人聊天、小孩玩耍，与句意相符。", "手术室": "语义：手术室是做手术的地方，大人聊天、小孩玩耍与之不符。", "墓园": "语义：墓园是安葬逝者的地方，不适合小孩玩耍。", "考场": "语义：考场是考试的地方，大人聊天、小孩玩耍与之不符。"}, "sentence_index": 6, "correct_answer": "市井"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们一起在市井里上了一下午课。", "explanation": "这里应该用〈教室〉。市井指人们买东西、聊天的地方，不是上课的场所，上课应说“教室”。"}, {"text": "市井里摆满了病床，医生来来往往。", "explanation": "这里应该用〈医院〉。市井指人们买东西、聊天的地方，摆满病床、医生来往的地方应说“医院”。"}, {"text": "他穿了一件市井色的衬衫。", "explanation": "这里应该用〈蓝色〉。市井指地方，不是颜色，衬衫的颜色应说“蓝色”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20688, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老人们市井里聊天。", "corrected_sentence": "老人们在市井里聊天。", "error_description": "错误：表示地点的“市井里”前漏掉了介词“在”。正确应为“在市井里聊天”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20688, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们市井里买了几样新鲜的菜。", "corrected_sentence": "我们在市井里买了几样新鲜的菜。", "error_description": "错误：表示地点的“市井里”前漏掉了介词“在”。正确应为“在市井里买了几样新鲜的菜”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b078b63d-92a2-49a9-a2da-8f8f9546efa3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
