INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20700, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "做买卖的人，比如卖东西的人。", "primary_collocate": null, "pronunciation": "shāng rén", "ipa": "ʂɑŋ˥ ɻən˧˥", "syllable_count": 2, "sentences": [{"text": "我爸爸是商人，每天都要进货和卖货。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "街上有一个商人在卖水果。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人对客人说：“今天打八折。”", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人把货物放在车上。", "target_word": "商人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "老商人很会讲价。", "target_word": "商人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位商人从国外买了很多衣服。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人赚了钱，就给孩子买礼物。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "古城里到处都是商人。", "target_word": "商人", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "那个商人每天早上五点就起床。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商人说这种茶叶很好卖。", "target_word": "商人", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "商人们", "label": "复合"}], "register": "中性", "sense_fingerprint": "做买卖、卖东西的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93755cc4-9c9f-4da2-a21c-6c25fdf039d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20700, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确答案。商人指做买卖、卖东西的人。"}, {"text": "山人", "is_correct": false, "explanation": "shān（第一声）与 shāng（第一声）只差韵尾（an 与 ang），山人指隐居山林的人。"}, {"text": "生人", "is_correct": false, "explanation": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指陌生人。"}, {"text": "上任", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声调不同，rèn（第四声）与 rén（第二声）声调也不同，上任指就职。"}], "explanations": {"商人": "正确答案。商人指做买卖、卖东西的人。", "山人": "shān（第一声）与 shāng（第一声）只差韵尾（an 与 ang），山人指隐居山林的人。", "生人": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指陌生人。", "上任": "shàng（第四声）与 shāng（第一声）声调不同，rèn（第四声）与 rén（第二声）声调也不同，上任指就职。"}, "sentence_index": null, "correct_answer": "商人"}, "level_3": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确。「我爸爸是商人」说明他的职业是做买卖，与「进货和卖货」一致。"}, {"text": "医生", "is_correct": false, "explanation": "语义：医生是治病的人，与「进货和卖货」的句意不符。"}, {"text": "教师", "is_correct": false, "explanation": "语义：教师的职业与「进货和卖货」无关，句意不通。"}, {"text": "工程师", "is_correct": false, "explanation": "搭配：「进货和卖货」不能与工程师搭配，工程师不以做买卖为职业。"}], "explanations": {"商人": "正确。「我爸爸是商人」说明他的职业是做买卖，与「进货和卖货」一致。", "医生": "语义：医生是治病的人，与「进货和卖货」的句意不符。", "教师": "语义：教师的职业与「进货和卖货」无关，句意不通。", "工程师": "搭配：「进货和卖货」不能与工程师搭配，工程师不以做买卖为职业。"}, "sentence_index": 0, "correct_answer": "商人"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "商人在教室里给小学生上语文课。", "explanation": "这里应该用〈老师〉。「商人」指做买卖的人，给小学生上语文课是老师的工作。"}, {"text": "商人在手术室里给病人做手术。", "explanation": "这里应该用〈医生〉。「商人」指做买卖的人，给病人做手术是医生的工作。"}, {"text": "商人在工厂里操作机器。", "explanation": "这里应该用〈工人〉。「商人」指做买卖的人，在工厂里操作机器是工人的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20700, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确答案。商人指做买卖、卖东西的人。"}, {"text": "上人", "is_correct": false, "explanation": "shàng（第四声）与 shāng（第一声）声母韵母相同，只差声调；上人是佛教对高僧的尊称。"}, {"text": "杀人", "is_correct": false, "explanation": "shā（第一声）与 shāng（第一声）韵母不同（少了 ng），杀人指伤害他人性命。"}, {"text": "生人", "is_correct": false, "explanation": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指不认识的人。"}], "explanations": {"商人": "正确答案。商人指做买卖、卖东西的人。", "上人": "shàng（第四声）与 shāng（第一声）声母韵母相同，只差声调；上人是佛教对高僧的尊称。", "杀人": "shā（第一声）与 shāng（第一声）韵母不同（少了 ng），杀人指伤害他人性命。", "生人": "shēng（第一声）与 shāng（第一声）韵母不同（eng 与 ang），生人指不认识的人。"}, "sentence_index": null, "correct_answer": "商人"}, "level_3": {"options": [{"text": "商人", "is_correct": true, "explanation": "正确。「商人赚了钱」符合人做买卖的常理，「给孩子买礼物」也与人的行为相符。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能赚钱，句意不通。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不能赚钱，也无法给孩子买礼物。"}, {"text": "小鸟", "is_correct": false, "explanation": "搭配：「赚钱」的主语应是人，小鸟不能赚钱买礼物。"}], "explanations": {"商人": "正确。「商人赚了钱」符合人做买卖的常理，「给孩子买礼物」也与人的行为相符。", "石头": "语义：石头不能赚钱，句意不通。", "窗户": "语义：窗户不能赚钱，也无法给孩子买礼物。", "小鸟": "搭配：「赚钱」的主语应是人，小鸟不能赚钱买礼物。"}, "sentence_index": 6, "correct_answer": "商人"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "商人每天给病人量体温。", "explanation": "这里应该用〈护士〉。「商人」指做买卖的人，给病人量体温是护士的工作。"}, {"text": "商人在派出所里审问嫌疑人。", "explanation": "这里应该用〈警察〉。「商人」指做买卖的人，审问嫌疑人是警察的工作。"}, {"text": "商人在法庭上宣判被告有罪。", "explanation": "这里应该用〈法官〉。「商人」指做买卖的人，宣判被告有罪是法官的工作。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20700, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "一头商人赶着驴车进城卖货。", "corrected_sentence": "一个商人赶着驴车进城卖货。", "error_description": "量词错误：「头」多用于牲畜，指人应用「个」或「位」，正确说法是「一个商人」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20700, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那个商人们每天在街角开店。", "corrected_sentence": "那个商人每天在街角开店。", "error_description": "复数错误：「那个」表示单数，商人后面不能加「们」，正确说法是「那个商人」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "狭窄", "is_correct": true, "explanation": "狭窄：范围小，与“广泛”在范围大小上形成反义。"}, {"text": "明显", "is_correct": false, "explanation": "明显指容易看出，与“广泛”的范围大小无关，没有反义关系。"}, {"text": "复杂", "is_correct": false, "explanation": "复杂指结构或情况多而乱，与“广泛”没有反义关系。"}, {"text": "漫长", "is_correct": false, "explanation": "漫长形容时间长，与“广泛”的范围含义无关。"}], "correct_answer": "狭窄", "explanations": {"狭窄": "狭窄：范围小，与“广泛”在范围大小上形成反义。", "明显": "明显指容易看出，与“广泛”的范围大小无关，没有反义关系。", "复杂": "复杂指结构或情况多而乱，与“广泛”没有反义关系。", "漫长": "漫长形容时间长，与“广泛”的范围含义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
