INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "表示范围很大，比如很多人或很多地方。", "primary_collocate": null, "pronunciation": "guǎng fàn", "ipa": "kwɑŋ˨˩ fan˥˩", "syllable_count": 2, "sentences": [{"text": "这本书受到广泛的欢迎。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的兴趣很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个问题引起了广泛的关注。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机的使用非常广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的朋友很多，来源也很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种方法在学校里应用广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读书很广泛，什么都看。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个消息传得很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家对这件事有广泛的讨论。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的商品种类很广泛。", "target_word": "广泛", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "广泛地", "label": "副词形式"}, {"form": "广泛性", "label": "复合"}, {"form": "廣泛", "label": "繁体"}], "register": "书面", "sense_fingerprint": "广泛：涉及的范围很大，人多、地方多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5845f11-6b3d-4f3d-90b8-a89f81eb4318') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "广泛", "is_correct": true, "explanation": "广泛：涉及的人多、范围大，修饰“欢迎”，指很多人欢迎。"}, {"text": "陡峭", "is_correct": false, "explanation": "语义：“陡峭”形容地势，不能修饰“欢迎”。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：“寒冷”指温度低，与“欢迎”的含义相悖。"}, {"text": "沉重", "is_correct": false, "explanation": "搭配：“欢迎”是一种态度，“沉重”不能与之搭配，句意不通。"}], "explanations": {"广泛": "广泛：涉及的人多、范围大，修饰“欢迎”，指很多人欢迎。", "陡峭": "语义：“陡峭”形容地势，不能修饰“欢迎”。", "寒冷": "语义：“寒冷”指温度低，与“欢迎”的含义相悖。", "沉重": "搭配：“欢迎”是一种态度，“沉重”不能与之搭配，句意不通。"}, "sentence_index": 0, "correct_answer": "广泛"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这间教室很广泛。", "explanation": "这里应该用〈宽敞〉。广泛指涉及的人或事物范围大，不用来形容房间等空间的面积。"}, {"text": "这片草原非常广泛。", "explanation": "这里应该用〈辽阔〉。辽阔形容地域广大，广泛不用来描述土地的面积。"}, {"text": "这个操场十分广泛。", "explanation": "这里应该用〈宽阔〉。宽阔形容空间面积大，广泛不能用于形容操场。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "广泛", "is_correct": true, "explanation": "广泛：涉及的范围大，与“什么都看”相合。"}, {"text": "炎热", "is_correct": false, "explanation": "语义：“炎热”指气温高，不能描述读书的范围。"}, {"text": "漆黑", "is_correct": false, "explanation": "语义：“漆黑”形容颜色或光线，与读书的范围无关。"}, {"text": "嘈杂", "is_correct": false, "explanation": "搭配：“嘈杂”多形容环境或声音，不用来形容人读书。"}], "explanations": {"广泛": "广泛：涉及的范围大，与“什么都看”相合。", "炎热": "语义：“炎热”指气温高，不能描述读书的范围。", "漆黑": "语义：“漆黑”形容颜色或光线，与读书的范围无关。", "嘈杂": "搭配：“嘈杂”多形容环境或声音，不用来形容人读书。"}, "sentence_index": 6, "correct_answer": "广泛"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他对这件事的印象很广泛。", "explanation": "这里应该用〈深刻〉。广泛说的是范围大，“印象”说的是程度深，要用深刻。"}, {"text": "他的脾气很广泛。", "explanation": "这里应该用〈大〉。广泛说的是范围大，脾气的程度要用“大”来说。"}, {"text": "他对家乡的思念很广泛。", "explanation": "这里应该用〈深切〉。广泛说的是涉及的范围，思念的程度要用深切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事引起了广泛地注意。", "corrected_sentence": "这件事引起了广泛的注意。", "error_description": "错误：“广泛”修饰名词“注意”，应用“的”，不能用“地”。“地”用于修饰动词，应为“广泛的注意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20704, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的爱好很的广泛，常常去看展览。", "corrected_sentence": "他的爱好很广泛，常常去看展览。", "error_description": "错误：“很”后不能接“的”再接形容词。“很”直接修饰“广泛”，应去掉“的”，说“很广泛”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd82c5768-3d76-4297-9c5d-b77284203304') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间接", "is_correct": true, "explanation": "与“直接”构成反义：“直接”指不经过中间环节，“间接”指经过中间环节。"}, {"text": "非常", "is_correct": false, "explanation": "与“直接”无反义关系，“非常”表示程度高。"}, {"text": "已经", "is_correct": false, "explanation": "与“直接”无反义关系，“已经”表示时间上已完成。"}, {"text": "突然", "is_correct": false, "explanation": "与“直接”无反义关系，“突然”表示出乎意料地发生。"}], "correct_answer": "间接", "explanations": {"间接": "与“直接”构成反义：“直接”指不经过中间环节，“间接”指经过中间环节。", "非常": "与“直接”无反义关系，“非常”表示程度高。", "已经": "与“直接”无反义关系，“已经”表示时间上已完成。", "突然": "与“直接”无反义关系，“突然”表示出乎意料地发生。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "间接", "is_correct": true, "explanation": "与“直接”构成反义：“直接”指不经过中间环节，“间接”指经过中间环节。"}, {"text": "逐渐", "is_correct": false, "explanation": "与“直接”无反义关系，“逐渐”表示渐进。"}, {"text": "十分", "is_correct": false, "explanation": "与“直接”无反义关系，“十分”表示程度。"}, {"text": "一定", "is_correct": false, "explanation": "与“直接”无反义关系，“一定”表示确定。"}], "correct_answer": "间接", "explanations": {"间接": "与“直接”构成反义：“直接”指不经过中间环节，“间接”指经过中间环节。", "逐渐": "与“直接”无反义关系，“逐渐”表示渐进。", "十分": "与“直接”无反义关系，“十分”表示程度。", "一定": "与“直接”无反义关系，“一定”表示确定。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不绕弯子。", "primary_collocate": null, "pronunciation": "zhí jiē", "ipa": "ʈʂɻ̩˧˥ tɕjɛ˥", "syllable_count": 2, "sentences": [{"text": "有问题就直接说，别不好意思。", "target_word": "直接", "complexity_tier": "T3", "furigana": "yǒu wèn tí jiù zhí jiē shuō, bié bù hǎo yì si。", "sentence_source": "generated"}, {"text": "他说话很直接，有什么说什么。", "target_word": "直接", "complexity_tier": "T3", "furigana": "tā shuō huà hěn zhí jiē, yǒu shénme shuō shénme。", "sentence_source": "generated"}, {"text": "你可以直接说，不用客气。", "target_word": "直接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "咱们别绕弯子，直接说吧。", "target_word": "直接", "complexity_tier": "T3", "furigana": "zán men bié rào wān zi, zhí jiē shuō ba。", "sentence_source": "generated"}, {"text": "他没有直接回答我的问题。", "target_word": "直接", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我直接说吧，你的方案不太行。", "target_word": "直接", "complexity_tier": "T3", "furigana": "wǒ zhí jiē shuō ba, nǐ de fāng àn bú tài xíng。", "sentence_source": "generated"}, {"text": "他问得很直接，让我有点尴尬。", "target_word": "直接", "complexity_tier": "T3", "furigana": "tā wèn de hěn zhí jiē, ràng wǒ yǒu diǎn gān gà。", "sentence_source": "generated"}, {"text": "你有意见就直接提，别藏在心里。", "target_word": "直接", "complexity_tier": "T3", "furigana": "nǐ yǒu yì jiàn jiù zhí jiē tí, bié cáng zài xīn lǐ。", "sentence_source": "generated"}, {"text": "他的回答很直接，让人印象深刻。", "target_word": "直接", "complexity_tier": "T3", "furigana": "tā de huí dá hěn zhí jiē, ràng rén yìn xiàng shēn kè。", "sentence_source": "generated"}, {"text": "她直接说出了自己的想法。", "target_word": "直接", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "不经过中间环节，不绕弯子，径直做某事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "直接", "is_correct": true, "explanation": "“有问题就直接说”表示不绕弯子地说，能正确填入空格。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示已完成，与“有问题就”的假设相矛盾。"}, {"text": "从来", "is_correct": false, "explanation": "语义：“从来”表示从未如此，与“有问题就”的假设不搭。"}, {"text": "仍然", "is_correct": false, "explanation": "搭配：“仍然”要接已成立的状态，不能接“有问题就”这样的假设。"}], "explanations": {"直接": "“有问题就直接说”表示不绕弯子地说，能正确填入空格。", "已经": "语义：“已经”表示已完成，与“有问题就”的假设相矛盾。", "从来": "语义：“从来”表示从未如此，与“有问题就”的假设不搭。", "仍然": "搭配：“仍然”要接已成立的状态，不能接“有问题就”这样的假设。"}, "sentence_index": 0, "correct_answer": "直接"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他通过朋友直接认识了她。", "explanation": "这里应该用〈间接〉。“通过朋友”说明经过了中间人，与“直接”矛盾。"}, {"text": "我们直接工作到了晚上。", "explanation": "这里应该用〈一直〉。“直接”指不经过中间环节，不能表示持续，持续要用“一直”。"}, {"text": "他委婉地直接拒绝了我的邀请。", "explanation": "这里应该用〈含蓄〉。“直接”指说话不绕弯子，与“含蓄”的表达方式相反，不能用来修饰“拒绝”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "直接", "is_correct": true, "explanation": "“问得很直接”指问话不绕弯子，能正确填入空格。"}, {"text": "亲切", "is_correct": false, "explanation": "语义：“亲切”表示态度温和，与“让我有点尴尬”的语境不搭。"}, {"text": "温和", "is_correct": false, "explanation": "语义：“温和”表示性子柔和，与“让我有点尴尬”的语境不搭。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”形容环境或状态，不能用来修饰“问得”的方式。"}], "explanations": {"直接": "“问得很直接”指问话不绕弯子，能正确填入空格。", "亲切": "语义：“亲切”表示态度温和，与“让我有点尴尬”的语境不搭。", "温和": "语义：“温和”表示性子柔和，与“让我有点尴尬”的语境不搭。", "安静": "搭配：“安静”形容环境或状态，不能用来修饰“问得”的方式。"}, "sentence_index": 6, "correct_answer": "直接"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他经过三次转手，直接买到了这本书。", "explanation": "这里应该用〈辗转〉。“经过三次转手”说明有中间环节，与“直接”矛盾。"}, {"text": "他拐弯抹角，直接说出了想法。", "explanation": "这里应该用〈含蓄〉。“直接”指不绕弯子、直说，与“含蓄”的说话方式相反，两者不能描述同一次说话。"}, {"text": "她含蓄地直接说出了想法。", "explanation": "这里的“直接”指不绕弯子，与“含蓄”的说法相反，两者不能同时修饰“说出”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我直接直接告诉你吧。", "corrected_sentence": "我直接告诉你吧。", "error_description": "重复错误：副词“直接”只需用一次，不能连续重复。正确说法：我直接告诉你吧。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20706, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他直接了给我答案。", "corrected_sentence": "他直接给了我答案。", "error_description": "体标错误：副词“直接”后面不能直接接“了”。“了”应放在动词“给”后面。正确说法：他直接给了我答案。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
