INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20714, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "教义就是宗教告诉人们要相信的道理。", "primary_collocate": null, "pronunciation": "jiào yì", "ipa": "tɕjɑʊ˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "教义告诉信徒要爱人，也要宽容。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小听家人讲教义，所以很相信。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教堂里的神父正在讲教义。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座寺庙里挂着写有教义的牌子。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们在周末学习教义。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读完了整本书，才明白这个宗教的教义。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条教义要求信徒每天祈祷。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教徒们相信教义，也按教义生活。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人把教义讲给了年轻的信徒。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对教义很好奇，问了许多问题。", "target_word": "教义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一条教义", "label": "量词：条"}, {"form": "教义学", "label": "复合"}], "register": "书面", "sense_fingerprint": "宗教告诉人们要相信的道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44487a15-d41b-418d-9679-5307425a1f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20714, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "教义", "is_correct": true, "explanation": "正确。教义指宗教告诉人们要相信的道理。"}, {"text": "交易", "is_correct": false, "explanation": "「jiāo（第一声）与 jiào 声调不同，意思是买卖、交易」。"}, {"text": "教育", "is_correct": false, "explanation": "「教育的第二个音节是 yù，与 yì 韵母不同，意思是培养人才的活动」。"}, {"text": "效益", "is_correct": false, "explanation": "「xiào 与 jiào 声母不同（x 与 j），意思是收益、成效」。"}], "explanations": {"教义": "正确。教义指宗教告诉人们要相信的道理。", "交易": "「jiāo（第一声）与 jiào 声调不同，意思是买卖、交易」。", "教育": "「教育的第二个音节是 yù，与 yì 韵母不同，意思是培养人才的活动」。", "效益": "「xiào 与 jiào 声母不同（x 与 j），意思是收益、成效」。"}, "sentence_index": null, "correct_answer": "教义"}, "level_3": {"options": [{"text": "教义", "is_correct": true, "explanation": "正确。「告诉信徒要爱人，也要宽容」说的是宗教传达的道理，教义符合。"}, {"text": "地图", "is_correct": false, "explanation": "语义：地图不能向信徒传达道理，与宗教内容无关。"}, {"text": "价格", "is_correct": false, "explanation": "语义：价格不能传达「要爱人、要宽容」这样的道理。"}, {"text": "车票", "is_correct": false, "explanation": "搭配：「告诉」的主语应是能传达道理的事物，车票不能用于此。"}], "explanations": {"教义": "正确。「告诉信徒要爱人，也要宽容」说的是宗教传达的道理，教义符合。", "地图": "语义：地图不能向信徒传达道理，与宗教内容无关。", "价格": "语义：价格不能传达「要爱人、要宽容」这样的道理。", "车票": "搭配：「告诉」的主语应是能传达道理的事物，车票不能用于此。"}, "sentence_index": 0, "correct_answer": "教义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次失败给了我一个深刻的教义，我永远记得。", "explanation": "这里应该用〈教训〉。教训指从失败或挫折中得到的启示；教义是宗教或学说的基本主张，不能指个人从失败中得到的启示。"}, {"text": "这些年的教学让我积累了宝贵的教义。", "explanation": "这里应该用〈经验〉。经验指从实践中积累的知识和体会；教义是宗教或学说的基本主张，不能指教学中积累的知识。"}, {"text": "这座城市的教义很有特色。", "explanation": "这里应该用〈文化〉。文化指地区的风俗、艺术等，教义专指宗教或学说的主张，不能形容城市的特色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20714, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "教义", "is_correct": true, "explanation": "正确。「要求信徒每天祈祷」是宗教的规定，只有教义符合。"}, {"text": "河", "is_correct": false, "explanation": "语义：河不是宗教的规定，不能要求信徒做任何事。"}, {"text": "路", "is_correct": false, "explanation": "配价：「要求」需要有意愿的主体，路不能提出要求。"}, {"text": "鱼", "is_correct": false, "explanation": "语义：鱼既不是规定，也不能要求信徒祈祷，与语境不符。"}], "explanations": {"教义": "正确。「要求信徒每天祈祷」是宗教的规定，只有教义符合。", "河": "语义：河不是宗教的规定，不能要求信徒做任何事。", "路": "配价：「要求」需要有意愿的主体，路不能提出要求。", "鱼": "语义：鱼既不是规定，也不能要求信徒祈祷，与语境不符。"}, "sentence_index": 6, "correct_answer": "教义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听完讲座，心里有很多教义。", "explanation": "这里应该用〈体会〉。体会指听讲或经历后形成的感受和认识；教义是宗教或学说的基本主张，不能指个人的感受。"}, {"text": "他从工作中得到了很多教义。", "explanation": "这里应该用〈收获〉。收获指从劳动或经历中得到的成果；教义不能说从工作中得到。"}, {"text": "这次长途旅行的教义让他终身难忘。", "explanation": "这里应该用〈经历〉。经历指亲身遭遇过的事情；教义是宗教或学说的基本主张，不能指旅行中的遭遇。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20714, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只教义我一直记得。", "corrected_sentence": "那条教义我一直记得。", "error_description": "量词错误：这里应用量词「条」，「只」不能修饰教义。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20714, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他教义相信上帝。", "corrected_sentence": "他按教义相信上帝。", "error_description": "错误：“教义”是名词，不能直接作状语修饰动词，需用介词“按”引出，此处缺少“按”，应说“按教义相信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
