INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把东西一点一点加起来。", "primary_collocate": null, "pronunciation": "jī lěi", "ipa": "tɕi˥ leɪ˨˩˦", "syllable_count": 2, "sentences": [{"text": "学汉语要一点一点积累词语。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在工作中积累了很多经验。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天积累几个新词。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就积累了不少知识。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱要慢慢积累，不能着急。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多读书，才能积累知识。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司积累了二十年的经验。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多听多说，才能积累语言经验。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一直在积累写作的材料。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把读过的好句子都积累起来。", "target_word": "积累", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "积累了", "label": "体标"}, {"form": "积累着", "label": "体标"}, {"form": "积累过", "label": "体标"}, {"form": "積累", "label": "繁体"}], "register": "中性", "sense_fingerprint": "经验、知识、财富等一点一点地聚集起来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "积累", "is_correct": true, "explanation": "正确答案：积累 jī lěi，指经验、知识等一点一点聚集起来。"}, {"text": "机理", "is_correct": false, "explanation": "lǐ 与 lěi 韵母不同（少一个 e），意思是事物内在的道理、机制。"}, {"text": "鸡类", "is_correct": false, "explanation": "lèi（第四声）与 lěi（第三声）声调不同，意思是鸡的种类。"}, {"text": "几类", "is_correct": false, "explanation": "jǐ（第三声）与 jī（第一声）声调不同，lèi 与 lěi 声调也不同，意思是几种类别。"}, {"text": "极累", "is_correct": false, "explanation": "jí（第二声）与 jī（第一声）声调不同，意思是非常疲劳。"}], "explanations": {"积累": "正确答案：积累 jī lěi，指经验、知识等一点一点聚集起来。", "机理": "lǐ 与 lěi 韵母不同（少一个 e），意思是事物内在的道理、机制。", "鸡类": "lèi（第四声）与 lěi（第三声）声调不同，意思是鸡的种类。", "几类": "jǐ（第三声）与 jī（第一声）声调不同，lèi 与 lěi 声调也不同，意思是几种类别。", "极累": "jí（第二声）与 jī（第一声）声调不同，意思是非常疲劳。"}, "sentence_index": null, "correct_answer": "积累"}, "level_3": {"options": [{"text": "积累", "is_correct": true, "explanation": "“积累词语”指词语一点一点地聚集起来，与“一点一点”相符。"}, {"text": "拍摄", "is_correct": false, "explanation": "语义：“拍摄”指用镜头记录影像，不能用于“词语”。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”的对象是植物或土地，不能说“浇灌词语”。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：“打扫”的对象是场所或物品表面，不能用于“词语”。"}], "explanations": {"积累": "“积累词语”指词语一点一点地聚集起来，与“一点一点”相符。", "拍摄": "语义：“拍摄”指用镜头记录影像，不能用于“词语”。", "浇灌": "搭配：“浇灌”的对象是植物或土地，不能说“浇灌词语”。", "打扫": "搭配：“打扫”的对象是场所或物品表面，不能用于“词语”。"}, "sentence_index": 0, "correct_answer": "积累"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今年这个城市的人口积累了十万。", "explanation": "这里应该用〈增加〉。积累指经验、知识、财富等逐渐聚集，人口数量的变化要用“增加”。"}, {"text": "他昨天积累了一场车祸。", "explanation": "这里应该用〈经历〉。积累指一点点聚集，车祸是突发的一次事件，不能说“积累”，要说“经历”。"}, {"text": "他上周积累了一支钢笔。", "explanation": "这里应该用〈买〉。积累指一点点聚集，买一支钢笔是一次性的行为，不能说“积累”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "积累", "is_correct": true, "explanation": "“积累了二十年的经验”指经验逐年聚集，能正确填入空格。"}, {"text": "喝", "is_correct": false, "explanation": "搭配：“喝”的对象是液体，不能说“喝了二十年的经验”。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”指修复器物，与“经验”不搭。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”的对象是表面，不能说“擦了二十年的经验”。"}], "explanations": {"积累": "“积累了二十年的经验”指经验逐年聚集，能正确填入空格。", "喝": "搭配：“喝”的对象是液体，不能说“喝了二十年的经验”。", "修理": "语义：“修理”指修复器物，与“经验”不搭。", "擦": "搭配：“擦”的对象是表面，不能说“擦了二十年的经验”。"}, "sentence_index": 6, "correct_answer": "积累"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他积累了一封信。", "explanation": "这里应该用〈写〉。积累指一点点聚集，不能用来说“写一封信”。"}, {"text": "他积累了一场比赛。", "explanation": "这里应该用〈参加〉。积累指一点点聚集，比赛是一次性的活动，不能说“积累”，要说“参加”。"}, {"text": "政府积累了一座大桥。", "explanation": "这里应该用〈建〉。积累指一点点聚集，大桥要建造，不能说“积累”，要说“建”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这几年积累的了很多经验。", "corrected_sentence": "他这几年积累了很多经验。", "error_description": "错误形式：“积累的了很多经验”；正确形式：“积累了很多经验”。“的”是结构助词，不能插在动词“积累”和体标“了”之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20720, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我想积累了一些经验。", "corrected_sentence": "我想积累一些经验。", "error_description": "体标错误：“想”后面不能直接接“了”表示完成。正确说法：我想积累一些经验。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
