INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20724, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "说别人做的不对。", "primary_collocate": null, "pronunciation": "pī pàn", "ipa": "pʰi˥ pʰan˥˩", "syllable_count": 2, "sentences": [{"text": "他做错了事，大家都批判他。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师批判了我的做法。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "别总是批判别人，先看看自己。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妈妈批判了弟弟的坏习惯。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他当着大家的面批判我。", "target_word": "批判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都批判他不守时。", "target_word": "批判", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "经理批判过这种做法。", "target_word": "批判", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你不要老是批判我的朋友。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不喜欢听别人批判自己。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "同学们批判小明乱扔垃圾的行为。", "target_word": "批判", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "批判了", "label": "完成体"}, {"form": "批判过", "label": "经历体"}, {"form": "批判者", "label": "复合"}], "register": "口语", "sense_fingerprint": "指出并说别人做得不对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c454d24f-0f35-4a6d-a548-05385f361c94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20724, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "批判", "is_correct": true, "explanation": "“他做错了事，大家都批判他”，批判指说别人做得不对，与“做错了事”一致。"}, {"text": "表扬", "is_correct": false, "explanation": "语义：“表扬”用于做得好的人，与“做错了事”相反，句意矛盾。"}, {"text": "夸奖", "is_correct": false, "explanation": "语义：“夸奖”表示称赞，与“做错了事”矛盾，大家不会这样做。"}, {"text": "感谢", "is_correct": false, "explanation": "搭配：“感谢”针对别人的帮助或好意，不用于做错事的人。"}], "explanations": {"批判": "“他做错了事，大家都批判他”，批判指说别人做得不对，与“做错了事”一致。", "表扬": "语义：“表扬”用于做得好的人，与“做错了事”相反，句意矛盾。", "夸奖": "语义：“夸奖”表示称赞，与“做错了事”矛盾，大家不会这样做。", "感谢": "搭配：“感谢”针对别人的帮助或好意，不用于做错事的人。"}, "sentence_index": 0, "correct_answer": "批判"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈批判了弟弟的好习惯。", "explanation": "这里应该用〈表扬〉。批判指说别人做得不对，好习惯应当表扬，不能批判。"}, {"text": "我批判你的帮助。", "explanation": "这里应该用〈感谢〉。批判指说对方做得不对，对别人的帮助应当表示感谢。"}, {"text": "老师批判了他的努力。", "explanation": "这里应该用〈赞美〉。批判指说别人做得不对，努力应当赞美，不能批判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20724, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "批判", "is_correct": true, "explanation": "“经理批判过这种做法”，批判指说别人的做法不对，与语境一致。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的宾语应是歌曲，不能说“唱做法”。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”的宾语应是食物，不能说“吃做法”。"}, {"text": "擦", "is_correct": false, "explanation": "语义：“擦”指清除污物，与“做法”不相关，句意不通。"}], "explanations": {"批判": "“经理批判过这种做法”，批判指说别人的做法不对，与语境一致。", "唱": "搭配：“唱”的宾语应是歌曲，不能说“唱做法”。", "吃": "搭配：“吃”的宾语应是食物，不能说“吃做法”。", "擦": "语义：“擦”指清除污物，与“做法”不相关，句意不通。"}, "sentence_index": 6, "correct_answer": "批判"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "同学们批判小明认真捡垃圾的行为。", "explanation": "这里应该用〈称赞〉。批判指说别人做得不对，认真捡垃圾是好行为，应当称赞。"}, {"text": "同学们批判小明乐于助人。", "explanation": "这里应该用〈夸奖〉。批判指说别人做得不对，乐于助人应当夸奖。"}, {"text": "同学们批判小明的勇敢。", "explanation": "这里应该用〈赞叹〉。批判指说别人做得不对，勇敢值得赞叹，不能用批判。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20724, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他批判很对。", "corrected_sentence": "他批判得很对。", "error_description": "“批判”后面的补语要用“得”引出，漏掉“得”。应为“批判得很对”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20724, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家都把他的做法批判。", "corrected_sentence": "大家都把他的做法批判了。", "error_description": "“把”字句中，动词“批判”后要带“了”等补充成分，光用动词句子不完整。应为“大家都把他的做法批判了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '172830be-9ef9-466e-a66d-cf7a22ff84d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "说大话，把小的说成大的。", "primary_collocate": null, "pronunciation": "kuā zhāng", "ipa": "[kʰua˥ ʈʂɑŋ˥]", "syllable_count": 2, "sentences": [{"text": "他说话总是很夸张，说一顿能吃十碗饭。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明夸张地说他昨天看到了一只恐龙。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他夸张地说，自己一个人扛走了一座山。", "target_word": "夸张", "complexity_tier": "T3", "furigana": "tā kuāzhāng de shuō, zìjǐ yí gè rén káng zǒu le yí zuò shān.", "sentence_source": "generated"}, {"text": "别说得那么夸张，哪有这么多人？", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他讲故事时总爱夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟夸张地说，他等了一百年。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样说太夸张了，没那么严重。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位朋友的话听上去很夸张。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小事说得很夸张，让人担心。", "target_word": "夸张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个渔夫说，那条鱼有两米长，话说得很夸张。", "target_word": "夸张", "complexity_tier": "T3", "furigana": "zhè ge yúfū shuō, nà tiáo yú yǒu liǎng mǐ cháng, huà shuō de hěn kuāzhāng.", "sentence_source": "generated"}], "morphological_forms": [{"form": "夸张地", "label": "状语形式"}, {"form": "夸张手法", "label": "复合词"}], "register": "中性", "sense_fingerprint": "说大话，把小的说成大的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '44487a15-d41b-418d-9679-5307425a1f18') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "夸张", "is_correct": true, "explanation": "正确：“很夸张”指说话言过其实，与“吃十碗饭”的夸大说法吻合。"}, {"text": "精确", "is_correct": false, "explanation": "语义：“精确”指准确，与“吃十碗饭”的夸大说法冲突。"}, {"text": "文雅", "is_correct": false, "explanation": "语域：“文雅”指斯文，与这种夸大的口吻不合。"}, {"text": "含蓄", "is_correct": false, "explanation": "语义：“含蓄”指委婉，与“吃十碗饭”的直白夸大冲突。"}], "explanations": {"夸张": "正确：“很夸张”指说话言过其实，与“吃十碗饭”的夸大说法吻合。", "精确": "语义：“精确”指准确，与“吃十碗饭”的夸大说法冲突。", "文雅": "语域：“文雅”指斯文，与这种夸大的口吻不合。", "含蓄": "语义：“含蓄”指委婉，与“吃十碗饭”的直白夸大冲突。"}, "sentence_index": 0, "correct_answer": "夸张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的体重夸张了五斤。", "explanation": "这里应该用〈增加〉。夸张指说大话、把小的说成大的，不表示体重增加；应说“体重增加了五斤”。"}, {"text": "他把房间夸张了一半。", "explanation": "这里应该用〈缩小〉。夸张不表示空间缩小，应说“把房间缩小了一半”。"}, {"text": "他的存款夸张了一半。", "explanation": "这里应该用〈减少〉。夸张不表示金额下降，应说“存款减少了一半”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "夸张", "is_correct": true, "explanation": "正确：“太夸张了”指说得过分，与“没那么严重”的语境相合。"}, {"text": "精彩", "is_correct": false, "explanation": "语义：“精彩”是褒义，与“没那么严重”的劝慰语境不合。"}, {"text": "圆满", "is_correct": false, "explanation": "语义：“圆满”指完美收场，与“没那么严重”的语境不合。"}, {"text": "整齐", "is_correct": false, "explanation": "搭配：“整齐”多用于排列、动作，不用来形容说法。"}], "explanations": {"夸张": "正确：“太夸张了”指说得过分，与“没那么严重”的语境相合。", "精彩": "语义：“精彩”是褒义，与“没那么严重”的劝慰语境不合。", "圆满": "语义：“圆满”指完美收场，与“没那么严重”的语境不合。", "整齐": "搭配：“整齐”多用于排列、动作，不用来形容说法。"}, "sentence_index": 6, "correct_answer": "夸张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "公司把成本夸张了一半。", "explanation": "这里应该用〈缩减〉。夸张不表示成本减少，应说“把成本缩减了一半”。"}, {"text": "比赛夸张了三天。", "explanation": "这里应该用〈推迟〉。夸张不表示日期的改变，应说“比赛推迟了三天”。"}, {"text": "这场讲座夸张了一个小时。", "explanation": "这里应该用〈缩短〉。夸张不表示时长减少，应说“讲座缩短了一个小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他讲话太夸张地了。", "corrected_sentence": "他讲话太夸张了。", "error_description": "错误：“夸张”后多加了“地”。“地”只修饰动词，“太夸张了”中不能加“地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20726, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "别把事情说得那夸张。", "corrected_sentence": "别把事情说得那么夸张。", "error_description": "错误：程度补语“那么”漏了“么”。“那”单独不能修饰形容词，应说“说得那么夸张”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '24f0b7ac-84f8-4ec9-9eb1-25f685137808') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
