INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20736, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "很久以前，欧洲人重新喜欢学习艺术和科学。", "primary_collocate": null, "pronunciation": "wén yì fù xīng", "ipa": "wən˧˥ i˥˩ fu˥˩ ɕiŋ˥˥", "syllable_count": 4, "sentences": [{"text": "文艺复兴是欧洲很久以前的事。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了文艺复兴。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴时，人们喜欢画画。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想去意大利看文艺复兴的画。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写的是文艺复兴。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴让人们重新学习艺术。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有很多文艺复兴时期的画。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他最喜欢文艺复兴的音乐。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "文艺复兴以后，科学也发展了。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们今天学了文艺复兴的故事。", "target_word": "文艺复兴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "文艺复兴时期", "label": "复合"}, {"form": "意大利文艺复兴", "label": "复合"}], "register": "中性", "sense_fingerprint": "很久以前欧洲人重新学习艺术和科学的时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49c86a1a-5204-4936-87bc-89eede9ea748') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20736, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文艺复兴", "is_correct": true, "explanation": "“文艺复兴”指很久以前欧洲重新学习艺术与科学的时期，与“很久以前的事”相符。"}, {"text": "互联网", "is_correct": false, "explanation": "语义：“互联网”是近几十年才出现的技术，与“很久以前”相矛盾。"}, {"text": "大熊猫", "is_correct": false, "explanation": "搭配：“是……的事”的主语须是事件或历史现象，“大熊猫”是动物，搭配不当。"}, {"text": "人工智能", "is_correct": false, "explanation": "语义：“人工智能”是近代以后才发展的技术，与“很久以前”相矛盾。"}], "explanations": {"文艺复兴": "“文艺复兴”指很久以前欧洲重新学习艺术与科学的时期，与“很久以前的事”相符。", "互联网": "语义：“互联网”是近几十年才出现的技术，与“很久以前”相矛盾。", "大熊猫": "搭配：“是……的事”的主语须是事件或历史现象，“大熊猫”是动物，搭配不当。", "人工智能": "语义：“人工智能”是近代以后才发展的技术，与“很久以前”相矛盾。"}, "sentence_index": 0, "correct_answer": "文艺复兴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她的英语文艺复兴得很快。", "explanation": "这里应该用〈进步〉。“文艺复兴”是名词，指欧洲的历史运动，不能作动词表示英语水平提高。"}, {"text": "他是一位文艺复兴。", "explanation": "这里应该用〈代表人物〉。“文艺复兴”指一场运动，不指人，说某人是它不合适。"}, {"text": "我听了一首文艺复兴。", "explanation": "这里的量词应为“场”。“首”用于歌曲和诗词，文艺复兴是一场运动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20736, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "文艺复兴", "is_correct": true, "explanation": "“文艺复兴时期”指欧洲重新学习艺术的时期，与博物馆里的古画相符。"}, {"text": "手机", "is_correct": false, "explanation": "语义：“手机”出现的时间很晚，不能作为古画所属时期的名称。"}, {"text": "高铁", "is_correct": false, "explanation": "语义：“高铁”是近代交通工具，与古画的创作时期不符。"}, {"text": "咖啡", "is_correct": false, "explanation": "搭配：“时期”需要时代或历史阶段的名称，“咖啡”不是时代名称。"}], "explanations": {"文艺复兴": "“文艺复兴时期”指欧洲重新学习艺术的时期，与博物馆里的古画相符。", "手机": "语义：“手机”出现的时间很晚，不能作为古画所属时期的名称。", "高铁": "语义：“高铁”是近代交通工具，与古画的创作时期不符。", "咖啡": "搭配：“时期”需要时代或历史阶段的名称，“咖啡”不是时代名称。"}, "sentence_index": 6, "correct_answer": "文艺复兴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们暑假去文艺复兴旅游。", "explanation": "这里应该用〈意大利〉。“文艺复兴”是历史运动，不是地点，不能作旅游目的地。"}, {"text": "我读过一部文艺复兴。", "explanation": "这里的量词应为“场”。“部”用于书籍、影视等作品，文艺复兴是一场运动，不是作品。"}, {"text": "他每天喝文艺复兴。", "explanation": "这里应该用〈咖啡〉。“喝”的对象应是饮料，“文艺复兴”是历史运动，不能喝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20736, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "博物馆里收藏着文艺复兴时间的雕塑。", "corrected_sentence": "博物馆里收藏着文艺复兴时期的雕塑。", "error_description": "错误：“时期”误作“时间”（文艺复兴时间的雕塑）。正确：“文艺复兴时期的雕塑”，指历史阶段须用“时期”，“时间”指时长或时点。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20736, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们在一座文艺复兴中学到了很多。", "corrected_sentence": "我们在一场文艺复兴中学到了很多。", "error_description": "错误：量词“座”用于建筑，不能修饰运动（一座文艺复兴）。正确：“一场文艺复兴”，“场”用于运动、事件。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b11c6d02-1c2e-4ccf-827c-3efbae0b1aae') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
