INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "从睡觉中醒来，或者突然明白一个道理。", "primary_collocate": null, "pronunciation": "jué xǐng", "ipa": "tɕyɛ˧˥ ɕiŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "冬眠的熊在春天觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他读了那本书，一下子觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们觉醒后，开始为自己争取权利。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沉睡的火山突然觉醒，喷出了大量烟尘。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影让很多年轻人觉醒过来。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她终于觉醒，决定离开那个公司。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "直到失去健康，他才真正觉醒。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们的环保意识正在觉醒。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争让这个国家的人民觉醒了。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一场大病让他觉醒，开始珍惜时间。", "target_word": "觉醒", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "觉醒了", "label": "完成体标"}, {"form": "觉醒过", "label": "经历体标"}], "register": "书面", "sense_fingerprint": "从睡眠中醒来，或突然醒悟明白道理", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '699a7efa-2ffe-43e6-84c2-b247b5d73d94') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "觉醒", "is_correct": true, "explanation": "正确。冬眠的熊在春天从睡眠中醒来，用“觉醒”表示。"}, {"text": "长眠", "is_correct": false, "explanation": "语义：“长眠”指死亡或长久沉睡，与春天醒来的语境相反。"}, {"text": "迁徙", "is_correct": false, "explanation": "搭配：“迁徙”指大范围的移动，不用于熊从冬眠中醒来。"}, {"text": "咆哮", "is_correct": false, "explanation": "语义：“咆哮”指发出吼叫，与“觉醒”从睡眠中醒来的意思不符。"}], "explanations": {"觉醒": "正确。冬眠的熊在春天从睡眠中醒来，用“觉醒”表示。", "长眠": "语义：“长眠”指死亡或长久沉睡，与春天醒来的语境相反。", "迁徙": "搭配：“迁徙”指大范围的移动，不用于熊从冬眠中醒来。", "咆哮": "语义：“咆哮”指发出吼叫，与“觉醒”从睡眠中醒来的意思不符。"}, "sentence_index": 0, "correct_answer": "觉醒"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "病人昏迷多日后终于觉醒，慢慢睁开了眼睛。", "explanation": "这里应该用〈苏醒〉。觉醒指从睡眠中醒来或醒悟，病人从昏迷中恢复要用苏醒。"}, {"text": "他的腿伤慢慢觉醒了，已经能下地走路。", "explanation": "这里应该用〈好转〉。觉醒指醒来或醒悟，伤势逐渐好起来要用好转。"}, {"text": "雨停以后，天上的乌云慢慢觉醒了。", "explanation": "这里应该用〈消散〉。觉醒指醒来或醒悟，云雾散开要用消散。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "觉醒", "is_correct": true, "explanation": "正确。“直到失去健康，他才真正觉醒”指经历变故后醒悟。"}, {"text": "昏迷", "is_correct": false, "explanation": "语义：“昏迷”指失去知觉，与“真正醒悟”的意思正相反。"}, {"text": "入睡", "is_correct": false, "explanation": "搭配：“入睡”是进入睡眠的动作，不能与“才真正”搭配表示认识上的转变。"}, {"text": "迷惑", "is_correct": false, "explanation": "语义：“迷惑”指弄不清楚，与“真正”明白之后的结果相矛盾。"}], "explanations": {"觉醒": "正确。“直到失去健康，他才真正觉醒”指经历变故后醒悟。", "昏迷": "语义：“昏迷”指失去知觉，与“真正醒悟”的意思正相反。", "入睡": "搭配：“入睡”是进入睡眠的动作，不能与“才真正”搭配表示认识上的转变。", "迷惑": "语义：“迷惑”指弄不清楚，与“真正”明白之后的结果相矛盾。"}, "sentence_index": 6, "correct_answer": "觉醒"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次手术后，他的膝盖慢慢觉醒了，可以正常走路了。", "explanation": "这里应该用〈复原〉。觉醒指醒来或醒悟，膝盖恢复原状要用复原。"}, {"text": "喝了热汤以后，身上的寒意慢慢觉醒了。", "explanation": "这里应该用〈消退〉。觉醒指醒来或醒悟，寒意逐渐减弱要用消退。"}, {"text": "这场风波很快就觉醒了。", "explanation": "这里应该用〈平息〉。觉醒指醒来或醒悟，风波停止要用平息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "春天来了，熊终于觉醒了着。", "corrected_sentence": "春天来了，熊终于觉醒了。", "error_description": "错误在体标：“了”已表示动作完成，又多出“着”，句子不通；应只用“觉醒了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20738, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "那次失败让他觉醒来了，明白了努力的重要。", "corrected_sentence": "那次失败让他觉醒过来，明白了努力的重要。", "error_description": "错误在补语：“觉醒”后应接“过来”，写作“觉醒过来”，表示恢复清醒；“觉醒来了”不符合规范。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '42eb6137-f768-4a96-8a30-858a9d254957') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
