INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20742, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20742, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一种圆圆的水果，可以吃，有红的和绿的。", "primary_collocate": null, "pronunciation": "píng guǒ", "ipa": "pʰiŋ˧˥ kuɔ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我早上吃了一个红苹果。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子上放着三个绿苹果。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种苹果又脆又甜。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈用苹果做了一杯果汁。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树上的苹果红了，可以吃了。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天吃一个苹果，身体很好。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请给我两斤苹果。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个苹果太酸了，我不爱吃。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩把苹果洗干净，然后咬了一口。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市里的苹果有红的，也有绿的。", "target_word": "苹果", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "苹果树", "label": "复合"}, {"form": "蘋果", "label": "繁体"}], "register": "中性", "sense_fingerprint": "圆形的水果，有红色和绿色", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20742, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "苹果", "is_correct": true, "explanation": "“红苹果”是一种水果，“吃了一个”的语境完全符合。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能吃，“吃了一个红汽车”说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，“吃了一个红石头”说不通。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不能吃，“吃了一个红椅子”说不通。"}], "explanations": {"苹果": "“红苹果”是一种水果，“吃了一个”的语境完全符合。", "汽车": "语义：汽车不能吃，“吃了一个红汽车”说不通。", "石头": "语义：石头不能吃，“吃了一个红石头”说不通。", "椅子": "语义：椅子不能吃，“吃了一个红椅子”说不通。"}, "sentence_index": 0, "correct_answer": "苹果"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天喝苹果，身体很好。", "explanation": "这里应该用〈苹果汁〉。苹果指可以直接吃的水果，喝的饮料要说苹果汁，不能说喝苹果。"}, {"text": "妈妈用苹果炒了一盘鸡蛋。", "explanation": "这里应该用〈西红柿〉。苹果一般不用来炒菜，炒鸡蛋要用西红柿。"}, {"text": "他用苹果给汽车加油，车跑得很快。", "explanation": "这里应该用〈汽油〉。苹果是水果，不能用来加油，给汽车加油要用汽油。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20742, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "苹果", "is_correct": true, "explanation": "“斤”用于称量水果，苹果可以按斤买，“两斤苹果”通顺。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能按斤买，“两斤汽车”说不通。"}, {"text": "钢笔", "is_correct": false, "explanation": "搭配：钢笔以“支”计量，不说“斤”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不能按斤称买，“请给我两斤房子”不合逻辑。"}], "explanations": {"苹果": "“斤”用于称量水果，苹果可以按斤买，“两斤苹果”通顺。", "汽车": "语义：汽车不能按斤买，“两斤汽车”说不通。", "钢笔": "搭配：钢笔以“支”计量，不说“斤”。", "房子": "语义：房子不能按斤称买，“请给我两斤房子”不合逻辑。"}, "sentence_index": 6, "correct_answer": "苹果"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我把苹果刷在牙上，每天早上都刷一次。", "explanation": "这里应该用〈牙膏〉。苹果是水果，不能用来刷牙，刷牙要用牙膏。"}, {"text": "我用苹果给自行车打气。", "explanation": "这里应该用〈气筒〉。苹果不能用来打气，给自行车打气要用气筒。"}, {"text": "妈妈用苹果擦地板，很干净。", "explanation": "这里应该用〈抹布〉。苹果不能用来擦地，擦地板要用抹布。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20742, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他买了一只苹果。", "corrected_sentence": "他买了一个苹果。", "error_description": "量词错误：苹果应该用量词“个”，“一只苹果”是错的，应说“一个苹果”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20742, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他苹果放进了冰箱。", "corrected_sentence": "他把苹果放进了冰箱。", "error_description": "“把”字句漏掉了“把”：应说“他把苹果放进了冰箱”；去掉“把”后“他苹果放进了冰箱”不成句。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
