INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20744, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水果中间硬硬的部分。", "primary_collocate": null, "pronunciation": "hé", "ipa": "xɤ˧˥", "syllable_count": 1, "sentences": [{"text": "桃子的核特别硬，我用锤子才打开。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "荔枝的肉很甜，核是黑色的。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "枣的核两头尖，吃的时候要小心。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "樱桃的核很小，吃的时候要吐出来。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山楂的核比较大，做菜前要先拿掉。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟吃杨梅时，把核留在了碗里。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把吃剩的核洗干净，晾干了。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "龙眼的核又圆又亮，像小黑珠子。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他吃梅子时不小心咬到了核。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗把桃子的核当成了球。", "target_word": "核", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "颗", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "果核", "label": "复合"}, {"form": "枣核", "label": "复合"}], "register": "中性", "sense_fingerprint": "水果中间硬硬的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 4 above tier T2: contains vocabulary far above tier T2: 楂 (Zipf 1.94)']::text[], '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20744, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "核", "is_correct": true, "explanation": "正确答案。核 hé，指水果中间硬硬的部分。"}, {"text": "湖", "is_correct": false, "explanation": "hú（第二声）与 hé 只差一个元音（u 与 e），意思是湖泊。"}, {"text": "鹅", "is_correct": false, "explanation": "é（第二声）与 hé 只差声母 h，意思是鹅。"}, {"text": "蛇", "is_correct": false, "explanation": "shé（第二声）与 hé 声母不同（sh 与 h），意思是蛇。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，意思是喝。"}], "explanations": {"核": "正确答案。核 hé，指水果中间硬硬的部分。", "湖": "hú（第二声）与 hé 只差一个元音（u 与 e），意思是湖泊。", "鹅": "é（第二声）与 hé 只差声母 h，意思是鹅。", "蛇": "shé（第二声）与 hé 声母不同（sh 与 h），意思是蛇。", "喝": "hē（第一声）与 hé（第二声）声调不同，意思是喝。"}, "sentence_index": null, "correct_answer": "核"}, "level_3": {"options": [{"text": "核", "is_correct": true, "explanation": "正确。桃子的核特别硬，需要用锤子才能打开，与后句相合。"}, {"text": "汁", "is_correct": false, "explanation": "搭配：“汁”是液体，不能说“特别硬”。"}, {"text": "肉", "is_correct": false, "explanation": "语义：桃子的肉是软的，“肉特别硬”与桃子的特点不合。"}, {"text": "味", "is_correct": false, "explanation": "搭配：“味”不能用“特别硬”来形容。"}], "explanations": {"核": "正确。桃子的核特别硬，需要用锤子才能打开，与后句相合。", "汁": "搭配：“汁”是液体，不能说“特别硬”。", "肉": "语义：桃子的肉是软的，“肉特别硬”与桃子的特点不合。", "味": "搭配：“味”不能用“特别硬”来形容。"}, "sentence_index": 0, "correct_answer": "核"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "鸡蛋的核很薄，轻轻一碰就碎了。", "explanation": "这里应该用〈壳〉。鸡蛋外面包着的硬壳叫壳，不叫核。"}, {"text": "橘子的核又软又香，剥开就能闻到。", "explanation": "这里应该用〈皮〉。橘子外层的皮才会散发香味；“核”指果实中心的硬核，不会又软又香。"}, {"text": "草莓的核很绿，摘下来洗一洗。", "explanation": "这里应该用〈蒂〉。草莓顶端的绿色部分叫蒂，不叫核。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20744, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "核", "is_correct": true, "explanation": "正确答案。核 hé，指水果中间硬硬的部分。"}, {"text": "喝", "is_correct": false, "explanation": "hē（第一声）与 hé（第二声）声调不同，意思是喝。"}, {"text": "横", "is_correct": false, "explanation": "héng（第二声）与 hé 韵母不同（eng 与 e），意思是横向。"}, {"text": "贺", "is_correct": false, "explanation": "hè（第四声）与 hé（第二声）声调不同，意思是祝贺。"}, {"text": "胡", "is_correct": false, "explanation": "hú（第二声）与 hé 只差一个元音（u 与 e），意思是胡须、胡乱。"}], "explanations": {"核": "正确答案。核 hé，指水果中间硬硬的部分。", "喝": "hē（第一声）与 hé（第二声）声调不同，意思是喝。", "横": "héng（第二声）与 hé 韵母不同（eng 与 e），意思是横向。", "贺": "hè（第四声）与 hé（第二声）声调不同，意思是祝贺。", "胡": "hú（第二声）与 hé 只差一个元音（u 与 e），意思是胡须、胡乱。"}, "sentence_index": null, "correct_answer": "核"}, "level_3": {"options": [{"text": "核", "is_correct": true, "explanation": "正确。“吃剩的核”指吃完果肉后剩下的硬核，可以洗干净晾干。"}, {"text": "汤", "is_correct": false, "explanation": "搭配：“汤”是液体，不能说“洗干净、晾干”。"}, {"text": "饭", "is_correct": false, "explanation": "语义：“饭”不是要洗干净晾干的东西，与整句语境不合。"}, {"text": "菜", "is_correct": false, "explanation": "语义：剩菜不能洗干净晾干，与整句的做法矛盾。"}], "explanations": {"核": "正确。“吃剩的核”指吃完果肉后剩下的硬核，可以洗干净晾干。", "汤": "搭配：“汤”是液体，不能说“洗干净、晾干”。", "饭": "语义：“饭”不是要洗干净晾干的东西，与整句语境不合。", "菜": "语义：剩菜不能洗干净晾干，与整句的做法矛盾。"}, "sentence_index": 6, "correct_answer": "核"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗饺子的核很香，咬一口就流油。", "explanation": "这里应该用〈馅〉。饺子里包的食材叫馅，“核”指水果中间的硬部分。"}, {"text": "这座山的核很高，爬上去要很久。", "explanation": "这里应该用〈山顶〉。山的最高处叫山顶，“核”指水果中间的硬部分。"}, {"text": "这串香蕉的核很粗，要先摘掉。", "explanation": "这里应该用〈梗〉。香蕉没有中心的硬核；连着果实的枝条叫梗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20744, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我把一只杏核放进了口袋。", "corrected_sentence": "我把一颗杏核放进了口袋。", "error_description": "错误：“杏核”的量词应用“颗”，“只”不能用于果核。应说“一颗杏核”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20744, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "吃完杏子，桌上有一片杏核。", "corrected_sentence": "吃完杏子，桌上有一颗杏核。", "error_description": "错误：“杏核”的量词应用“颗”，“片”用于扁平的东西，不能用于果核。应说“一颗杏核”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20746, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "取出", "is_correct": true, "explanation": "反义：“放进”是把东西放入里面，“取出”是把里面的东西拿出来，二者方向相反。"}, {"text": "留下", "is_correct": false, "explanation": "不构成反义：“留下”指保持原状、不带走，与“放进”的动作没有对立关系。"}, {"text": "保存", "is_correct": false, "explanation": "不构成反义：“保存”指妥善存放、留存，与“放进”没有对立关系。"}, {"text": "出现", "is_correct": false, "explanation": "不构成反义：“出现”指显露或发生，与“放进”的动作无关。"}], "correct_answer": "取出", "explanations": {"取出": "反义：“放进”是把东西放入里面，“取出”是把里面的东西拿出来，二者方向相反。", "留下": "不构成反义：“留下”指保持原状、不带走，与“放进”的动作没有对立关系。", "保存": "不构成反义：“保存”指妥善存放、留存，与“放进”没有对立关系。", "出现": "不构成反义：“出现”指显露或发生，与“放进”的动作无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5929ded6-410f-41e2-9010-d14e773cb815') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
