INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20748, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奶是哺乳动物分泌的白色乳汁，用来喂养幼崽。", "primary_collocate": null, "pronunciation": "nǎi", "ipa": "nai˨˩˦", "syllable_count": 1, "sentences": [{"text": "宝宝饿了，妈妈给他喝奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小宝宝一醒来就要喝奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈把奶倒进小瓶子里。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝喝完奶就睡着了。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶是白色的，宝宝都爱喝。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里宝宝哭了，妈妈马上去热奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小羊在草地上跟着妈妈吃奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸轻轻抱着宝宝，喂他喝奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小猫闭着眼睛，正在喝奶。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "宝宝每天喝很多奶，长得又白又胖。", "target_word": "奶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "瓶", "label": "量词"}, {"form": "杯", "label": "量词"}, {"form": "奶粉", "label": "复合"}, {"form": "牛奶", "label": "复合"}], "register": "中性", "sense_fingerprint": "哺乳动物用来喂养幼崽的白色乳汁", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5ff5dce4-678f-4afa-8fc7-dd6993e1a005') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20748, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "奶", "is_correct": true, "explanation": "奶（nǎi，第三声）：指乳汁，是正确答案。"}, {"text": "买", "is_correct": false, "explanation": "mǎi（第三声）与 nǎi 声母不同（m/n），意思是购买。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是大脑。"}, {"text": "耐", "is_correct": false, "explanation": "nài（第四声）与 nǎi 声调不同，意思是能够经受。"}, {"text": "海", "is_correct": false, "explanation": "hǎi（第三声）与 nǎi 声母不同（h/n），意思是海洋。"}], "explanations": {"奶": "奶（nǎi，第三声）：指乳汁，是正确答案。", "买": "mǎi（第三声）与 nǎi 声母不同（m/n），意思是购买。", "脑": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是大脑。", "耐": "nài（第四声）与 nǎi 声调不同，意思是能够经受。", "海": "hǎi（第三声）与 nǎi 声母不同（h/n），意思是海洋。"}, "sentence_index": null, "correct_answer": "奶"}, "level_3": {"options": [{"text": "饭", "is_correct": false, "explanation": "搭配：“喝”不能搭配固体的饭，宝宝不能“喝饭”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能喝，与“饿了”要喝东西的语境冲突。"}, {"text": "奶", "is_correct": true, "explanation": "正确：“奶”是宝宝喝的奶汁，与“饿了”和“喝”搭配。"}, {"text": "面包", "is_correct": false, "explanation": "搭配：面包是固体，不能说“喝面包”。"}], "explanations": {"饭": "搭配：“喝”不能搭配固体的饭，宝宝不能“喝饭”。", "玩具": "语义：玩具不能喝，与“饿了”要喝东西的语境冲突。", "奶": "正确：“奶”是宝宝喝的奶汁，与“饿了”和“喝”搭配。", "面包": "搭配：面包是固体，不能说“喝面包”。"}, "sentence_index": 0, "correct_answer": "奶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈给宝宝买了一只奶。", "explanation": "这里量词用错。“只”不用于液体，奶应说“瓶”或“盒”。"}, {"text": "妈妈给宝宝榨了一杯奶。", "explanation": "这里“榨”用错了：“榨”用于水果、蔬菜取汁，不能用于奶。给宝宝倒奶，动词应用“倒”。"}, {"text": "妈妈给宝宝买了一块奶。", "explanation": "这里量词用错。“块”用于块状固体，奶是液体，应说“瓶”或“杯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20748, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "奶", "is_correct": true, "explanation": "奶（nǎi，第三声）：指乳汁，是正确答案。"}, {"text": "摆", "is_correct": false, "explanation": "bǎi（第三声）与 nǎi 声母不同（b/n），意思是摆放。"}, {"text": "改", "is_correct": false, "explanation": "gǎi（第三声）与 nǎi 声母不同（g/n），意思是改变。"}, {"text": "彩", "is_correct": false, "explanation": "cǎi（第三声）与 nǎi 声母不同（c/n），意思是彩色。"}, {"text": "恼", "is_correct": false, "explanation": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是生气。"}], "explanations": {"奶": "奶（nǎi，第三声）：指乳汁，是正确答案。", "摆": "bǎi（第三声）与 nǎi 声母不同（b/n），意思是摆放。", "改": "gǎi（第三声）与 nǎi 声母不同（g/n），意思是改变。", "彩": "cǎi（第三声）与 nǎi 声母不同（c/n），意思是彩色。", "恼": "nǎo（第三声）与 nǎi 韵母不同（ao/ai），意思是生气。"}, "sentence_index": null, "correct_answer": "奶"}, "level_3": {"options": [{"text": "水", "is_correct": false, "explanation": "搭配：“吃”不能搭配水，应说“喝水”。"}, {"text": "玩具", "is_correct": false, "explanation": "语义：玩具不能吃，与小羊跟着妈妈的语境不符。"}, {"text": "奶", "is_correct": true, "explanation": "正确：小羊“吃奶”是动物哺乳的常用说法，与“跟着妈妈”的语境一致。"}, {"text": "电话", "is_correct": false, "explanation": "语义：电话不能吃，与“吃”的语境冲突。"}], "explanations": {"水": "搭配：“吃”不能搭配水，应说“喝水”。", "玩具": "语义：玩具不能吃，与小羊跟着妈妈的语境不符。", "奶": "正确：小羊“吃奶”是动物哺乳的常用说法，与“跟着妈妈”的语境一致。", "电话": "语义：电话不能吃，与“吃”的语境冲突。"}, "sentence_index": 6, "correct_answer": "奶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "宝宝每天喝一个奶，长得又白又胖。", "explanation": "这里量词用错。“个”不能修饰液体，奶应说“瓶”或“杯”。"}, {"text": "宝宝每天喝一条奶，长得又白又胖。", "explanation": "这里量词用错。“条”用于细长的东西，奶是液体，应说“瓶”或“杯”。"}, {"text": "宝宝每天喝一台奶，长得又白又胖。", "explanation": "这里量词用错。“台”用于机器等物品，不能修饰奶，应说“瓶”或“杯”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20748, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宝宝每天早上都要喝一只奶。", "corrected_sentence": "宝宝每天早上都要喝一瓶奶。", "error_description": "错误：量词用“只”。“奶”是液体，应使用容器量词“瓶”，说“一瓶奶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20748, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "宝宝刚才喝了一瓶的奶。", "corrected_sentence": "宝宝刚才喝了一瓶奶。", "error_description": "错误：数量短语与名词之间多加了“的”。“一瓶”直接修饰“奶”，中间不用“的”，应说“一瓶奶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f6aa1cac-2c77-49a8-8e8a-40de85235245') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
