INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20754, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用手或工具让东西动一下，再看一看。", "primary_collocate": null, "pronunciation": "fān yi fān", "ipa": "fan˥˥ i fan˥˥", "syllable_count": 3, "sentences": [{"text": "他用筷子翻一翻锅里的肉。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把鱼翻一翻，不然会烧焦。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸用铲子翻一翻地里的土。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩用小木棍翻一翻石头下面。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你用手翻一翻这些水果，看看有没有坏的。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把垫子翻一翻，下面什么也没有。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人用手翻一翻草，想找那只小虫。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厨师用勺子翻一翻锅里的菜。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把这件衣服翻一翻，看看里面有没有口袋。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们蹲在地上，翻一翻树叶找蜗牛。", "target_word": "翻一翻", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "翻翻", "label": "重叠"}, {"form": "翻了翻", "label": "体标"}, {"form": "翻", "label": "单字形式"}], "register": "口语", "sense_fingerprint": "用手或工具把东西翻动一下再查看", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'b10fc90c-0e14-449a-94f1-3095b8172350') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20754, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "翻一翻", "is_correct": true, "explanation": "翻一翻：用工具翻动，正好符合「用筷子……锅里的肉」的语境。"}, {"text": "切", "is_correct": false, "explanation": "搭配：切肉通常用刀，「用筷子切锅里的肉」不成立。"}, {"text": "撒", "is_correct": false, "explanation": "语义：撒指使东西散落，不能用来翻动锅里的肉。"}, {"text": "晾", "is_correct": false, "explanation": "语义：晾指放在通风处使东西干燥，不能用来翻动锅里的肉。"}], "explanations": {"翻一翻": "翻一翻：用工具翻动，正好符合「用筷子……锅里的肉」的语境。", "切": "搭配：切肉通常用刀，「用筷子切锅里的肉」不成立。", "撒": "语义：撒指使东西散落，不能用来翻动锅里的肉。", "晾": "语义：晾指放在通风处使东西干燥，不能用来翻动锅里的肉。"}, "sentence_index": 0, "correct_answer": "翻一翻"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用力翻一翻那棵树，看看有没有鸟窝。", "explanation": "这里应该用〈摇〉。翻一翻指让轻小的物品翻转或拨开查看，大树要靠摇动，不能用翻一翻。"}, {"text": "他用布翻一翻镜子，让镜子变亮。", "explanation": "这里应该用〈擦拭〉。擦拭是把表面擦干净，翻一翻是翻动物体，不能用来擦镜子。"}, {"text": "她用手翻一翻孩子的头。", "explanation": "这里应该用〈摸〉。翻一翻指翻动可以翻转的物体，不能用于抚摸人的头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20754, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "翻一翻", "is_correct": true, "explanation": "翻一翻：用手翻动草，正好符合「想找那只小虫」的语境。"}, {"text": "踩", "is_correct": false, "explanation": "搭配：踩要用脚，不能说用手踩草。"}, {"text": "擦", "is_correct": false, "explanation": "语义：擦指抹去表面，与「想找那只小虫」毫无关系。"}, {"text": "扔", "is_correct": false, "explanation": "语义：扔指丢弃，把草扔掉就不能用来找小虫了。"}], "explanations": {"翻一翻": "翻一翻：用手翻动草，正好符合「想找那只小虫」的语境。", "踩": "搭配：踩要用脚，不能说用手踩草。", "擦": "语义：擦指抹去表面，与「想找那只小虫」毫无关系。", "扔": "语义：扔指丢弃，把草扔掉就不能用来找小虫了。"}, "sentence_index": 6, "correct_answer": "翻一翻"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她每天翻一翻钢琴两小时。", "explanation": "这里应该用〈弹〉。翻一翻指翻动或快速查看，不能用来说弹钢琴。"}, {"text": "他轻轻翻一翻我的后背，让我别紧张。", "explanation": "这里应该用〈拍〉。翻一翻指翻动物体，轻拍别人的后背要用拍，不能用翻一翻。"}, {"text": "他轻轻翻一翻我的脸蛋，逗我笑。", "explanation": "这里应该用〈捏〉。翻一翻指翻动物体，捏脸蛋要用捏，不能用翻一翻。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20754, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "妈妈用铲子翻着一翻菜地里的土。", "corrected_sentence": "妈妈用铲子翻一翻菜地里的土。", "error_description": "「着」表示动作持续，与「翻一翻」这种短时动作矛盾。应删去「着」，说「用铲子翻一翻」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20754, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "请你把这块布翻翻一，看看背面。", "corrected_sentence": "请你把这块布翻一翻，看看背面。", "error_description": "「翻一翻」的结构是「翻」＋「一」＋「翻」，应说「翻一翻」，不能把中间的「一」挪到两个「翻」之后，说成「翻翻一」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '43b210fc-d3d7-441e-83e1-71bbf100a917') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
