INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20772, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "就是用手去做一件事。", "primary_collocate": null, "pronunciation": "dòng shǒu zuò", "ipa": "tʊŋ˥˩ ʂoʊ˨˩˦ tswɔ˥˩", "syllable_count": 3, "sentences": [{"text": "周末我们一起动手做蛋糕。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子喜欢动手做小玩具。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让大家动手做一个纸飞机。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想学会做菜，就要自己动手做。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他动手做了一张小桌子。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我也想动手做一份生日礼物。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别只看别人做，你也动手做吧。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸正动手做晚饭。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学生们动手做过很多小实验。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的手工课，我们动手做灯笼。", "target_word": "动手做", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "动手做了", "label": "体标"}, {"form": "动手做过", "label": "体标"}], "register": "口语", "sense_fingerprint": "亲自用手去做某件事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '77d97711-45c9-40d1-a540-071631f184cb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20772, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "动手做", "is_correct": true, "explanation": "正确答案：动手做，表示亲自用手去做事情，与「一起」「蛋糕」相配。"}, {"text": "吟诵", "is_correct": false, "explanation": "语域：「吟诵」是文雅的书面用语，多用于诗文，与这个口语句子不搭。"}, {"text": "监督", "is_correct": false, "explanation": "语义：「监督」针对的是人或工作，不能说监督蛋糕。"}, {"text": "思考", "is_correct": false, "explanation": "语义：「思考」是动脑的活动，与「蛋糕」这样的具体东西不搭配，句子说不通。"}], "explanations": {"动手做": "正确答案：动手做，表示亲自用手去做事情，与「一起」「蛋糕」相配。", "吟诵": "语域：「吟诵」是文雅的书面用语，多用于诗文，与这个口语句子不搭。", "监督": "语义：「监督」针对的是人或工作，不能说监督蛋糕。", "思考": "语义：「思考」是动脑的活动，与「蛋糕」这样的具体东西不搭配，句子说不通。"}, "sentence_index": 0, "correct_answer": "动手做"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他昨晚动手做了一个好梦。", "explanation": "这里应该用〈做〉。「做梦」指睡眠中的心理活动；「动手做」强调用手做具体的事，梦不能用手去做。"}, {"text": "他动手做了一个决定。", "explanation": "这里应该用〈做出〉。「动手做」指用手去做具体的事，决定是心里的判断，不能用手去做。"}, {"text": "他很思念家乡，动手做了家乡。", "explanation": "这里应该用〈建设〉。「动手做」指亲手做具体的东西，家乡不能亲手做出，应说「建设家乡」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20772, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "动手做", "is_correct": true, "explanation": "正确答案：动手做，与前句「看别人做」形成对照，表示你也亲自去做。"}, {"text": "说", "is_correct": false, "explanation": "语义：前句是「看别人做」，这里要的是动手去做，「说」与语境不符。"}, {"text": "睡", "is_correct": false, "explanation": "语义：「睡」与「看别人做」的语境没有关系，「你也睡吧」与劝人一起做事不合。"}, {"text": "走", "is_correct": false, "explanation": "语义：「走」与「看别人做」的语境不符，「你也走吧」不表示动手去做。"}], "explanations": {"动手做": "正确答案：动手做，与前句「看别人做」形成对照，表示你也亲自去做。", "说": "语义：前句是「看别人做」，这里要的是动手去做，「说」与语境不符。", "睡": "语义：「睡」与「看别人做」的语境没有关系，「你也睡吧」与劝人一起做事不合。", "走": "语义：「走」与「看别人做」的语境不符，「你也走吧」不表示动手去做。"}, "sentence_index": 6, "correct_answer": "动手做"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他听了这个笑话，动手做了一个大笑。", "explanation": "这个词不这么用。这里误把「动手做」当作〈露出〉来用；「大笑」是表情和声音，不是可以用手做出的东西。"}, {"text": "他昨天动手做了一场大病。", "explanation": "这个词不这么用。这里误把「动手做」当作〈得〉来用；「大病」是身体状况，不能用手去做，应说「得了一场大病」。"}, {"text": "他做了一场精彩的发言，动手做了一场发言。", "explanation": "这个词不这么用。这里误把「动手做」当作〈说话〉来用；「动手做」指用手做具体的事，发言是用口说的，不能用手去做。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20772, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他想自己很动手做一个书架。", "corrected_sentence": "他想自己动手做一个书架。", "error_description": "副词位置错误：「很」修饰形容词，不能放在动词「动手做」前面，应删去「很」，说「想自己动手做一个书架」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20772, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们动手做了完一个风筝。", "corrected_sentence": "孩子们动手做完了一个风筝。", "error_description": "补语位置错误：结果补语「完」应紧接动词，说「动手做完了」，不能说「动手做了完」。正确说法是「孩子们动手做完了一个风筝」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bc650faf-eef1-4b87-8649-678eec955448') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
