INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "让东西变少。", "primary_collocate": null, "pronunciation": "jiǎn shǎo", "ipa": "tɕjɛn˨˩˦ ʂau˨˩˦", "syllable_count": 2, "sentences": [{"text": "我想减少吃糖的次数。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "关灯可以减少用电。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把每天喝咖啡的杯数减少了。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司减少了三个人。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了身体好，爸爸减少了抽烟。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多用公共汽车能减少污染。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师减少了我们的作业。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈想减少家里花钱的地方。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生让他减少盐的量。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要减少用塑料袋。", "target_word": "减少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "减少了", "label": "体标"}, {"form": "减少过", "label": "体标"}], "register": "中性", "sense_fingerprint": "使数量变少", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ea089b11-07da-4ae5-aa39-37efb2e90fe9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "减少", "is_correct": true, "explanation": "正确答案。“我想减少吃糖的次数”中，指使次数变少。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于抹去具体物体表面，不能和“次数”搭配。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”指丢掉具体物品，与吃糖的次数无关，与句意冲突。"}, {"text": "挖", "is_correct": false, "explanation": "语义：“挖”指向下掘取，不能用来处理次数，与句意冲突。"}], "explanations": {"减少": "正确答案。“我想减少吃糖的次数”中，指使次数变少。", "擦": "搭配：“擦”用于抹去具体物体表面，不能和“次数”搭配。", "扔": "语义：“扔”指丢掉具体物品，与吃糖的次数无关，与句意冲突。", "挖": "语义：“挖”指向下掘取，不能用来处理次数，与句意冲突。"}, "sentence_index": 0, "correct_answer": "减少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "今天的气温减少了三度。", "explanation": "这里应该用〈降低〉。减少说数量变少，气温、温度等要用降低。"}, {"text": "这块布的颜色减少了一些。", "explanation": "这里应该用〈褪色〉。布料颜色变淡要说褪色，减少说数量变少，不用于颜色。"}, {"text": "老师的声音慢慢减少了。", "explanation": "这里应该用〈减弱〉。声音的强弱要用减弱，减少只用于数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "减少", "is_correct": true, "explanation": "正确答案。“老师减少了我们的作业”中，指使作业变少。"}, {"text": "吃", "is_correct": false, "explanation": "语义：“吃”指进食，不能用来处理作业，与句意冲突。"}, {"text": "喝", "is_correct": false, "explanation": "语义：“喝”指饮用液体，不能用来处理作业，与句意冲突。"}, {"text": "烤", "is_correct": false, "explanation": "搭配：“烤”多用于食物，不说烤作业。"}], "explanations": {"减少": "正确答案。“老师减少了我们的作业”中，指使作业变少。", "吃": "语义：“吃”指进食，不能用来处理作业，与句意冲突。", "喝": "语义：“喝”指饮用液体，不能用来处理作业，与句意冲突。", "烤": "搭配：“烤”多用于食物，不说烤作业。"}, "sentence_index": 6, "correct_answer": "减少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "十减少三，等于七。", "explanation": "这里应该用〈减去〉。算式中的减法要用减去，减少说数量变少，不用于算式。"}, {"text": "他的汉语水平减少了。", "explanation": "这里应该用〈提高〉。水平的变化要说提高或下降，减少只用于数量。"}, {"text": "爷爷的视力减少了。", "explanation": "这里应该用〈减退〉。视力等能力的衰退要用减退，减少只用于数量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "公司的员工减少了到三个人。", "corrected_sentence": "公司的员工减少到了三个人。", "error_description": "“了”位置错误：“减少到”是动词加补语的结构，“了”应放在补语“到”之后，应说“减少到了三个人”，不能说“减少了到三个人”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20774, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些年，城市的污染减少地很明显。", "corrected_sentence": "这些年，城市的污染减少得很明显。", "error_description": "补语标记用错：表示程度的补语要用“得”，不能用“地”，应说“减少得很明显”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f08eafa2-c770-4ee3-b013-116e42cbb10e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "费钱", "is_correct": true, "explanation": "正确。费钱指花费很多钱，与省钱意思相反。"}, {"text": "购买", "is_correct": false, "explanation": "购买指付钱得到东西，与省钱没有对立关系。"}, {"text": "投资", "is_correct": false, "explanation": "投资指把钱用于盈利，不是与省钱相对的词。"}, {"text": "赚取", "is_correct": false, "explanation": "赚取指获得收入，与省钱不是反义关系。"}], "correct_answer": "费钱", "explanations": {"费钱": "正确。费钱指花费很多钱，与省钱意思相反。", "购买": "购买指付钱得到东西，与省钱没有对立关系。", "投资": "投资指把钱用于盈利，不是与省钱相对的词。", "赚取": "赚取指获得收入，与省钱不是反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "费钱", "is_correct": true, "explanation": "正确。费钱指花费很多钱，与省钱意思相反。"}, {"text": "借贷", "is_correct": false, "explanation": "借贷指借入或借出钱财，与省钱没有对立关系。"}, {"text": "兑换", "is_correct": false, "explanation": "兑换指把一种货币换成另一种，不是与省钱相对的词。"}, {"text": "收取", "is_correct": false, "explanation": "收取指接收或征收钱物，与省钱不是反义关系。"}], "correct_answer": "费钱", "explanations": {"费钱": "正确。费钱指花费很多钱，与省钱意思相反。", "借贷": "借贷指借入或借出钱财，与省钱没有对立关系。", "兑换": "兑换指把一种货币换成另一种，不是与省钱相对的词。", "收取": "收取指接收或征收钱物，与省钱不是反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "省钱就是不花太多的钱。", "primary_collocate": null, "pronunciation": "shěng qián", "ipa": "ʂɤŋ˨˩˦ tɕʰjɛn˧˥", "syllable_count": 2, "sentences": [{"text": "我想省钱，所以自己带饭。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比打车更省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每个月都省钱买书。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "买便宜的东西可以省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说在家做饭更省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们这次旅行想尽量省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他为了省钱，走路去上班。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样买菜一点也不省钱。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会省钱，一个月只花一千块。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在网上买东西能省钱，也很方便。", "target_word": "省钱", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "省了钱", "label": "体标"}, {"form": "省过钱", "label": "体标"}, {"form": "省点钱", "label": "离合"}], "register": "口语", "sense_fingerprint": "少花钱、节约开支", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "省钱", "is_correct": true, "explanation": "正确。省钱指不花太多的钱。"}, {"text": "剩钱", "is_correct": false, "explanation": "剩钱 shèng qián 与 shěng qián 声调不同（第四声与第三声），意思是剩下的钱。"}, {"text": "赏钱", "is_correct": false, "explanation": "赏钱 shǎng qián 与 shěng qián 韵母不同（ang 与 eng），意思是赏赐或小费。"}, {"text": "整钱", "is_correct": false, "explanation": "整钱 zhěng qián 与 shěng qián 声母不同（zh 与 sh），意思是整数的钱，与零钱相对。"}], "explanations": {"省钱": "正确。省钱指不花太多的钱。", "剩钱": "剩钱 shèng qián 与 shěng qián 声调不同（第四声与第三声），意思是剩下的钱。", "赏钱": "赏钱 shǎng qián 与 shěng qián 韵母不同（ang 与 eng），意思是赏赐或小费。", "整钱": "整钱 zhěng qián 与 shěng qián 声母不同（zh 与 sh），意思是整数的钱，与零钱相对。"}, "sentence_index": null, "correct_answer": "省钱"}, "level_3": {"options": [{"text": "省钱", "is_correct": true, "explanation": "正确。省钱与后半句“所以自己带饭”构成因果，符合“想省钱”的理由。"}, {"text": "花钱", "is_correct": false, "explanation": "语义：花钱与“所以自己带饭”的理由相反，自己带饭正是为了少花钱。"}, {"text": "挣钱", "is_correct": false, "explanation": "语义：挣钱是获得收入，与“自己带饭”之间没有因果关系。"}, {"text": "请客", "is_correct": false, "explanation": "搭配：“请客”要接被请的人，不能与“我想……，所以自己带饭”组成合理的因果。"}], "explanations": {"省钱": "正确。省钱与后半句“所以自己带饭”构成因果，符合“想省钱”的理由。", "花钱": "语义：花钱与“所以自己带饭”的理由相反，自己带饭正是为了少花钱。", "挣钱": "语义：挣钱是获得收入，与“自己带饭”之间没有因果关系。", "请客": "搭配：“请客”要接被请的人，不能与“我想……，所以自己带饭”组成合理的因果。"}, "sentence_index": 0, "correct_answer": "省钱"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他靠卖菜省钱，每个月收入五千块。", "explanation": "这里应该用〈挣钱〉。省钱指少花钱，靠卖菜获得收入要用挣钱。"}, {"text": "他每个月都去银行省钱。", "explanation": "这里应该用〈存钱〉。去银行是为了存钱，省钱指少花钱，不能用于银行。"}, {"text": "他这个人一向乱省钱。", "explanation": "这里应该用〈花钱〉。“乱”指随便花钱，省钱指少花钱，二者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "省钱", "is_correct": true, "explanation": "正确。“为了省钱”说明走路去上班的目的，与句意一致。"}, {"text": "乘车", "is_correct": false, "explanation": "语义：乘车与“走路去上班”相互矛盾，不能作为“为了”的目的。"}, {"text": "打车", "is_correct": false, "explanation": "语义：打车与“走路去上班”的做法冲突，句子的前后逻辑不通。"}, {"text": "赶时间", "is_correct": false, "explanation": "语义：走路去上班比打车或乘车慢，与“为了赶时间”的目的相反。"}], "explanations": {"省钱": "正确。“为了省钱”说明走路去上班的目的，与句意一致。", "乘车": "语义：乘车与“走路去上班”相互矛盾，不能作为“为了”的目的。", "打车": "语义：打车与“走路去上班”的做法冲突，句子的前后逻辑不通。", "赶时间": "语义：走路去上班比打车或乘车慢，与“为了赶时间”的目的相反。"}, "sentence_index": 6, "correct_answer": "省钱"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次投资他省钱了。", "explanation": "这里应该用〈赔钱〉。省钱指少花钱，投资亏损要用赔钱。"}, {"text": "他在柜台前省钱，每天能拿到两千块。", "explanation": "这里应该用〈赚钱〉。省钱指少花钱，靠工作拿到收入要用赚钱。"}, {"text": "他手头紧，只好向朋友省钱。", "explanation": "这里应该用〈借钱〉。手头紧时向朋友要钱要用借钱，省钱不能表示借入。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他这个月省了很多了钱。", "corrected_sentence": "他这个月省了很多钱。", "error_description": "错误在于“了”的位置：“了”应紧跟动词“省”，不能插在“很多”和“钱”之间。错误形式：“省了很多了钱”；正确形式：“省了很多钱”，只需删去多余的“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20776, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她这个月省钱得很厉害。", "corrected_sentence": "她这个月省钱省得很厉害。", "error_description": "错误形式：“省钱得很厉害”；正确形式：“省钱省得很厉害”。带补语“得”的结构要重复动词，即“V+宾语+V+得+补语”，不能省去第二个“省”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
