INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "箱子是一个方方的容器，可以用来装东西。", "primary_collocate": null, "pronunciation": "xiāng zi", "ipa": "ɕjɑŋ˥ tsɨ", "syllable_count": 2, "sentences": [{"text": "这个箱子是方的，可以装很多东西。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用箱子装玩具。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌子下面有一个大箱子。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他搬着一个重箱子上楼。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子满了，放不进去了。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把箱子放在门口。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那只箱子里全是书。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "箱子坏了，不能再用。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们一起把箱子抬进房间。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧箱子里有爷爷的照片。", "target_word": "箱子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "只", "label": "量词"}, {"form": "纸箱", "label": "复合词"}], "register": "中性", "sense_fingerprint": "方形的容器，用来装东西", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5846132b-121e-4712-a287-c75705189ab3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：方形的收纳容器，即听到的词。"}, {"text": "巷子", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷。"}, {"text": "仙子", "is_correct": false, "explanation": "xiān 与 xiāng 韵尾不同（n 与 ng），意思是仙女。"}, {"text": "橡子", "is_correct": false, "explanation": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是橡树的果实。"}], "explanations": {"箱子": "箱子：方形的收纳容器，即听到的词。", "巷子": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是小巷。", "仙子": "xiān 与 xiāng 韵尾不同（n 与 ng），意思是仙女。", "橡子": "xiàng（第四声）与 xiāng（第一声）声调不同，意思是橡树的果实。"}, "sentence_index": null, "correct_answer": "箱子"}, "level_3": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：方形的容器，可以装很多东西，符合语境。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头是实心的硬块，不能用来装东西，与“可以装很多东西”矛盾。"}, {"text": "地毯", "is_correct": false, "explanation": "语义：地毯是铺在地上的织物，不是容器，不能装东西。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户是墙上的开口，不是用来装东西的。"}], "explanations": {"箱子": "箱子：方形的容器，可以装很多东西，符合语境。", "石头": "语义：石头是实心的硬块，不能用来装东西，与“可以装很多东西”矛盾。", "地毯": "语义：地毯是铺在地上的织物，不是容器，不能装东西。", "窗户": "语义：窗户是墙上的开口，不是用来装东西的。"}, "sentence_index": 0, "correct_answer": "箱子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把一条箱子放在门口。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，箱子不能这样数。"}, {"text": "厨房里有一朵箱子。", "explanation": "这里应该用〈个〉。〈朵〉用于花、云等，箱子不能这样数。"}, {"text": "桌上摆着一片箱子。", "explanation": "这里应该用〈个〉。〈片〉用于扁平的薄片，箱子不是这样的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "箱子", "is_correct": true, "explanation": "箱子：能装东西的容器，里面可以全是书，符合语境。"}, {"text": "鞋子", "is_correct": false, "explanation": "语义：鞋子是穿在脚上的，里面不装书。"}, {"text": "花瓶", "is_correct": false, "explanation": "语义：花瓶是用来插花的，不用来装书。"}, {"text": "苹果", "is_correct": false, "explanation": "体貌：苹果是实心的果实，里面没有空间装书。"}], "explanations": {"箱子": "箱子：能装东西的容器，里面可以全是书，符合语境。", "鞋子": "语义：鞋子是穿在脚上的，里面不装书。", "花瓶": "语义：花瓶是用来插花的，不用来装书。", "苹果": "体貌：苹果是实心的果实，里面没有空间装书。"}, "sentence_index": 6, "correct_answer": "箱子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他从柜子里拿出一根箱子。", "explanation": "这里应该用〈个〉。〈根〉用于细长的东西，箱子不能这样数。"}, {"text": "床边放着一颗箱子。", "explanation": "这里应该用〈个〉。〈颗〉用于粒状、圆形的小东西，箱子不能这样数。"}, {"text": "院子里有一棵箱子。", "explanation": "这里应该用〈个〉。〈棵〉用于树、草等整株植物，箱子不能这样数。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在床下找到一片旧箱子。", "corrected_sentence": "他在床下找到一个旧箱子。", "error_description": "错误：“一片旧箱子”。正确：“一个旧箱子”。箱子是立体的容器，量词用“个”，“片”用于扁平的薄片。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20782, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把箱子搬了进屋里。", "corrected_sentence": "他把箱子搬进了屋里。", "error_description": "错误：“搬了进屋里”。正确：“搬进了屋里”。“搬进”是动补结构，“了”应放在“进”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a0ffc170-d033-4a78-a5be-ee4c7f454139') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多", "is_correct": true, "explanation": "正确：“多”与“少”（数量不多）意义相反。"}, {"text": "快", "is_correct": false, "explanation": "“快”指速度，与“少”（数量）没有反义关系。"}, {"text": "高", "is_correct": false, "explanation": "“高”指高度，与“少”的数量义没有反义关系。"}, {"text": "轻", "is_correct": false, "explanation": "“轻”指重量，与“少”没有反义关系。"}], "correct_answer": "多", "explanations": {"多": "正确：“多”与“少”（数量不多）意义相反。", "快": "“快”指速度，与“少”（数量）没有反义关系。", "高": "“高”指高度，与“少”的数量义没有反义关系。", "轻": "“轻”指重量，与“少”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "多", "is_correct": true, "explanation": "正确：“多”与“少”（数量不多）意义相反。"}, {"text": "长", "is_correct": false, "explanation": "“长”的反义词是“短”，与“少”没有反义关系。"}, {"text": "厚", "is_correct": false, "explanation": "“厚”的反义词是“薄”，与“少”没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "“深”的反义词是“浅”，与“少”没有反义关系。"}], "correct_answer": "多", "explanations": {"多": "正确：“多”与“少”（数量不多）意义相反。", "长": "“长”的反义词是“短”，与“少”没有反义关系。", "厚": "“厚”的反义词是“薄”，与“少”没有反义关系。", "深": "“深”的反义词是“浅”，与“少”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "不多，数量小。", "primary_collocate": null, "pronunciation": "shǎo", "ipa": "ʂɑʊ˨˩˦", "syllable_count": 1, "sentences": [{"text": "今天来的人很少。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的雨水比较少。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他话少，不爱说笑。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家里的书很少，只有几本。", "target_word": "少", "complexity_tier": "T3", "furigana": "wǒ jiā lǐ de shū hěn shǎo, zhǐ yǒu jǐ běn。", "sentence_source": "generated"}, {"text": "菜里盐太少了，不好吃。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "最近睡得少，我很累。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的饭馆少，晚上不好找吃的。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的水果太少，不够大家吃。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天这里的雪很少。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "班里学生少，老师能照顾每个人。", "target_word": "少", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "数量不多", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "少", "is_correct": true, "explanation": "正确答案：少（shǎo），意思是数量不多。"}, {"text": "扫", "is_correct": false, "explanation": "sǎo 与 shǎo 声母不同（s 与 sh），“扫”意思是打扫。"}, {"text": "烧", "is_correct": false, "explanation": "shāo（第一声）与 shǎo（第三声）声调不同，“烧”意思是燃烧。"}, {"text": "吵", "is_correct": false, "explanation": "chǎo 与 shǎo 声母不同（ch 与 sh），“吵”意思是吵闹。"}, {"text": "找", "is_correct": false, "explanation": "zhǎo 与 shǎo 声母不同（zh 与 sh），“找”意思是寻找。"}], "explanations": {"少": "正确答案：少（shǎo），意思是数量不多。", "扫": "sǎo 与 shǎo 声母不同（s 与 sh），“扫”意思是打扫。", "烧": "shāo（第一声）与 shǎo（第三声）声调不同，“烧”意思是燃烧。", "吵": "chǎo 与 shǎo 声母不同（ch 与 sh），“吵”意思是吵闹。", "找": "zhǎo 与 shǎo 声母不同（zh 与 sh），“找”意思是寻找。"}, "sentence_index": null, "correct_answer": "少"}, "level_3": {"options": [{"text": "少", "is_correct": true, "explanation": "正确：“今天来的人很少”，表示人数不多。"}, {"text": "快", "is_correct": false, "explanation": "语义：“快”描述速度，不能用来形容“来的人”的数量。"}, {"text": "重", "is_correct": false, "explanation": "搭配：“重”说分量，不能修饰人的数量。"}, {"text": "远", "is_correct": false, "explanation": "语义：“远”指距离，“来的人很远”语义不通。"}], "explanations": {"少": "正确：“今天来的人很少”，表示人数不多。", "快": "语义：“快”描述速度，不能用来形容“来的人”的数量。", "重": "搭配：“重”说分量，不能修饰人的数量。", "远": "语义：“远”指距离，“来的人很远”语义不通。"}, "sentence_index": 0, "correct_answer": "少"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这张纸很少。", "explanation": "这里应该用〈薄〉。“少”表示数量不多，纸的厚薄要用“薄”。"}, {"text": "这篇文章很少。", "explanation": "这里应该用〈好〉。“少”说数量，文章的好坏要用“好”或“差”。"}, {"text": "这个湖很少。", "explanation": "这里应该用〈深〉。“少”说的是数量，不能用来形容湖的深浅。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20786, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "少", "is_correct": true, "explanation": "正确答案：少（shǎo），意思是数量不多。"}, {"text": "稍", "is_correct": false, "explanation": "shāo（第一声）与 shǎo（第三声）声调不同，“稍”意思是稍微。"}, {"text": "嫂", "is_correct": false, "explanation": "sǎo 与 shǎo 声母不同（s 与 sh），“嫂”意思是嫂子。"}, {"text": "炒", "is_correct": false, "explanation": "chǎo 与 shǎo 声母不同（ch 与 sh），“炒”意思是翻炒。"}, {"text": "哨", "is_correct": false, "explanation": "shào（第四声）与 shǎo（第三声）声调不同，“哨”意思是口哨。"}], "explanations": {"少": "正确答案：少（shǎo），意思是数量不多。", "稍": "shāo（第一声）与 shǎo（第三声）声调不同，“稍”意思是稍微。", "嫂": "sǎo 与 shǎo 声母不同（s 与 sh），“嫂”意思是嫂子。", "炒": "chǎo 与 shǎo 声母不同（ch 与 sh），“炒”意思是翻炒。", "哨": "shào（第四声）与 shǎo（第三声）声调不同，“哨”意思是口哨。"}, "sentence_index": null, "correct_answer": "少"}, "level_3": {"options": [{"text": "少", "is_correct": true, "explanation": "正确：“这里的饭馆少”，表示饭馆数量不多。"}, {"text": "乱", "is_correct": false, "explanation": "语义：“乱”形容秩序混乱，不能修饰饭馆的数量。"}, {"text": "轻", "is_correct": false, "explanation": "搭配：“轻”说分量，不能修饰“饭馆”的数量。"}, {"text": "贵", "is_correct": false, "explanation": "语义：“贵”说价格，与“晚上不好找吃的”的因果关系不通。"}], "explanations": {"少": "正确：“这里的饭馆少”，表示饭馆数量不多。", "乱": "语义：“乱”形容秩序混乱，不能修饰饭馆的数量。", "轻": "搭配：“轻”说分量，不能修饰“饭馆”的数量。", "贵": "语义：“贵”说价格，与“晚上不好找吃的”的因果关系不通。"}, "sentence_index": 6, "correct_answer": "少"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这座山很少。", "explanation": "这里应该用〈高〉。“少”只表示数量不多，不能用来形容山的高矮。"}, {"text": "这条路很少。", "explanation": "这里应该用〈长〉。“少”不能用来形容路的长短。"}, {"text": "这盏灯很少。", "explanation": "这里应该用〈亮〉。“少”只说数量，灯的明暗要用“亮”或“暗”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
