INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20790, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "菜是可以吃的植物。", "primary_collocate": null, "pronunciation": "cài", "ipa": "tsʰaɪ̯˥˩", "syllable_count": 1, "sentences": [{"text": "我家后院种了很多菜。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些菜又新鲜又便宜。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈每天早上去市场买菜。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子不爱吃菜，只想吃肉。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先把菜洗干净，再切成小块。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多吃菜对身体好。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在地里种的菜长得很好。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种菜要用热水烫一下。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把菜放进篮子里。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天的菜比夏天的贵。", "target_word": "菜", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "棵", "label": "量词"}, {"form": "青菜", "label": "复合"}, {"form": "白菜", "label": "复合"}], "register": "口语", "sense_fingerprint": "可以吃的蔬菜类植物", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2ceb66b7-4790-48b5-8313-3c93963dc888') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20790, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "菜", "is_correct": true, "explanation": "正确。菜是可以吃的植物。"}, {"text": "才", "is_correct": false, "explanation": "才 cái 与 cài 声调不同（第二声与第四声），意思是“刚刚”。"}, {"text": "猜", "is_correct": false, "explanation": "猜 cāi 与 cài 声调不同（第一声与第四声），意思是猜测。"}, {"text": "在", "is_correct": false, "explanation": "在 zài 与 cài 声母不同（z 与 c，c 送气），意思是“位于”。"}], "explanations": {"菜": "正确。菜是可以吃的植物。", "才": "才 cái 与 cài 声调不同（第二声与第四声），意思是“刚刚”。", "猜": "猜 cāi 与 cài 声调不同（第一声与第四声），意思是猜测。", "在": "在 zài 与 cài 声母不同（z 与 c，c 送气），意思是“位于”。"}, "sentence_index": null, "correct_answer": "菜"}, "level_3": {"options": [{"text": "菜", "is_correct": true, "explanation": "正确。菜是可以种在后院的植物，符合“种了很多”。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“种”后面一般接植物，不能与“书”搭配。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“种”不能与“衣服”搭配，衣服不能种在后院。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不是植物，不可能种在后院，与句意矛盾。"}], "explanations": {"菜": "正确。菜是可以种在后院的植物，符合“种了很多”。", "书": "搭配：“种”后面一般接植物，不能与“书”搭配。", "衣服": "搭配：“种”不能与“衣服”搭配，衣服不能种在后院。", "汽车": "语义：汽车不是植物，不可能种在后院，与句意矛盾。"}, "sentence_index": 0, "correct_answer": "菜"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我每天吃三顿菜。", "explanation": "这里应该用〈饭〉。三顿指正餐的次数，吃正餐要用饭，菜不能用“顿”计量。"}, {"text": "我点了一只菜。", "explanation": "这里应该用〈盘〉或〈道〉。菜不用“只”作量词，“只”用于动物。"}, {"text": "我想喝热菜。", "explanation": "这里应该用〈汤〉。菜是吃的菜肴，不是喝的；要喝的应该用汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20790, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "菜", "is_correct": true, "explanation": "正确。菜是可以吃的植物。"}, {"text": "再", "is_correct": false, "explanation": "再 zài 与 cài 声母不同（z 与 c），意思是“再次”。"}, {"text": "赛", "is_correct": false, "explanation": "赛 sài 与 cài 声母不同（s 与 c），意思是比赛。"}, {"text": "盖", "is_correct": false, "explanation": "盖 gài 与 cài 声母不同（g 与 c），意思是覆盖。"}], "explanations": {"菜": "正确。菜是可以吃的植物。", "再": "再 zài 与 cài 声母不同（z 与 c），意思是“再次”。", "赛": "赛 sài 与 cài 声母不同（s 与 c），意思是比赛。", "盖": "盖 gài 与 cài 声母不同（g 与 c），意思是覆盖。"}, "sentence_index": null, "correct_answer": "菜"}, "level_3": {"options": [{"text": "菜", "is_correct": true, "explanation": "正确。菜是在地里种的植物，可以长得很好。"}, {"text": "桌子", "is_correct": false, "explanation": "语义：桌子不会生长，不能说“长得很好”。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是植物，不会生长，与“种的”冲突。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：“种”不能与“冰箱”搭配，冰箱不能种在地里。"}], "explanations": {"菜": "正确。菜是在地里种的植物，可以长得很好。", "桌子": "语义：桌子不会生长，不能说“长得很好”。", "椅子": "语义：椅子不是植物，不会生长，与“种的”冲突。", "冰箱": "搭配：“种”不能与“冰箱”搭配，冰箱不能种在地里。"}, "sentence_index": 6, "correct_answer": "菜"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她穿着新菜。", "explanation": "这里应该用〈衣服〉。穿的是衣服，菜是可以吃的，不能穿。"}, {"text": "早上他喝了菜。", "explanation": "这里应该用〈牛奶〉。喝的是饮料，菜是食物，不能用来喝。"}, {"text": "孩子在院子里踢菜。", "explanation": "这里应该用〈足球〉。踢的是球，菜不是可以踢的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20790, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这菜道很好吃。", "corrected_sentence": "这道菜很好吃。", "error_description": "错误形式：“这菜道”；正确形式：“这道菜”。量词“道”应紧跟指示代词“这”，放在名词“菜”之前。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20790, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他买了两只菜，都吃完了。", "corrected_sentence": "他买了两盘菜，都吃完了。", "error_description": "错误形式：“两只菜”；正确形式：“两盘菜”。“只”用于动物，盛放的菜肴要用量词“盘”或“道”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9ee8d5e-f8f0-4dc2-b155-6b198a83a879') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
