INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "堆肥就是把树叶、果皮等垃圾堆在一起，让它们变成肥料。", "primary_collocate": null, "pronunciation": "duī féi", "ipa": "tuei˥ fei˧˥", "syllable_count": 2, "sentences": [{"text": "爷爷用树叶做了堆肥。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们把果皮放进堆肥里。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥能让花园里的菜长得更好。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做堆肥要把树叶和果皮放在一起。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋堆肥是邻居送给我的。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "堆肥需要几个月才能做好。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民在地里撒了一些堆肥。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天把剩菜倒进堆肥里。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用堆肥种花，花开得很漂亮。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好的堆肥闻起来没有臭味。", "target_word": "堆肥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆肥箱", "label": "复合"}, {"form": "一袋堆肥", "label": "量词"}], "register": "中性", "sense_fingerprint": "垃圾堆放后变成的肥料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '73bdc592-5317-4323-ab99-fe56d44fcace') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "“堆肥”是把树叶、果皮等垃圾堆放发酵后得到的肥料，符合“用树叶做了”的句意。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：树叶不能做成雨水，句意不通。"}, {"text": "饺子", "is_correct": false, "explanation": "语义：树叶不能包成饺子，也不能食用，句意不通。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“做”一般不用于手机这类工业产品，应说“生产”。"}], "explanations": {"堆肥": "“堆肥”是把树叶、果皮等垃圾堆放发酵后得到的肥料，符合“用树叶做了”的句意。", "雨水": "语义：树叶不能做成雨水，句意不通。", "饺子": "语义：树叶不能包成饺子，也不能食用，句意不通。", "手机": "搭配：“做”一般不用于手机这类工业产品，应说“生产”。"}, "sentence_index": 0, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "农场每天用堆肥喂猪。", "explanation": "这里应该用〈饲料〉。堆肥是给土地用的肥料，不能拿来喂猪；喂猪要用饲料。"}, {"text": "工人们用水泥和堆肥砌墙。", "explanation": "这里应该用〈沙子〉。堆肥是肥料，不能用来砌墙；砌墙要用水泥和沙子。"}, {"text": "他每天用堆肥擦脸。", "explanation": "这里应该用〈毛巾〉。堆肥是肥料，不能用来擦脸；擦脸要用毛巾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "堆肥", "is_correct": true, "explanation": "“堆肥”是可以撒在地里的肥料，符合“农民在地里撒了一些”的句意。"}, {"text": "电视", "is_correct": false, "explanation": "语义：电视不能撒在地里，句意不通。"}, {"text": "汽车", "is_correct": false, "explanation": "语义：汽车不能撒在地里，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "搭配：“撒”一般用于颗粒、粉末或种子，不说撒“书”。"}], "explanations": {"堆肥": "“堆肥”是可以撒在地里的肥料，符合“农民在地里撒了一些”的句意。", "电视": "语义：电视不能撒在地里，句意不通。", "汽车": "语义：汽车不能撒在地里，句意不通。", "书": "搭配：“撒”一般用于颗粒、粉末或种子，不说撒“书”。"}, "sentence_index": 6, "correct_answer": "堆肥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗堆肥很好吃，大家都抢着吃。", "explanation": "堆肥是给土地用的肥料，不能吃。这句话用的是“食物”的意思，与堆肥的词义不符。"}, {"text": "浴室里放着一块堆肥，用来洗手。", "explanation": "这里应该用〈肥皂〉。堆肥是肥料，不能用来洗手，洗手要用肥皂。"}, {"text": "他每天早上用堆肥刷牙。", "explanation": "这里应该用〈牙膏〉。堆肥是肥料，不能用来刷牙；刷牙要用牙膏。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "院子里有一条堆肥。", "corrected_sentence": "院子里有一堆堆肥。", "error_description": "错误：量词用错。“条”用于细长的东西，堆肥成堆，应用“堆”。应说“一堆堆肥”，不能说“一条堆肥”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20800, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈每天把剩饭倒堆肥里。", "corrected_sentence": "妈妈每天把剩饭倒进堆肥里。", "error_description": "错误：“倒”后缺少方向或位置成分。应说“倒进堆肥里”或“倒在堆肥里”，不能说“倒堆肥里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e637d3f7-ec17-4a3b-9057-4a71e65be333') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低效", "is_correct": true, "explanation": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。"}, {"text": "漂亮", "is_correct": false, "explanation": "与“高效”没有反义关系，“漂亮”形容外貌。"}, {"text": "柔软", "is_correct": false, "explanation": "与“高效”没有反义关系，“柔软”形容质地。"}, {"text": "清楚", "is_correct": false, "explanation": "与“高效”没有反义关系，“清楚”形容明白或清晰的程度。"}], "correct_answer": "低效", "explanations": {"低效": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。", "漂亮": "与“高效”没有反义关系，“漂亮”形容外貌。", "柔软": "与“高效”没有反义关系，“柔软”形容质地。", "清楚": "与“高效”没有反义关系，“清楚”形容明白或清晰的程度。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低效", "is_correct": true, "explanation": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。"}, {"text": "明亮", "is_correct": false, "explanation": "与“高效”没有反义关系，“明亮”形容光线强或色彩鲜艳。"}, {"text": "干净", "is_correct": false, "explanation": "与“高效”没有反义关系，“干净”形容洁净的状态。"}, {"text": "窄", "is_correct": false, "explanation": "与“高效”没有反义关系，“窄”形容宽度小。"}], "correct_answer": "低效", "explanations": {"低效": "“高效”与“低效”是反义词：高效指效率高，低效指效率低。", "明亮": "与“高效”没有反义关系，“明亮”形容光线强或色彩鲜艳。", "干净": "与“高效”没有反义关系，“干净”形容洁净的状态。", "窄": "与“高效”没有反义关系，“窄”形容宽度小。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "做事快，效果好。", "primary_collocate": null, "pronunciation": "gāo xiào", "ipa": "kɑʊ̯˥ ɕiɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "他工作很高效，一天就做完了。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个新方法非常高效。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开会要高效，不要说太多没用的话。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是一个很高效的老师。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "用这台机器洗衣服又快又干净，真高效。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们需要一种高效的学习方法。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家合作得很高效，两小时就搞定了。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "高效的人会先做重要的事。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的服务很高效，十分钟就办好了。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他睡得很好，所以白天工作特别高效。", "target_word": "高效", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高效率", "label": "复合"}], "register": "中性", "sense_fingerprint": "做事速度快、效果好", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1994afce-084b-4c4b-8b0f-90dace7d412c') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高效", "is_correct": true, "explanation": "“工作很高效”说做事效率高，与“一天就做完了”前后一致。"}, {"text": "慢", "is_correct": false, "explanation": "语义：工作很慢却一天就做完了，前后矛盾。"}, {"text": "漂亮", "is_correct": false, "explanation": "搭配：“工作”不能用“漂亮”来形容。"}, {"text": "便宜", "is_correct": false, "explanation": "语义：工作不能说“便宜”，与句意不通。"}], "explanations": {"高效": "“工作很高效”说做事效率高，与“一天就做完了”前后一致。", "慢": "语义：工作很慢却一天就做完了，前后矛盾。", "漂亮": "搭配：“工作”不能用“漂亮”来形容。", "便宜": "语义：工作不能说“便宜”，与句意不通。"}, "sentence_index": 0, "correct_answer": "高效"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "消防员高效跑进了火场。", "explanation": "这里应该用〈迅速〉。高效侧重做事的效率和效果，不用来形容跑动的速度。"}, {"text": "他的道歉很高效，我们和好了。", "explanation": "这里应该用〈有效〉。高效指做事快、效果好，不能用来形容道歉的作用。"}, {"text": "小狗很高效地跑回了家。", "explanation": "这里应该用〈快〉。高效强调做事的效率，形容跑动的速度要用“快”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高效", "is_correct": true, "explanation": "“合作得很高效”说合作的效率高，与“两小时就搞定了”一致。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“合作”不能用“甜”来形容。"}, {"text": "矮", "is_correct": false, "explanation": "体貌：合作没有高矮之分，不能说“合作得很矮”。"}, {"text": "咸", "is_correct": false, "explanation": "搭配：“合作”不能用“咸”来形容。"}], "explanations": {"高效": "“合作得很高效”说合作的效率高，与“两小时就搞定了”一致。", "甜": "搭配：“合作”不能用“甜”来形容。", "矮": "体貌：合作没有高矮之分，不能说“合作得很矮”。", "咸": "搭配：“合作”不能用“咸”来形容。"}, "sentence_index": 6, "correct_answer": "高效"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他身手高效，几下就爬上了树。", "explanation": "这里应该用〈敏捷〉。高效指做事的效率，不用来形容身手或动作的灵活。"}, {"text": "她的步子很高效，像跳舞一样。", "explanation": "这里应该用〈轻快〉。高效不用来形容步子或走路的样子。"}, {"text": "这只小猫的毛很高效，摸上去很舒服。", "explanation": "这里应该用〈柔软〉。高效形容做事的效率，不用来形容毛的质地，应说“柔软”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他高效的完成了任务。", "corrected_sentence": "他高效地完成了任务。", "error_description": "“的”“地”混用：“高效”作状语修饰动词“完成”，后面要加“地”，应说“高效地完成”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20806, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他学习很得高效。", "corrected_sentence": "他学习得很高效。", "error_description": "补语位置错误：补语标记“得”要紧跟动词，应说“学习得很高效”，不能说“学习很得高效”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5117ed1-d7d9-4cc4-a629-8feb932f8911') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
