INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20818, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "氮是一种气体，空气中就有它。", "primary_collocate": null, "pronunciation": "dàn", "ipa": "tan˥˩", "syllable_count": 1, "sentences": [{"text": "我们呼吸的空气里有氮。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "氮看不见，也闻不到。", "target_word": "氮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "空气中大部分是氮。", "target_word": "氮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草需要氮才能长得好。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书上说，氮是一种气体。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师问我空气里什么最多，我说是氮。", "target_word": "氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "氮和氧都是气体。", "target_word": "氮", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个瓶子里装着氮。", "target_word": "氮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地里的草缺氮，所以颜色发黄。", "target_word": "氮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在实验室里学过氮的知识。", "target_word": "氮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "氮气", "label": "复合词"}], "register": "中性", "sense_fingerprint": "空气中的一种气体氮（通俗讲法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20818, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确答案：氮（dàn），空气中的一种气体。"}, {"text": "胆", "is_correct": false, "explanation": "dǎn（第三声）与 dàn（第四声）声调不同，意思是胆囊或勇气。"}, {"text": "担", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，意思是挑、承担。"}, {"text": "叹", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是叹气。"}], "explanations": {"氮": "正确答案：氮（dàn），空气中的一种气体。", "胆": "dǎn（第三声）与 dàn（第四声）声调不同，意思是胆囊或勇气。", "担": "dān（第一声）与 dàn（第四声）声调不同，意思是挑、承担。", "叹": "tàn 与 dàn 声母不同（t 与 d），意思是叹气。"}, "sentence_index": null, "correct_answer": "氮"}, "level_3": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确：“氮”是空气中的一种气体，与“我们呼吸的空气里有”相符。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子是家具，不是气体，不会存在于我们呼吸的空气里，句意不通。"}, {"text": "书", "is_correct": false, "explanation": "语义：书是纸制品，不会弥散在空气中，“空气里有书”句意不通。"}, {"text": "糖", "is_correct": false, "explanation": "搭配：“空气里有”一般搭配气体，固体的“糖”不这样说。"}], "explanations": {"氮": "正确：“氮”是空气中的一种气体，与“我们呼吸的空气里有”相符。", "椅子": "语义：椅子是家具，不是气体，不会存在于我们呼吸的空气里，句意不通。", "书": "语义：书是纸制品，不会弥散在空气中，“空气里有书”句意不通。", "糖": "搭配：“空气里有”一般搭配气体，固体的“糖”不这样说。"}, "sentence_index": 0, "correct_answer": "氮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "汽车用氮做燃料，很环保。", "explanation": "这里应该用〈氢〉。氢可以燃烧，用作燃料；氮不能燃烧，不能这样用。"}, {"text": "氮常用来消毒伤口。", "explanation": "这里应该用〈碘〉。碘酒可用于消毒伤口；氮没有消毒作用。"}, {"text": "病人吸入氮，可以补充身体需要的氧。", "explanation": "这里应该用〈氧〉。补充人体需要的是氧，氮不能供人呼吸，吸入纯氮反而会窒息。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20818, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确答案：氮（dàn），空气中的一种气体。"}, {"text": "荡", "is_correct": false, "explanation": "dàng 与 dàn 韵母不同（ang 与 an），意思是摇动。"}, {"text": "丹", "is_correct": false, "explanation": "dān（第一声）与 dàn（第四声）声调不同，意思是红色。"}, {"text": "炭", "is_correct": false, "explanation": "tàn 与 dàn 声母不同（t 与 d），意思是木炭。"}], "explanations": {"氮": "正确答案：氮（dàn），空气中的一种气体。", "荡": "dàng 与 dàn 韵母不同（ang 与 an），意思是摇动。", "丹": "dān（第一声）与 dàn（第四声）声调不同，意思是红色。", "炭": "tàn 与 dàn 声母不同（t 与 d），意思是木炭。"}, "sentence_index": null, "correct_answer": "氮"}, "level_3": {"options": [{"text": "氮", "is_correct": true, "explanation": "正确：“氮”是空气中的气体，与“和氧都是气体”相符。"}, {"text": "木头", "is_correct": false, "explanation": "语义：木头是固体，不是气体，与“都是气体”不合。"}, {"text": "石油", "is_correct": false, "explanation": "语义：石油是液体，不是气体，与“都是气体”不合。"}, {"text": "蜂蜜", "is_correct": false, "explanation": "搭配：“和……都是气体”要求同类的气态物质，“蜂蜜”不搭配。"}], "explanations": {"氮": "正确：“氮”是空气中的气体，与“和氧都是气体”相符。", "木头": "语义：木头是固体，不是气体，与“都是气体”不合。", "石油": "语义：石油是液体，不是气体，与“都是气体”不合。", "蜂蜜": "搭配：“和……都是气体”要求同类的气态物质，“蜂蜜”不搭配。"}, "sentence_index": 6, "correct_answer": "氮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个瓶子里装着一座氮。", "explanation": "这里应该用〈瓶〉。“座”用于山、桥、建筑等，不用来数气体；瓶中装的氮要说“一瓶氮”。"}, {"text": "自来水厂用氮来消毒。", "explanation": "这里应该用〈氯〉。自来水厂消毒用氯，氮没有消毒作用。"}, {"text": "气球里充的是氮，可以飘起来。", "explanation": "这里应该用〈氦〉。氦比空气轻得多，能让气球飘起来；氮气密度与空气接近，几乎托不起气球。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20818, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "实验室买了一个氮。", "corrected_sentence": "实验室买了一瓶氮。", "error_description": "错误：气体的量词用“瓶”，不能用“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20818, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这个钢瓶里装氮着，要小心保管。", "corrected_sentence": "这个钢瓶里装着氮，要小心保管。", "error_description": "错误：动态助词“着”应紧跟动词“装”，说“装着氮”；不能把“着”放在宾语“氮”的后面，说“装氮着”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
