INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "草屑就是很小的碎草片，比如割草后落在地上的小草叶。", "primary_collocate": null, "pronunciation": "cǎo xiè", "ipa": "tsʰau˨˩˦ ɕie˥˩", "syllable_count": 2, "sentences": [{"text": "小狗在草地上滚了一身草屑。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爸爸割草，我帮他扫草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "草屑粘在我的袜子上。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他拍掉裤子上的草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "一阵风吹起地上的草屑。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "割草机停了，院子里全是草屑。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子手里抓着一把草屑。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把草屑装进袋子里。", "target_word": "草屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草屑沾到了她的白鞋上。", "target_word": "草屑", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨后，路边的草屑湿湿的。", "target_word": "草屑", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "把", "label": "量词"}], "register": "中性", "sense_fingerprint": "割草后落在地上的小碎草叶", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6c1d19cc-cc1a-4fe0-be5a-6e8d2b501730') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "草屑", "is_correct": true, "explanation": "草屑：指割草后落下的细碎草片，与“草地”的语境相符。"}, {"text": "金币", "is_correct": false, "explanation": "语义：草地上不会有金币，“滚了一身金币”不符合语境。"}, {"text": "玻璃碴", "is_correct": false, "explanation": "语义：玻璃碴锋利，小狗在草地上不会滚得一身玻璃碴。"}, {"text": "电线", "is_correct": false, "explanation": "语义：电线是金属导线，小狗不会在草地上滚得一身电线，句意不通。"}], "explanations": {"草屑": "草屑：指割草后落下的细碎草片，与“草地”的语境相符。", "金币": "语义：草地上不会有金币，“滚了一身金币”不符合语境。", "玻璃碴": "语义：玻璃碴锋利，小狗在草地上不会滚得一身玻璃碴。", "电线": "语义：电线是金属导线，小狗不会在草地上滚得一身电线，句意不通。"}, "sentence_index": 0, "correct_answer": "草屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在草地上摘了一把草屑。", "explanation": "这里应该用〈草叶〉。草屑是细碎的碎片，摘不成一片完整的叶子，要说草叶。"}, {"text": "他把草屑拔了出来。", "explanation": "这里应该用〈草根〉。草根长在土里可以拔出，草屑是碎片，拔不出来。"}, {"text": "他用草屑捆好了柴火。", "explanation": "这里应该用〈草绳〉。捆绑需要有韧性的长条材料，草屑是碎片，做不到。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "草屑", "is_correct": true, "explanation": "草屑：一把细碎的草屑可以用手抓住，与“一把”相符，句意通顺。"}, {"text": "灯泡", "is_correct": false, "explanation": "语义：灯泡易碎，孩子不会随手抓着一把灯泡。"}, {"text": "炸药", "is_correct": false, "explanation": "语义：炸药很危险，与孩子手里抓着东西的日常场景不符。"}, {"text": "钢筋", "is_correct": false, "explanation": "搭配：钢筋是建筑材料，“一把钢筋”不常见，与“抓着”的动作不协调。"}], "explanations": {"草屑": "草屑：一把细碎的草屑可以用手抓住，与“一把”相符，句意通顺。", "灯泡": "语义：灯泡易碎，孩子不会随手抓着一把灯泡。", "炸药": "语义：炸药很危险，与孩子手里抓着东西的日常场景不符。", "钢筋": "搭配：钢筋是建筑材料，“一把钢筋”不常见，与“抓着”的动作不协调。"}, "sentence_index": 6, "correct_answer": "草屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们每周修剪草屑。", "explanation": "这里应该用〈草坪〉。修剪的是长着的草坪，草屑已是碎片，不能修剪。"}, {"text": "她把草屑夹进书里做标本。", "explanation": "这里应该用〈花瓣〉。花瓣薄而完整，可以压成标本，草屑只是碎片，不能这样用。"}, {"text": "院子里开满了草屑。", "explanation": "这里应该用〈花〉。“开满”用于花朵，草屑不会开放。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他的衣服上沾了一只草屑。", "corrected_sentence": "他的衣服上沾了一撮草屑。", "error_description": "“草屑”的量词应用“撮”或“堆”，不能用“只”，“只”一般用于动物等。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20822, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的衣服上满沾了草屑。", "corrected_sentence": "他的衣服上沾满了草屑。", "error_description": "“满”是“沾”的结果补语，必须紧跟在“沾”之后，应说“沾满了草屑”；“满沾了”把补语提到动词前，是错误语序。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7033a421-d1f0-4534-a357-0c175cc7954b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
