INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20824, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "组成事物的基本成分或要素。", "primary_collocate": null, "pronunciation": "yuán sù", "ipa": "yɥɛn˧˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "水里有氢和氧两种元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "金是一种很贵的元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "空气中最多的元素是氮。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这幅画里有很多中国元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁是人体需要的一种元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师问我们：氧是什么元素？", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的设计有很多现代元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "美术的基本元素有哪些？", "target_word": "元素", "complexity_tier": "T3", "furigana": "měi shù de jīběn yuánsù yǒu nǎxiē？", "sentence_source": "generated"}, {"text": "地球上有一百多种元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这首歌里加了一些音乐元素。", "target_word": "元素", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "化学元素", "label": "复合词"}], "register": "中性", "sense_fingerprint": "组成事物的基本成分，如化学元素、文化元素", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f35b906f-46d6-4de6-ad17-6696c52b793f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20824, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "元素", "is_correct": true, "explanation": "“两种元素”指组成水的基本成分，与“氢和氧”相符，能正确填入空格。"}, {"text": "动物", "is_correct": false, "explanation": "语义：氢和氧不是动物，“水里有氢和氧两种动物”不成立。"}, {"text": "植物", "is_correct": false, "explanation": "语义：氢和氧不是植物，与“水里有氢和氧”的说法不符。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”指可见的色彩，不能用来说明水的组成成分。"}], "explanations": {"元素": "“两种元素”指组成水的基本成分，与“氢和氧”相符，能正确填入空格。", "动物": "语义：氢和氧不是动物，“水里有氢和氧两种动物”不成立。", "植物": "语义：氢和氧不是植物，与“水里有氢和氧”的说法不符。", "颜色": "搭配：“颜色”指可见的色彩，不能用来说明水的组成成分。"}, "sentence_index": 0, "correct_answer": "元素"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地上种了很多元素。", "explanation": "这里应该用〈庄稼〉。元素是组成东西的成分，不能被种植；“种”的对象是植物，要说“庄稼”。"}, {"text": "他写了很多元素。", "explanation": "这里应该用〈作品〉。元素指组成成分，不是可以创作的成品；“写”的对象要说“作品”。"}, {"text": "他是一位很有个性的元素。", "explanation": "这里应该用〈人物〉。元素指成分，不指人，描写人要说“人物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20824, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "元素", "is_correct": true, "explanation": "“现代元素”指设计中的现代成分，与“设计”相符，能正确填入空格。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是数值，不能与“现代”组成设计的成分。"}, {"text": "饮料", "is_correct": false, "explanation": "搭配：“设计”不与“饮料”搭配，不能说“设计有很多饮料”。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是设备，不是设计的组成部分，不能说“设计有很多电脑”。"}], "explanations": {"元素": "“现代元素”指设计中的现代成分，与“设计”相符，能正确填入空格。", "价格": "语义：“价格”是数值，不能与“现代”组成设计的成分。", "饮料": "搭配：“设计”不与“饮料”搭配，不能说“设计有很多饮料”。", "电脑": "语义：电脑是设备，不是设计的组成部分，不能说“设计有很多电脑”。"}, "sentence_index": 6, "correct_answer": "元素"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这里是一个安静的元素。", "explanation": "这里应该用〈地方〉。元素不指场所，描述地点要说“地方”。"}, {"text": "这是一件好用的元素。", "explanation": "这里应该用〈工具〉。元素指组成成分，不指可以使用的器具。"}, {"text": "他的元素很周密。", "explanation": "这里应该用〈计划〉。元素是组成成分，不能用“周密”形容；“周密”说的是计划、方案。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20824, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "铁是一块常见的元素。", "corrected_sentence": "铁是一种常见的元素。", "error_description": "量词错误：“元素”应用量词“种”，“块”用于块状物。正确说法：铁是一种常见的元素。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20824, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店的设计融合了很多现代元素们。", "corrected_sentence": "这家店的设计融合了很多现代元素。", "error_description": "“元素”是非人名词，不能加“们”表示复数。正确说法：这家店的设计融合了很多现代元素。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0f9a6dd5-3570-4b29-92cb-cd6d0999c1a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "轻", "is_correct": false, "explanation": "轻描述重量，与湿性所指的带水状态没有反义关系。"}, {"text": "亮", "is_correct": false, "explanation": "亮描述光线，与带水的性质无关。"}, {"text": "干", "is_correct": true, "explanation": "干与湿性相对，指不带水分，与“东西带着水”相反。"}, {"text": "硬", "is_correct": false, "explanation": "硬描述质地，与湿性所指的带水状态没有反义关系。"}], "correct_answer": "干", "explanations": {"轻": "轻描述重量，与湿性所指的带水状态没有反义关系。", "亮": "亮描述光线，与带水的性质无关。", "干": "干与湿性相对，指不带水分，与“东西带着水”相反。", "硬": "硬描述质地，与湿性所指的带水状态没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "冷", "is_correct": false, "explanation": "冷描述温度，与湿性所指的带水性质没有反义关系。"}, {"text": "深", "is_correct": false, "explanation": "深描述距离或颜色的程度，与湿性所指的带水性质不构成反义。"}, {"text": "干", "is_correct": true, "explanation": "干与湿性相对，指不带水分，与“东西带着水”相反。"}, {"text": "粗", "is_correct": false, "explanation": "粗描述粗细或质地，与湿性所指的带水性质不构成反义。"}], "correct_answer": "干", "explanations": {"冷": "冷描述温度，与湿性所指的带水性质没有反义关系。", "深": "深描述距离或颜色的程度，与湿性所指的带水性质不构成反义。", "干": "干与湿性相对，指不带水分，与“东西带着水”相反。", "粗": "粗描述粗细或质地，与湿性所指的带水性质不构成反义。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指东西带着水，不是干的。", "primary_collocate": null, "pronunciation": "shī xìng", "ipa": "ʂɨ˥ ɕiŋ˥˩", "syllable_count": 2, "sentences": [{"text": "湿性材料容易弄湿包装，所以别放进这个纸盒里。", "target_word": "湿性", "complexity_tier": "T3", "furigana": "shī xìng cái liào róng yì nòng shī bāo zhuāng, suǒ yǐ bié fàng jìn zhè ge zhǐ hé lǐ.", "sentence_source": "generated"}, {"text": "这些湿性材料带着水，拿起来很重。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性垃圾要和干的垃圾分开放。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性垃圾带着水，扔之前要沥干。", "target_word": "湿性", "complexity_tier": "T3", "furigana": "shī xìng lā jī dài zhe shuǐ, rēng zhī qián yào lì gān.", "sentence_source": "generated"}, {"text": "这堆湿性木材烧起来烟很大。", "target_word": "湿性", "complexity_tier": "T3", "furigana": "zhè duī shī xìng mù cái shāo qǐ lái yān hěn dà.", "sentence_source": "generated"}, {"text": "干性材料放左边，湿性材料放右边。", "target_word": "湿性", "complexity_tier": "T3", "furigana": "gān xìng cái liào fàng zuǒ biān, shī xìng cái liào fàng yòu biān.", "sentence_source": "generated"}, {"text": "湿性饲料有水，小鸡爱吃。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨后的湿性树叶不能马上点火。", "target_word": "湿性", "complexity_tier": "T3", "furigana": "yǔ hòu de shī xìng shù yè bù néng mǎ shàng diǎn huǒ.", "sentence_source": "generated"}, {"text": "这包湿性材料太重了，我拿不动。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "湿性材料放久了会发霉，要早点用。", "target_word": "湿性", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "濕性", "label": "繁体"}, {"form": "湿性材料", "label": "复合"}], "register": "中性", "sense_fingerprint": "湿性：东西带着水，不是干的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "湿性", "is_correct": true, "explanation": "湿性：东西带着水，不是干的。"}, {"text": "时兴", "is_correct": false, "explanation": "shí xīng 与 shī xìng 两个音节的声调都不同，意思是一时流行。"}, {"text": "施刑", "is_correct": false, "explanation": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是施加刑罚。"}, {"text": "实性", "is_correct": false, "explanation": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是真实的性质。"}, {"text": "室性", "is_correct": false, "explanation": "shì xìng 的第一个音节声调不同（shì 为第四声，shī 为第一声），是医学用语，指心室的。"}], "explanations": {"湿性": "湿性：东西带着水，不是干的。", "时兴": "shí xīng 与 shī xìng 两个音节的声调都不同，意思是一时流行。", "施刑": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是施加刑罚。", "实性": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是真实的性质。", "室性": "shì xìng 的第一个音节声调不同（shì 为第四声，shī 为第一声），是医学用语，指心室的。"}, "sentence_index": null, "correct_answer": "湿性"}, "level_3": {"options": [{"text": "干燥", "is_correct": false, "explanation": "语义：干燥材料不带水，不会弄湿包装，与“容易弄湿包装”矛盾。"}, {"text": "透明", "is_correct": false, "explanation": "语义：“透明”说的是能否看见，与“容易弄湿包装”无关，句意不通。"}, {"text": "湿性", "is_correct": true, "explanation": "正确：“湿性材料”指带着水的材料，所以容易弄湿包装。"}, {"text": "干性", "is_correct": false, "explanation": "语义：干性指不带水的性质，与“容易弄湿包装”的语境相反。"}], "explanations": {"干燥": "语义：干燥材料不带水，不会弄湿包装，与“容易弄湿包装”矛盾。", "透明": "语义：“透明”说的是能否看见，与“容易弄湿包装”无关，句意不通。", "湿性": "正确：“湿性材料”指带着水的材料，所以容易弄湿包装。", "干性": "语义：干性指不带水的性质，与“容易弄湿包装”的语境相反。"}, "sentence_index": 0, "correct_answer": "湿性"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条毛巾的湿性还很大，晾一会儿再收。", "explanation": "这里应该用〈潮湿〉。湿性是只作定语的形容词，不能作谓语；说毛巾还没干，要用“还很潮湿”。"}, {"text": "他的脾气湿性很强，动不动就哭。", "explanation": "这里用错了对象。湿性只说东西、材料带水的性质，不能形容人的脾气；形容人性格脆弱，要用〈脆弱〉。"}, {"text": "这间屋子的湿性很重，要开窗通风。", "explanation": "这里应该用〈湿气〉。湿性指东西本身带水，屋里的潮气要说“湿气很重”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "湿性", "is_correct": true, "explanation": "湿性：东西带着水，不是干的。"}, {"text": "失信", "is_correct": false, "explanation": "shī xìn 与湿性 shī xìng 的第一个音节相同，第二个音节韵尾不同（xìn 为 -n，xìng 为 -ng），意思是失去信用。"}, {"text": "施行", "is_correct": false, "explanation": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是实施、施行。"}, {"text": "食性", "is_correct": false, "explanation": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是动物的摄食习性。"}, {"text": "实行", "is_correct": false, "explanation": "shí xíng 与 shī xìng 两个音节的声调都不同，意思是执行、实施。"}], "explanations": {"湿性": "湿性：东西带着水，不是干的。", "失信": "shī xìn 与湿性 shī xìng 的第一个音节相同，第二个音节韵尾不同（xìn 为 -n，xìng 为 -ng），意思是失去信用。", "施行": "shī xíng 的第二个音节声调不同（xíng 为第二声，xìng 为第四声），意思是实施、施行。", "食性": "shí xìng 的第一个音节声调不同（shí 为第二声，shī 为第一声），意思是动物的摄食习性。", "实行": "shí xíng 与 shī xìng 两个音节的声调都不同，意思是执行、实施。"}, "sentence_index": null, "correct_answer": "湿性"}, "level_3": {"options": [{"text": "干燥", "is_correct": false, "explanation": "语义：“干燥”指不含水分，与后半句“有水”直接矛盾。"}, {"text": "无水", "is_correct": false, "explanation": "语义：“无水”与后半句“有水”直接矛盾。"}, {"text": "湿性", "is_correct": true, "explanation": "正确：“湿性饲料”指带着水的饲料，所以小鸡爱吃。"}, {"text": "干巴", "is_correct": false, "explanation": "语域：“干巴”是口语色彩较重的词，而且与“有水”的说明相矛盾。"}], "explanations": {"干燥": "语义：“干燥”指不含水分，与后半句“有水”直接矛盾。", "无水": "语义：“无水”与后半句“有水”直接矛盾。", "湿性": "正确：“湿性饲料”指带着水的饲料，所以小鸡爱吃。", "干巴": "语域：“干巴”是口语色彩较重的词，而且与“有水”的说明相矛盾。"}, "sentence_index": 6, "correct_answer": "湿性"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这堆材料的湿性很多，放久了会发霉，要早点用。", "explanation": "这里应该用〈水分〉。湿性是形容词，不作名词；说材料里水的多少要用“水分”。"}, {"text": "这只小猫的湿性很强，喜欢在水边玩。", "explanation": "这里用错了对象。湿性只说东西带水的性质，不用来描写动物的习性；描写动物在水里嬉玩，要用〈戏水〉。"}, {"text": "这里的湿性很高，夏天出门要带伞。", "explanation": "这里应该用〈湿度〉。湿度指空气中水汽的多少，湿性说的是东西本身带水。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些湿性地废纸要单独存放，别和干纸混在一起。", "corrected_sentence": "这些湿性废纸要单独存放，别和干纸混在一起。", "error_description": "“湿性”作定语时直接放在名词前，中间不能加“地”（“地”用于修饰动词、形容词作状语）。应说“湿性废纸”，不能说“湿性地废纸”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20826, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这堆很湿性的饲料要尽快用完。", "corrected_sentence": "这堆湿性的饲料要尽快用完。", "error_description": "“湿性”作定语前不能加程度副词“很”，应说“湿性的饲料”，不能说“很湿性的饲料”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完整", "is_correct": true, "explanation": "正确：完整与“碎”相对，指东西没有破成块。"}, {"text": "明亮", "is_correct": false, "explanation": "明亮描述光线或颜色，与“碎”没有反义关系。"}, {"text": "柔软", "is_correct": false, "explanation": "柔软描述质地，与“碎”的破裂状态没有对应的反义关系。"}, {"text": "平滑", "is_correct": false, "explanation": "平滑描述表面质地，与“碎”不构成反义关系。"}], "correct_answer": "完整", "explanations": {"完整": "正确：完整与“碎”相对，指东西没有破成块。", "明亮": "明亮描述光线或颜色，与“碎”没有反义关系。", "柔软": "柔软描述质地，与“碎”的破裂状态没有对应的反义关系。", "平滑": "平滑描述表面质地，与“碎”不构成反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "完整", "is_correct": true, "explanation": "正确：完整与“碎”相对，指纸没有被撕成小块。"}, {"text": "温暖", "is_correct": false, "explanation": "温暖描述温度或感觉，与“碎”没有反义关系。"}, {"text": "光滑", "is_correct": false, "explanation": "光滑描述表面质地，与“碎”不是反义关系。"}, {"text": "潮湿", "is_correct": false, "explanation": "潮湿描述含水的状态，与“碎”的破裂状态没有反义关系。"}], "correct_answer": "完整", "explanations": {"完整": "正确：完整与“碎”相对，指纸没有被撕成小块。", "温暖": "温暖描述温度或感觉，与“碎”没有反义关系。", "光滑": "光滑描述表面质地，与“碎”不是反义关系。", "潮湿": "潮湿描述含水的状态，与“碎”的破裂状态没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "意思是东西破开成小块或一片片的。", "primary_collocate": null, "pronunciation": "suì", "ipa": "suei˥˩", "syllable_count": 1, "sentences": [{"text": "盘子掉了，碎了。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个杯子碎了。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地上有碎玻璃，别踩。", "target_word": "碎", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "饼干太脆，一拿就碎。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "冰很硬，不会一下子就碎。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的玩具屋摔了一下，窗户的玻璃碎了。", "target_word": "碎", "complexity_tier": "T3", "furigana": "suì", "sentence_source": "generated"}, {"text": "妈妈把菜切得很碎。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的眼镜镜片碎了，什么都看不清。", "target_word": "碎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鸡蛋掉在地上，碎了一地。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把纸撕得很碎。", "target_word": "碎", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "碎了", "label": "体标"}, {"form": "打碎", "label": "复合词"}], "register": "中性", "sense_fingerprint": "东西破成小块或一片片（通俗讲法）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '68807ff3-eb58-4d1c-ba43-2ad750765589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：碎（suì），指东西破开成小块或一片片的。"}, {"text": "随", "is_correct": false, "explanation": "suí 与 suì 声调不同，意思是跟随。"}, {"text": "醉", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z / s），声调相同，意思是醉酒。"}, {"text": "睡", "is_correct": false, "explanation": "shuì 与 suì 声母不同（sh / s），声调相同，意思是睡觉。"}], "explanations": {"碎": "正确：碎（suì），指东西破开成小块或一片片的。", "随": "suí 与 suì 声调不同，意思是跟随。", "醉": "zuì 与 suì 声母不同（z / s），声调相同，意思是醉酒。", "睡": "shuì 与 suì 声母不同（sh / s），声调相同，意思是睡觉。"}, "sentence_index": null, "correct_answer": "碎"}, "level_3": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：盘子掉下去破成小块，用“碎”。"}, {"text": "香", "is_correct": false, "explanation": "语义：盘子摔落后不会变香，句意不通。"}, {"text": "亮", "is_correct": false, "explanation": "语义：盘子掉了不会因此变亮。"}, {"text": "薄", "is_correct": false, "explanation": "搭配：“薄”描述厚度，盘子摔落后不说变薄。"}], "explanations": {"碎": "正确：盘子掉下去破成小块，用“碎”。", "香": "语义：盘子摔落后不会变香，句意不通。", "亮": "语义：盘子掉了不会因此变亮。", "薄": "搭配：“薄”描述厚度，盘子摔落后不说变薄。"}, "sentence_index": 0, "correct_answer": "碎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这碗粥一会儿就碎了。", "explanation": "这里应该用〈凉〉。碎指东西破开成小块，粥变冷应说“凉”。"}, {"text": "这条河很碎。", "explanation": "这里应该用〈长〉。碎指东西破开成小块，形容河的长度应说“长”。"}, {"text": "玻璃上碎了一道缝。", "explanation": "这里应该用〈裂〉。碎指摔成小块，玻璃上的缝只是裂开，应说“裂”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：碎（suì），指东西破开成小块或一片片的。"}, {"text": "对", "is_correct": false, "explanation": "duì 与 suì 声母不同（d / s），声调相同，意思是对。"}, {"text": "翠", "is_correct": false, "explanation": "cuì 与 suì 声母不同（c / s），声调相同，意思是翠绿。"}, {"text": "最", "is_correct": false, "explanation": "zuì 与 suì 声母不同（z / s），声调相同，意思是最。"}], "explanations": {"碎": "正确：碎（suì），指东西破开成小块或一片片的。", "对": "duì 与 suì 声母不同（d / s），声调相同，意思是对。", "翠": "cuì 与 suì 声母不同（c / s），声调相同，意思是翠绿。", "最": "zuì 与 suì 声母不同（z / s），声调相同，意思是最。"}, "sentence_index": null, "correct_answer": "碎"}, "level_3": {"options": [{"text": "碎", "is_correct": true, "explanation": "正确：菜切得很小块，用“碎”。"}, {"text": "甜", "is_correct": false, "explanation": "语义：切菜的方式与味道无关，“切得很甜”句意不通。"}, {"text": "远", "is_correct": false, "explanation": "搭配：“切得”后接的应是形状或大小的结果，“远”不搭配。"}, {"text": "苦", "is_correct": false, "explanation": "语义：切菜的结果不是味道，“切得很苦”句意不通。"}], "explanations": {"碎": "正确：菜切得很小块，用“碎”。", "甜": "语义：切菜的方式与味道无关，“切得很甜”句意不通。", "远": "搭配：“切得”后接的应是形状或大小的结果，“远”不搭配。", "苦": "语义：切菜的结果不是味道，“切得很苦”句意不通。"}, "sentence_index": 6, "correct_answer": "碎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "衣服碎了一个洞。", "explanation": "这里应该用〈破〉。碎指东西摔成小块，衣服破洞应说“破”。"}, {"text": "她的脸很碎。", "explanation": "这里应该用〈红〉。碎指东西破开成小块，形容脸色应说“红”。"}, {"text": "这根线碎了。", "explanation": "这里应该用〈断〉。碎指东西摔成小块，线被扯断应说“断”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把碗碎了。", "corrected_sentence": "他把碗摔碎了。", "error_description": "“碎”作结果补语，前面需要动作动词，“把碗碎了”缺少动词“摔”，应说“摔碎了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20828, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把信撕很碎，扔掉了。", "corrected_sentence": "他把信撕得很碎，扔掉了。", "error_description": "“撕”后作程度补语时需要用“得”引出，“撕很碎”应改为“撕得很碎”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a7cfbb23-137f-442a-96f7-c56d6c9db68b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "湿润", "is_correct": true, "explanation": "正确答案。“湿润”与“干燥”意义相对，指水分充足。"}, {"text": "明亮", "is_correct": false, "explanation": "“明亮”形容光线，与“干燥”没有反义关系。"}, {"text": "宽敞", "is_correct": false, "explanation": "“宽敞”形容空间大，与“干燥”没有反义关系。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”形容声音小，与“干燥”没有反义关系，其反义词是吵闹。"}], "correct_answer": "湿润", "explanations": {"湿润": "正确答案。“湿润”与“干燥”意义相对，指水分充足。", "明亮": "“明亮”形容光线，与“干燥”没有反义关系。", "宽敞": "“宽敞”形容空间大，与“干燥”没有反义关系。", "安静": "“安静”形容声音小，与“干燥”没有反义关系，其反义词是吵闹。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "湿润", "is_correct": true, "explanation": "正确答案。“湿润”与“干燥”意义相对，指水分充足。"}, {"text": "清澈", "is_correct": false, "explanation": "“清澈”形容水或眼睛干净透明，与“干燥”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”形容场面喧哗，与“干燥”没有反义关系。"}, {"text": "坚硬", "is_correct": false, "explanation": "“坚硬”形容质地硬，与“干燥”没有反义关系，其反义词是柔软。"}], "correct_answer": "湿润", "explanations": {"湿润": "正确答案。“湿润”与“干燥”意义相对，指水分充足。", "清澈": "“清澈”形容水或眼睛干净透明，与“干燥”没有反义关系。", "热闹": "“热闹”形容场面喧哗，与“干燥”没有反义关系。", "坚硬": "“坚硬”形容质地硬，与“干燥”没有反义关系，其反义词是柔软。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "没有水，东西就不湿了。", "primary_collocate": null, "pronunciation": "gān zào", "ipa": "kan˥˥ tsɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "木柴很干燥，一点火就着了。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨停了三天，路上的土已经干燥了。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "山洞里没有一滴水，石头都很干燥。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "干燥的树叶踩上去会发出响声。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "毛巾没有水了，摸起来很干燥。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "饼干放久了会受潮，要放在干燥的盒子里。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把纸巾放进干燥的袋子里，就不会湿了。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "实验前要先把瓶子洗净并保持干燥。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "面包放在外面几天，变得又硬又干燥。", "target_word": "干燥", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "雨衣下面的衣服还是干燥的，一点也没湿。", "target_word": "干燥", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "干燥剂", "label": "复合"}, {"form": "干燥器", "label": "复合"}, {"form": "乾燥", "label": "繁体"}], "register": "通用", "sense_fingerprint": "物体、土地等没有水分，摸起来不湿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '15493912-f1ff-4f6e-a884-3ffcb8e6a4f7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。“干燥”读作 gān zào，指没有水分。"}, {"text": "干枣", "is_correct": false, "explanation": "干枣 gān zǎo 与“干燥”的第一个音节相同，第二个音节只有声调不同（第三声与第四声），意思是干枣。"}, {"text": "赶早", "is_correct": false, "explanation": "赶早 gǎn zǎo 两个音节的声调都与“干燥”不同，意思是尽早。"}, {"text": "干扰", "is_correct": false, "explanation": "干扰 gān rǎo 的第二个音节声母 r 与 z 不同，声调也不同，意思是妨碍。"}], "explanations": {"干燥": "正确答案。“干燥”读作 gān zào，指没有水分。", "干枣": "干枣 gān zǎo 与“干燥”的第一个音节相同，第二个音节只有声调不同（第三声与第四声），意思是干枣。", "赶早": "赶早 gǎn zǎo 两个音节的声调都与“干燥”不同，意思是尽早。", "干扰": "干扰 gān rǎo 的第二个音节声母 r 与 z 不同，声调也不同，意思是妨碍。"}, "sentence_index": null, "correct_answer": "干燥"}, "level_3": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。木柴缺少水分，所以才会“一点火就着了”。"}, {"text": "湿润", "is_correct": false, "explanation": "语义：木柴湿润就不容易点着，与“一点火就着了”矛盾。"}, {"text": "光滑", "is_correct": false, "explanation": "语义：“光滑”形容表面平滑，与“一点火就着了”没有关系。"}, {"text": "清澈", "is_correct": false, "explanation": "搭配：“清澈”多形容水或眼睛，不用来形容木柴。"}], "explanations": {"干燥": "正确答案。木柴缺少水分，所以才会“一点火就着了”。", "湿润": "语义：木柴湿润就不容易点着，与“一点火就着了”矛盾。", "光滑": "语义：“光滑”形容表面平滑，与“一点火就着了”没有关系。", "清澈": "搭配：“清澈”多形容水或眼睛，不用来形容木柴。"}, "sentence_index": 0, "correct_answer": "干燥"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈把厨房打扫得很干燥，地板都亮了。", "explanation": "这里应该用〈干净〉。“干燥”指缺少水分，形容打扫后的整洁要用“干净”。"}, {"text": "他回答问题很干燥，三句话就把问题说清楚了。", "explanation": "这里应该用〈干脆〉。“干脆”形容说话直截了当，“干燥”不用来形容说话。"}, {"text": "这家店到了晚上就很干燥，几乎没有客人。", "explanation": "这里应该用〈冷清〉。“干燥”指缺少水分，形容地方没有人气、生意清淡要用“冷清”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。“干燥”读作 gān zào，指没有水分。"}, {"text": "肝脏", "is_correct": false, "explanation": "肝脏 gān zàng 的第一个音节相同，第二个音节只有韵母不同（zàng 与 zào），意思是肝脏。"}, {"text": "干草", "is_correct": false, "explanation": "干草 gān cǎo 的第二个音节声母 c 与 z 不同，声调也不同，意思是晒干的草。"}, {"text": "干烧", "is_correct": false, "explanation": "干烧 gān shāo 的第二个音节声母 sh 与 z 不同，声调也不同，是一种烹饪方法。"}], "explanations": {"干燥": "正确答案。“干燥”读作 gān zào，指没有水分。", "肝脏": "肝脏 gān zàng 的第一个音节相同，第二个音节只有韵母不同（zàng 与 zào），意思是肝脏。", "干草": "干草 gān cǎo 的第二个音节声母 c 与 z 不同，声调也不同，意思是晒干的草。", "干烧": "干烧 gān shāo 的第二个音节声母 sh 与 z 不同，声调也不同，是一种烹饪方法。"}, "sentence_index": null, "correct_answer": "干燥"}, "level_3": {"options": [{"text": "干燥", "is_correct": true, "explanation": "正确答案。袋子干燥，纸巾放进去才不会湿。"}, {"text": "漂亮", "is_correct": false, "explanation": "语义：袋子漂亮与“就不会湿了”没有关系，不能防止纸巾湿。"}, {"text": "苗条", "is_correct": false, "explanation": "体貌：“苗条”形容人的身材，不能用来形容袋子。"}, {"text": "热闹", "is_correct": false, "explanation": "语义：“热闹”形容场面，不能用来形容袋子的状态。"}], "explanations": {"干燥": "正确答案。袋子干燥，纸巾放进去才不会湿。", "漂亮": "语义：袋子漂亮与“就不会湿了”没有关系，不能防止纸巾湿。", "苗条": "体貌：“苗条”形容人的身材，不能用来形容袋子。", "热闹": "语义：“热闹”形容场面，不能用来形容袋子的状态。"}, "sentence_index": 6, "correct_answer": "干燥"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她做事很干燥，三两下就把任务完成了。", "explanation": "这里应该用〈干练〉。“干燥”指缺少水分，形容做事利落要用“干练”。"}, {"text": "这只鸟的叫声很干燥，听着很舒服。", "explanation": "这里应该用〈清脆〉。“干燥”不用来形容声音，形容声音悦耳要用“清脆”。"}, {"text": "他在这个行业的经验很干燥，很多人都向他请教。", "explanation": "这里应该用〈丰富〉。“干燥”指缺少水分，形容经验多要用“丰富”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这块木头放了很久，现在很干燥地。", "corrected_sentence": "这块木头放了很久，现在很干燥。", "error_description": "“干燥”作谓语时后面不能加结构助词“地”，“地”用于修饰动词，应说“现在很干燥”，不能说“现在很干燥地”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20830, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些衣服晾了一下午，现在干燥地很。", "corrected_sentence": "这些衣服晾了一下午，现在干燥得很。", "error_description": "“干燥”后面接程度补语要用“得”，不能用“地”；“地”用于修饰动词。应说“干燥得很”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'bb946a2c-5082-4fc0-aaf6-4d510c0afa07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
