INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20832, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20832, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "生物体里的一种东西，比如糖、油、蛋白质。", "primary_collocate": null, "pronunciation": "yǒu jī wù", "ipa": "joʊ˨˩˦ tɕi˥ u˥˩", "syllable_count": 3, "sentences": [{"text": "我们吃的米饭里有很多有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "糖、油和蛋白质都是身体需要的有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "树叶里有很多有机物，烂了以后能变成肥料。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物吃进去的有机物，会变成身体的能量。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水果里的糖是一种有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼和肉里的蛋白质都是有机物。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "身体里的有机物少了，人就会没力气。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "生物体里有各种有机物，比如糖和油。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "豆子里有很多有机物，吃了对身体好。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "种子里的有机物能让小苗慢慢长大。", "target_word": "有机物", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "有機物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "有机物：生物体里的糖、油、蛋白质等物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20832, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "语义：石头不能吃，米饭里不会有很多石头，与“我们吃的米饭”矛盾。"}, {"text": "有机物", "is_correct": true, "explanation": "正确：米饭里的淀粉等有机物是生物体的成分，与句意相符。"}, {"text": "金属", "is_correct": false, "explanation": "搭配：说“米饭里有很多……”时，“金属”不是食物成分，搭配不当。"}, {"text": "塑料", "is_correct": false, "explanation": "语义：塑料无法食用，与“我们吃的米饭”矛盾。"}], "explanations": {"石头": "语义：石头不能吃，米饭里不会有很多石头，与“我们吃的米饭”矛盾。", "有机物": "正确：米饭里的淀粉等有机物是生物体的成分，与句意相符。", "金属": "搭配：说“米饭里有很多……”时，“金属”不是食物成分，搭配不当。", "塑料": "语义：塑料无法食用，与“我们吃的米饭”矛盾。"}, "sentence_index": 0, "correct_answer": "有机物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "身体需要的有机物，比如钙和铁，能让骨头变硬。", "explanation": "这里应该用〈无机盐〉。钙、铁是无机物，有机物指糖、油、蛋白质等含碳物质。"}, {"text": "我的盘子里有一只有机物。", "explanation": "这里应该用〈种〉或〈份〉。“只”用于动物和器物，有机物是物质，不能用“只”计量。"}, {"text": "铁是人体需要的有机物。", "explanation": "这里应该用〈元素〉。铁是无机的化学元素，不属于生物体里的有机物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20832, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "沙子", "is_correct": false, "explanation": "语义：沙子不是人体的组成成分，“身体里的沙子少了”不合常理。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“颜色”与“少了”之后导致没力气的因果关系搭配不当。"}, {"text": "有机物", "is_correct": true, "explanation": "正确：身体里的糖、油、蛋白质等有机物减少，人就会没力气，与句意相符。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃不存在于人体中，与“身体里”的语境矛盾。"}], "explanations": {"沙子": "语义：沙子不是人体的组成成分，“身体里的沙子少了”不合常理。", "颜色": "搭配：“颜色”与“少了”之后导致没力气的因果关系搭配不当。", "有机物": "正确：身体里的糖、油、蛋白质等有机物减少，人就会没力气，与句意相符。", "玻璃": "语义：玻璃不存在于人体中，与“身体里”的语境矛盾。"}, "sentence_index": 6, "correct_answer": "有机物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块石头的成分主要是有机物，很硬。", "explanation": "这里应该用〈矿物〉。石头的成分主要是矿物，有机物指生物体里的糖、油、蛋白质等。"}, {"text": "牛奶里的有机物能让骨头变硬。", "explanation": "这里应该用〈钙〉。能让骨头变硬的是钙这类无机元素，不属于有机物。"}, {"text": "我从桌上拿起一颗有机物，放进嘴里。", "explanation": "这里应该用〈种〉或〈份〉。“颗”用于圆形小物，有机物是物质，不说“一颗有机物”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20832, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "蔬菜里有很多个有机物，能帮助消化。", "corrected_sentence": "蔬菜里有很多有机物，能帮助消化。", "error_description": "“有机物”是物质，不能用“个”计量，“很多”后直接接名词即可，应说“很多有机物”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20832, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "身体里的有机物们要靠饮食补充。", "corrected_sentence": "身体里的有机物要靠饮食补充。", "error_description": "“有机物”是物质，不能加“们”表示复数，应说“身体里的有机物”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
