INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20836, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "纸板是一种厚厚的硬纸。", "primary_collocate": null, "pronunciation": "zhǐ bǎn", "ipa": "ʈʂʐ̩˨˩˦ pan˨˩˦", "syllable_count": 2, "sentences": [{"text": "这张纸板又厚又硬，不容易弯。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈给我一块纸板，让我拿它当画板用。", "target_word": "纸板", "complexity_tier": "T3", "furigana": "zhǐ bǎn", "sentence_source": "generated"}, {"text": "弟弟坐在纸板上滑下了小山坡。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在门口放了一块纸板挡风。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "照片后面有一块硬硬的纸板。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买几张白色的纸板做海报。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块纸板很大，一个人拿不动。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里有红色、蓝色和黄色的纸板。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小狗躺在一块旧纸板上睡觉。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用笔在纸板上写了一行大字。", "target_word": "纸板", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一张纸板", "label": "量词"}, {"form": "一块纸板", "label": "量词"}, {"form": "硬纸板", "label": "复合"}, {"form": "紙板", "label": "繁体"}], "register": "中性", "sense_fingerprint": "厚厚的硬纸，可垫、可挡、可写画", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '89d4eb5e-197e-43d1-89cf-33f8c82390e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20836, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "纸板", "is_correct": true, "explanation": "纸板 zhǐ bǎn：厚厚的硬纸，正确答案。"}, {"text": "直板", "is_correct": false, "explanation": "直板 zhí bǎn：zhí（第二声）与 zhǐ（第三声）声调不同，意思是直的板子。"}, {"text": "制版", "is_correct": false, "explanation": "制版 zhì bǎn：zhì（第四声）与 zhǐ（第三声）声调不同，意思是印刷或制作的版。"}, {"text": "纸本", "is_correct": false, "explanation": "纸本 zhǐ běn：běn 与 bǎn 韵母不同（en 与 an），意思是纸质的版本。"}], "explanations": {"纸板": "纸板 zhǐ bǎn：厚厚的硬纸，正确答案。", "直板": "直板 zhí bǎn：zhí（第二声）与 zhǐ（第三声）声调不同，意思是直的板子。", "制版": "制版 zhì bǎn：zhì（第四声）与 zhǐ（第三声）声调不同，意思是印刷或制作的版。", "纸本": "纸本 zhǐ běn：běn 与 bǎn 韵母不同（en 与 an），意思是纸质的版本。"}, "sentence_index": null, "correct_answer": "纸板"}, "level_3": {"options": [{"text": "纸板", "is_correct": true, "explanation": "“这张纸板”指一片厚硬的纸板，符合“又厚又硬，不容易弯”的描述。"}, {"text": "纸巾", "is_correct": false, "explanation": "体貌：纸巾薄而软，与“又厚又硬”的外貌不符。"}, {"text": "报纸", "is_correct": false, "explanation": "体貌：报纸薄而软，不会“又厚又硬，不容易弯”。"}, {"text": "床单", "is_correct": false, "explanation": "搭配：“又厚又硬”一般不用来形容床单。"}], "explanations": {"纸板": "“这张纸板”指一片厚硬的纸板，符合“又厚又硬，不容易弯”的描述。", "纸巾": "体貌：纸巾薄而软，与“又厚又硬”的外貌不符。", "报纸": "体貌：报纸薄而软，不会“又厚又硬，不容易弯”。", "床单": "搭配：“又厚又硬”一般不用来形容床单。"}, "sentence_index": 0, "correct_answer": "纸板"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我买了一只纸板做海报。", "explanation": "这里应该用〈张〉或〈块〉。“只”用于动物或成对器官中的一个，纸板是平面的，不用“只”。"}, {"text": "他撕了一粒纸板。", "explanation": "这里应该用〈张〉或〈块〉。“粒”用于颗粒状的小东西，纸板是平面的，不用“粒”。"}, {"text": "他拿了一朵纸板挡风。", "explanation": "这里应该用〈张〉或〈块〉。“朵”用于花、云等，纸板不用“朵”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20836, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "纸板", "is_correct": true, "explanation": "“这块纸板”指一片较大的纸板，一个人拿不动，符合语境。"}, {"text": "泡沫", "is_correct": false, "explanation": "语义：泡沫很轻，不会出现“一个人拿不动”的情况。"}, {"text": "香皂", "is_correct": false, "explanation": "体貌：香皂体形小，与“很大”的描述不符。"}, {"text": "橡皮", "is_correct": false, "explanation": "体貌：橡皮体形小，与“很大”的描述不符。"}], "explanations": {"纸板": "“这块纸板”指一片较大的纸板，一个人拿不动，符合语境。", "泡沫": "语义：泡沫很轻，不会出现“一个人拿不动”的情况。", "香皂": "体貌：香皂体形小，与“很大”的描述不符。", "橡皮": "体貌：橡皮体形小，与“很大”的描述不符。"}, "sentence_index": 6, "correct_answer": "纸板"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用纸板擦了擦脸上的汗。", "explanation": "这里应该用〈纸巾〉。擦汗要用柔软吸水的纸巾，纸板厚硬，不能用来擦脸。"}, {"text": "我每天早上在纸板上读新闻。", "explanation": "这里应该用〈报纸〉。读新闻要看报纸，纸板厚硬，不用来印刷新闻。"}, {"text": "妈妈用纸板煮了一锅面条。", "explanation": "这里应该用〈锅〉。煮面条要用锅，纸板是纸做的，不能用来煮东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20836, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他找来一颗纸板挡住了门口。", "corrected_sentence": "他找来一块纸板挡住了门口。", "error_description": "量词错误：“颗”用于粒状的小东西，“纸板”是平面的薄片，不能用“颗”，应用量词“块”或“张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20836, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "弟弟纸板裁成了两块小垫子。", "corrected_sentence": "弟弟把纸板裁成了两块小垫子。", "error_description": "“把”缺失：处置式要用“把”引出宾语“纸板”，应为“弟弟把纸板裁成了两块小垫子”，省去“把”写成“弟弟纸板裁成”是错误的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5699d722-26b4-4a02-8f4e-2ced59ea9cb2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
