INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20838, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20838, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "木头被锯子锯下来后，掉在地上的小碎片就是木屑。", "primary_collocate": null, "pronunciation": "mù xiè", "ipa": "mu˥˩ ɕjɛ˥˩", "syllable_count": 2, "sentences": [{"text": "锯子一响，木屑就掉在地上了。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一堆木屑，是刚才锯木头留下的。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用锯子锯木板，木屑飞得到处都是。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把桌子上的木屑擦干净。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "锯木头时，木屑掉进了我的眼睛里。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷在院子里做小凳子，脚边全是木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扫地的时候，我扫出了一大堆木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这块木头很硬，锯了很久才掉下一点木屑。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新锯开的木头有香味，木屑也很香。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们在木屑上玩，鞋子都脏了。", "target_word": "木屑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "堆", "label": "量词"}, {"form": "层", "label": "量词"}], "register": "中性", "sense_fingerprint": "木屑：木头被锯后掉在地上的小碎片", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20838, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "木屑", "is_correct": true, "explanation": "木屑：锯木头后掉在地上的细碎小片。"}, {"text": "不屑", "is_correct": false, "explanation": "bù（第四声）与 mù（第四声）声母不同（b 与 m），意思是轻视、看不起。"}, {"text": "木楔", "is_correct": false, "explanation": "xiē（第一声）与 xiè（第四声）声调不同，意思是木头做的楔子。"}, {"text": "木鞋", "is_correct": false, "explanation": "xié（第二声）与 xiè（第四声）声调不同，意思是木头做的鞋。"}, {"text": "末屑", "is_correct": false, "explanation": "mò（第四声）与 mù（第四声）韵母不同（o 与 u），意思是细碎的末子。"}], "explanations": {"木屑": "木屑：锯木头后掉在地上的细碎小片。", "不屑": "bù（第四声）与 mù（第四声）声母不同（b 与 m），意思是轻视、看不起。", "木楔": "xiē（第一声）与 xiè（第四声）声调不同，意思是木头做的楔子。", "木鞋": "xié（第二声）与 xiè（第四声）声调不同，意思是木头做的鞋。", "末屑": "mò（第四声）与 mù（第四声）韵母不同（o 与 u），意思是细碎的末子。"}, "sentence_index": null, "correct_answer": "木屑"}, "level_3": {"options": [{"text": "木屑", "is_correct": true, "explanation": "木屑：锯木头时掉下的细碎颗粒。"}, {"text": "面粉", "is_correct": false, "explanation": "语义：锯子锯的是硬物，不会锯出面粉，句意不通。"}, {"text": "纸屑", "is_correct": false, "explanation": "搭配：“纸屑”一般是撕碎或剪碎的纸，锯木头掉下的不是纸屑。"}, {"text": "水", "is_correct": false, "explanation": "语义：锯子不会产生水，“锯子一响，水就掉在地上”说不通。"}], "explanations": {"木屑": "木屑：锯木头时掉下的细碎颗粒。", "面粉": "语义：锯子锯的是硬物，不会锯出面粉，句意不通。", "纸屑": "搭配：“纸屑”一般是撕碎或剪碎的纸，锯木头掉下的不是纸屑。", "水": "语义：锯子不会产生水，“锯子一响，水就掉在地上”说不通。"}, "sentence_index": 0, "correct_answer": "木屑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子上放着一条木屑。", "explanation": "这里应该用〈堆〉或〈点〉。木屑是细碎的颗粒，不能用〈条〉，那是用于细长东西的。"}, {"text": "地上散着比手掌还大的木屑。", "explanation": "这里应该用〈木块〉。木屑是掉下来的小碎片，不会比手掌还大；大块的木料要用木块。"}, {"text": "他捡起了完整的木屑，放进了口袋。", "explanation": "这里应该用〈木条〉。木屑是掉下来的小碎片，不会是完整的；完整的细长木料要用木条。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20838, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "木屑", "is_correct": true, "explanation": "木屑：扫地时扫出的细碎木末。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气看不见，不能被扫成一大堆。"}, {"text": "水", "is_correct": false, "explanation": "搭配：“扫出一大堆”不说水，水一般要用拖把拖。"}, {"text": "月光", "is_correct": false, "explanation": "语义：月光不是实物，不能被扫成一大堆。"}], "explanations": {"木屑": "木屑：扫地时扫出的细碎木末。", "空气": "语义：空气看不见，不能被扫成一大堆。", "水": "搭配：“扫出一大堆”不说水，水一般要用拖把拖。", "月光": "语义：月光不是实物，不能被扫成一大堆。"}, "sentence_index": 6, "correct_answer": "木屑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "地上散着又长又薄的木屑。", "explanation": "这里应该用〈木片〉。木屑是掉下来的小碎片，不会“又长又薄”；又长又薄的木料要用木片。"}, {"text": "这些木屑都很粗，像手指一样。", "explanation": "这里应该用〈木棍〉。木屑是掉下来的小碎片，不会像手指一样粗；粗长的木料要用木棍。"}, {"text": "这些木屑都很平整，表面光滑。", "explanation": "这里应该用〈木板〉。木屑是掉下来的小碎片，不会平整光滑；平整光滑的薄木要用木板。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20838, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "门口放着一根木屑，别忘了倒掉。", "corrected_sentence": "门口放着一堆木屑，别忘了倒掉。", "error_description": "量词错误：“木屑”是成堆的细碎颗粒，应说“一堆木屑”，不能说“一根木屑”（“根”用于细长的东西）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20838, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把木屑全部扫。", "corrected_sentence": "他把木屑全部扫进了簸箕里。", "error_description": "“把”字句的动词后须有补充成分（如“了”、补语），只说“扫”句子不完整，应说“扫进了簸箕里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
