INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20840, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "把不同的东西按一定数量放在一起。", "primary_collocate": null, "pronunciation": "pèi bǐ", "ipa": "pʰei⁵¹ pi²¹⁴", "syllable_count": 2, "sentences": [{"text": "师傅正在配比颜料。", "target_word": "配比", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "请你把水和糖配比好，再倒进杯子里。", "target_word": "配比", "complexity_tier": "T3", "furigana": "qǐng nǐ bǎ shuǐ hé táng pèi bǐ hǎo, zài dào jìn bēi zi lǐ.", "sentence_source": "generated"}, {"text": "他认真地配比了三种肥料。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师教我们怎样配比盐水。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工人们在工厂里配比水泥和沙子。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "厨师把做面包的材料配比好，然后放进烤箱。", "target_word": "配比", "complexity_tier": "T3", "furigana": "chú shī bǎ zuò miànbāo de cáiliào pèi bǐ hǎo, ránhòu fàng jìn kǎoxiāng.", "sentence_source": "generated"}, {"text": "妈妈每天给小狗配比不同的食物。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些药要先配比好，再给病人用。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你配比得不对，颜色太深了。", "target_word": "配比", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他配比过很多种药水。", "target_word": "配比", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "配比了", "label": "体标"}, {"form": "配比着", "label": "体标"}, {"form": "配比过", "label": "体标"}], "register": "中性", "sense_fingerprint": "配比|把不同的东西按数量放在一起", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20840, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "配比", "is_correct": true, "explanation": "正确：“配比”表示把颜料按数量搭配在一起，与句中“师傅正在”相符。"}, {"text": "朗读", "is_correct": false, "explanation": "语义：“朗读”是出声读文字，不能用于颜料。"}, {"text": "烧烤", "is_correct": false, "explanation": "语义：“烧烤”是用火加热食物，与颜料不符。"}, {"text": "播放", "is_correct": false, "explanation": "搭配：“播放”用于影音内容，不说播放颜料。"}], "explanations": {"配比": "正确：“配比”表示把颜料按数量搭配在一起，与句中“师傅正在”相符。", "朗读": "语义：“朗读”是出声读文字，不能用于颜料。", "烧烤": "语义：“烧烤”是用火加热食物，与颜料不符。", "播放": "搭配：“播放”用于影音内容，不说播放颜料。"}, "sentence_index": 0, "correct_answer": "配比"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们把两种方案配比一下。", "explanation": "这里应该用〈比较〉。配比指把东西按量放在一起，比较两种方案的优劣要说比较。"}, {"text": "他把钱配比给了朋友。", "explanation": "这里应该用〈借〉。配比指按量把东西搭配在一起，不指把钱借出去。"}, {"text": "这两件衣服配比得很好。", "explanation": "这里应该用〈搭配〉。配比指按一定数量把东西放在一起，衣服的颜色和款式协调要说搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20840, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "配比", "is_correct": true, "explanation": "正确：“配比”表示按数量搭配食物，与“每天给小狗”“不同的食物”相符。"}, {"text": "修理", "is_correct": false, "explanation": "语义：“修理”是修复器物，不能用于给小狗的食物。"}, {"text": "翻译", "is_correct": false, "explanation": "语义：“翻译”是转换语言，食物不能被翻译。"}, {"text": "登记", "is_correct": false, "explanation": "搭配：“登记”用于名册或信息，不说登记食物。"}], "explanations": {"配比": "正确：“配比”表示按数量搭配食物，与“每天给小狗”“不同的食物”相符。", "修理": "语义：“修理”是修复器物，不能用于给小狗的食物。", "翻译": "语义：“翻译”是转换语言，食物不能被翻译。", "登记": "搭配：“登记”用于名册或信息，不说登记食物。"}, "sentence_index": 6, "correct_answer": "配比"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "护士用针管配比了一点血。", "explanation": "这里应该用〈抽〉。配比指按量搭配，不指用针管吸取。"}, {"text": "班长把新同学配比到了我们组。", "explanation": "这里应该用〈分配〉。配比的对象是物品或材料，安排人员应说分配。"}, {"text": "我去配比了一把钥匙。", "explanation": "这里应该用〈配〉（配钥匙）。配比指按量把几种东西放在一起，不指复制钥匙。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20840, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他把两种颜料配比了好，就开始画画。", "corrected_sentence": "他把两种颜料配比好，就开始画画。", "error_description": "补语错误：“配比好”中“好”是结果补语，“了”不能插在动词和补语之间，应为“配比好”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20840, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈把两种肥料配比了好了。", "corrected_sentence": "妈妈把两种肥料配比好了。", "error_description": "补语位置错误：结果补语“好”应紧接在动词“配比”之后，中间不能插入“了”，应说“配比好了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
