INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20844, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "施给植物、促进其生长的养分物质。", "primary_collocate": null, "pronunciation": "féi liào", "ipa": "feɪ˧˥ ljɑʊ˥˩", "syllable_count": 2, "sentences": [{"text": "农民给菜地施了很多肥料。", "target_word": "肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "肥料可以让玉米长得又高又大。", "target_word": "肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "花长得不好，应该给它加一点肥料。", "target_word": "肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这袋肥料是用牛粪做的。", "target_word": "肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用太多肥料，草会死的。", "target_word": "肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "春天，爷爷在田里撒了一些肥料。", "target_word": "肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种肥料对青菜特别有用。", "target_word": "肥料", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "商店里卖各种肥料，有化学的，也有有机的。", "target_word": "肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家阳台的花每个月都要加一次肥料。", "target_word": "肥料", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把肥料放在土里，再浇上水。", "target_word": "肥料", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "袋", "label": "量词"}, {"form": "有机肥料", "label": "复合"}, {"form": "化学肥料", "label": "复合"}], "register": "中性", "sense_fingerprint": "施给植物、促进生长的养分物质", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '53f15428-b18b-410e-8301-878efd0cd378') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20844, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "肥料", "is_correct": true, "explanation": "肥料是施给植物的养分，农民给菜地施的就是它，符合句意。"}, {"text": "水", "is_correct": false, "explanation": "搭配：「施」多用于肥料、农药，说「施水」不搭配，给植物供水要说「浇」。"}, {"text": "种子", "is_correct": false, "explanation": "语义：种子是播下去的，不是施在地里的东西，「施了很多种子」说不通。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不能施给菜地，句意不通。"}], "explanations": {"肥料": "肥料是施给植物的养分，农民给菜地施的就是它，符合句意。", "水": "搭配：「施」多用于肥料、农药，说「施水」不搭配，给植物供水要说「浇」。", "种子": "语义：种子是播下去的，不是施在地里的东西，「施了很多种子」说不通。", "石头": "语义：石头不能施给菜地，句意不通。"}, "sentence_index": 0, "correct_answer": "肥料"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这瓶肥料能杀死害虫，庄稼很安全。", "explanation": "这里应该用「农药」。农药用来杀虫，肥料是给植物补充养分，不能杀虫。"}, {"text": "这种肥料很好吃，孩子们都抢着尝。", "explanation": "这里应该用「饼干」或「糖果」。肥料是给植物用的，不能吃；「好吃」形容食物。"}, {"text": "这袋肥料是给老人吃的，营养很好。", "explanation": "这里应该用「营养品」。营养品是给人吃的，肥料是给植物用的，不能给老人吃。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20844, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "肥料", "is_correct": true, "explanation": "肥料能给青菜补充养分，对青菜特别有用，符合句意。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是硬的透明材料，对青菜没有用处。"}, {"text": "饮料", "is_correct": false, "explanation": "语义：饮料是给人喝的，对青菜没有养分作用。"}, {"text": "粉笔", "is_correct": false, "explanation": "搭配：粉笔用来写字，与「对青菜有用」不搭配。"}], "explanations": {"肥料": "肥料能给青菜补充养分，对青菜特别有用，符合句意。", "玻璃": "语义：玻璃是硬的透明材料，对青菜没有用处。", "饮料": "语义：饮料是给人喝的，对青菜没有养分作用。", "粉笔": "搭配：粉笔用来写字，与「对青菜有用」不搭配。"}, "sentence_index": 6, "correct_answer": "肥料"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "农场给猪准备了很多肥料。", "explanation": "这里应该用「饲料」。饲料是给动物吃的，肥料是给植物用的，不能拿来喂猪。"}, {"text": "他用肥料给房间刷了一层漆。", "explanation": "这里应该用「油漆」。肥料是给植物用的，不能刷在墙上。"}, {"text": "画家用肥料画了一幅画。", "explanation": "这里应该用「颜料」。颜料用来上色，肥料是给植物用的，不能用来画画。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20844, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我昨天买了一只肥料，撒在菜地里。", "corrected_sentence": "我昨天买了一袋肥料，撒在菜地里。", "error_description": "错误：「一只肥料」，正确：「一袋肥料」。肥料应用量词「袋」，「只」用于动物或成对的东西，不能用来数肥料。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20844, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他把肥料们放进了桶里。", "corrected_sentence": "他把肥料放进了桶里。", "error_description": "错误在于“肥料”后多加了“们”。“们”只用于指人或有生命的名词，“肥料”是物质名词，不能加“们”；正确为“他把肥料放进了桶里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4a845b51-b13e-483c-bfd9-dd14a4b661fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心里想的最好的事情相对。"}, {"text": "草地", "is_correct": false, "explanation": "草地：与“理想”没有反义关系，是自然地貌，与此义无关。"}, {"text": "雨伞", "is_correct": false, "explanation": "雨伞：与“理想”没有反义关系，是日用品，与此义无关。"}, {"text": "窗户", "is_correct": false, "explanation": "窗户：与“理想”没有反义关系，是建筑的组成部分，与此义无关。"}], "correct_answer": "现实", "explanations": {"现实": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心里想的最好的事情相对。", "草地": "草地：与“理想”没有反义关系，是自然地貌，与此义无关。", "雨伞": "雨伞：与“理想”没有反义关系，是日用品，与此义无关。", "窗户": "窗户：与“理想”没有反义关系，是建筑的组成部分，与此义无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "现实", "is_correct": true, "explanation": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心里想的最好的事情相对。"}, {"text": "纸张", "is_correct": false, "explanation": "纸张：与“理想”没有反义关系，是具体的材料，与此义无关。"}, {"text": "钢铁", "is_correct": false, "explanation": "钢铁：与“理想”没有反义关系，是具体的金属材料，与此义无关。"}, {"text": "花园", "is_correct": false, "explanation": "花园：与“理想”没有反义关系，是具体的场所，与此义无关。"}], "correct_answer": "现实", "explanations": {"现实": "现实：与“理想”构成反义关系，指客观存在的实际情况，与心里想的最好的事情相对。", "纸张": "纸张：与“理想”没有反义关系，是具体的材料，与此义无关。", "钢铁": "钢铁：与“理想”没有反义关系，是具体的金属材料，与此义无关。", "花园": "花园：与“理想”没有反义关系，是具体的场所，与此义无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "理想就是心里想的最好的事情。", "primary_collocate": null, "pronunciation": "lǐ xiǎng", "ipa": "li˨˩˦ ɕjɑŋ˨˩˦", "syllable_count": 2, "sentences": [{"text": "我的理想很简单。", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "她告诉朋友自己的理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "弟弟的理想是当警察。", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "爸爸说，有理想的人不怕累。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个理想让他每天都很快乐。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你的理想是什么？", "target_word": "理想", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他从小就有一个理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家在课上谈了各自的理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "为了自己的理想，她学习音乐。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我不会放弃我的理想。", "target_word": "理想", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "理想主义", "label": "复合"}], "register": "中性", "sense_fingerprint": "名词：心里想要的最好的事情", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5eeed5b8-1098-4e34-8801-c1d52aad0786') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "理想：心里想要实现的美好目标，可以说“很简单”，句意通顺。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体特征，不能用“很简单”来形容。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体指标，不能用“很简单”来形容。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”是岁数，不是可以用“简单”描述的目标，句意不通。"}], "explanations": {"理想": "理想：心里想要实现的美好目标，可以说“很简单”，句意通顺。", "身高": "体貌：“身高”是身体特征，不能用“很简单”来形容。", "体重": "体貌：“体重”是身体指标，不能用“很简单”来形容。", "年龄": "语义：“年龄”是岁数，不是可以用“简单”描述的目标，句意不通。"}, "sentence_index": 0, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她理想了一个好计划。", "explanation": "这里应该用〈想出〉。理想是名词，不作动词；“她想出了一个好计划”才对。"}, {"text": "这个理想已经被很多实验证实了。", "explanation": "这里应该用〈理论〉。理想指心里想要实现的美好事情，不能像理论那样被实验证实。"}, {"text": "她心里有一把理想。", "explanation": "量词不对。理想是抽象名词，不用“把”，应该说“个”或“种”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "理想", "is_correct": true, "explanation": "理想：可以“从小就有”的长远目标，句意通顺。"}, {"text": "气温", "is_correct": false, "explanation": "语义：“气温”是天气的冷热，不是人从小就拥有的东西，句意不通。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是身体的高度，不说“有一个身高”，句意不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：“学历”是受教育的程度，要逐步取得，不能“从小就有”。"}], "explanations": {"理想": "理想：可以“从小就有”的长远目标，句意通顺。", "气温": "语义：“气温”是天气的冷热，不是人从小就拥有的东西，句意不通。", "身高": "体貌：“身高”是身体的高度，不说“有一个身高”，句意不通。", "学历": "语义：“学历”是受教育的程度，要逐步取得，不能“从小就有”。"}, "sentence_index": 6, "correct_answer": "理想"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的理想是明天去医院。", "explanation": "这里应该用〈打算〉。理想指心里想要的最好的事情，不指明天要去的地方；“我明天打算去医院”才对。"}, {"text": "他来北京的理想是看朋友。", "explanation": "这里应该用〈目的〉。理想指心里向往的美好目标，不用来指一次出行的缘由。"}, {"text": "他送给我一份理想。", "explanation": "这里应该用〈礼物〉。理想指心中向往的美好目标，不是可以送给别人的实物。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她心里有一条很好的理想。", "corrected_sentence": "她心里有一个很好的理想。", "error_description": "量词错误：“理想”应该用量词“个”，“条”用于细长的东西，不能修饰“理想”。正确说法是“一个很好的理想”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20846, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的理想已经实现着。", "corrected_sentence": "她的理想已经实现了。", "error_description": "时态错误：“实现”是一次性完成的动作，已经完成应用“了”，“着”表示动作持续，不能说“已经实现着”。正确说法是“已经实现了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3a4dd33e-60b7-405d-bd18-a9e9ea259e75') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
