INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20848, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "东西用完后剩下的部分。", "primary_collocate": null, "pronunciation": "cán yú wù", "ipa": "tsʰan³⁵ y³⁵ u⁵¹", "syllable_count": 3, "sentences": [{"text": "火烧完以后，地上有黑色的残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "茶喝完了，杯底还有一点儿残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "做完实验，我们要处理这些残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "油用完后，锅里留下了一层残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他把咖啡的残余物倒在花盆里。", "target_word": "残余物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机里有很多洗衣粉的残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些残余物不能吃，请扔到垃圾桶里。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "工厂把生产后的残余物送到别的地方。", "target_word": "残余物", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水干了以后，盆底有白色的残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他用刷子刷掉了墙上的残余物。", "target_word": "残余物", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "一堆残余物", "label": "量词"}, {"form": "一层残余物", "label": "量词"}, {"form": "殘餘物", "label": "繁体"}], "register": "中性", "sense_fingerprint": "残余物|东西用完后剩下的部分", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c5597598-c981-48d2-943d-58920f11f2ef') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20848, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "残余物", "is_correct": true, "explanation": "残余物：火烧后留下的黑色剩余物。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光不是黑色的，“黑色的阳光”说不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是多种颜色的光，与“黑色”矛盾。"}, {"text": "火", "is_correct": false, "explanation": "搭配：“黑色的”修饰“火”搭配不当，火不会留在地上成为黑色的东西。"}], "explanations": {"残余物": "残余物：火烧后留下的黑色剩余物。", "阳光": "语义：阳光不是黑色的，“黑色的阳光”说不通。", "彩虹": "语义：彩虹是多种颜色的光，与“黑色”矛盾。", "火": "搭配：“黑色的”修饰“火”搭配不当，火不会留在地上成为黑色的东西。"}, "sentence_index": 0, "correct_answer": "残余物"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "地上放着一张残余物。", "explanation": "这里应该用〈层〉。残余物是铺开的剩余物，不能用〈张〉，那是用于纸张、桌面等平面物的。"}, {"text": "他在墓里找到了一具古人的残余物。", "explanation": "这里应该用〈遗骸〉。残余物不指人的遗体，古人的遗体要用〈遗骸〉。"}, {"text": "父亲给我留下了一笔残余物。", "explanation": "这里应该用〈遗产〉。残余物是用剩的东西，不是可以留给子女的财产。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20848, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "残余物", "is_correct": true, "explanation": "残余物：不能吃、应当扔掉的剩余物。"}, {"text": "宝石", "is_correct": false, "explanation": "语义：宝石价值很高，不应该扔到垃圾桶里。"}, {"text": "音乐", "is_correct": false, "explanation": "搭配：“吃”不能搭配“音乐”，“这些音乐不能吃”说不通。"}, {"text": "钞票", "is_correct": false, "explanation": "语义：钞票值钱，不应该扔到垃圾桶里。"}], "explanations": {"残余物": "残余物：不能吃、应当扔掉的剩余物。", "宝石": "语义：宝石价值很高，不应该扔到垃圾桶里。", "音乐": "搭配：“吃”不能搭配“音乐”，“这些音乐不能吃”说不通。", "钞票": "语义：钞票值钱，不应该扔到垃圾桶里。"}, "sentence_index": 6, "correct_answer": "残余物"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "账户里只剩下残余物。", "explanation": "这里应该用〈余额〉。残余物指用剩的东西，不能用来说账户里的钱；账户里剩下的钱叫余额。"}, {"text": "10除以3，残余物是1。", "explanation": "这里应该用〈余数〉。残余物指用剩的东西，不能指算式里的数；除法后剩下的数叫余数。"}, {"text": "他的抽屉里有一沓残余物。", "explanation": "这里应该用〈钞票〉。残余物是废弃的剩余物，不指钞票。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20848, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "台面上有一朵残余物，要记得擦掉。", "corrected_sentence": "台面上有一堆残余物，要记得擦掉。", "error_description": "量词错误：“残余物”成堆，应说“一堆残余物”，不能说“一朵残余物”（“朵”用于花、云等）。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20848, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "墙角堆着一株黑色的残余物。", "corrected_sentence": "墙角堆着一堆黑色的残余物。", "error_description": "量词错误：“残余物”成堆，应说“一堆残余物”，不能说“一株残余物”（“株”用于植物）。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4ad7ff85-3b71-4c71-816c-f2b148642e1d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
