INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20856, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "一种东西慢慢换成另一种东西，比如森林变成草地。", "primary_collocate": null, "pronunciation": "yǎn tì", "ipa": "jɛn˨˩˦ tʰi˥˩", "syllable_count": 2, "sentences": [{"text": "森林慢慢变成草地，这就是演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小池塘变成草地，要经过很长的演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的树慢慢换成了另一种树，这是演替。", "target_word": "演替", "complexity_tier": "T3", "furigana": "yǎn tì", "sentence_source": "generated"}, {"text": "老师带我们去看荒地的演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "田里不种菜以后，草的演替开始了。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演替就是一种东西慢慢换成另一种。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "池水变干后，这里发生了演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "几十年里，这座山经历了演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙地上先长草，再长树，这是演替。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "演替很慢，我们一年看不出变化。", "target_word": "演替", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "群落演替", "label": "复合"}, {"form": "次生演替", "label": "复合"}], "register": "通用", "sense_fingerprint": "一种东西慢慢换成另一种东西，如森林变草地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '48ac3c8d-76b4-45c0-965f-4bd59ba0a937') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20856, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "演替", "is_correct": true, "explanation": "正确：指一种东西慢慢换成另一种东西，森林变成草地正是这一过程。"}, {"text": "栽种", "is_correct": false, "explanation": "语义：栽种是人为种下植物，与森林自然变成草地的过程不符。"}, {"text": "翻耕", "is_correct": false, "explanation": "搭配：翻耕是对耕地的农事，不能用来指森林变成草地。"}, {"text": "灭绝", "is_correct": false, "explanation": "语义：灭绝指物种消失，句中描述的是一种东西换成另一种，意思不同。"}], "explanations": {"演替": "正确：指一种东西慢慢换成另一种东西，森林变成草地正是这一过程。", "栽种": "语义：栽种是人为种下植物，与森林自然变成草地的过程不符。", "翻耕": "搭配：翻耕是对耕地的农事，不能用来指森林变成草地。", "灭绝": "语义：灭绝指物种消失，句中描述的是一种东西换成另一种，意思不同。"}, "sentence_index": 0, "correct_answer": "演替"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这片田一夜之间演替成了果园。", "explanation": "这里应该用〈转变〉。演替指东西慢慢换成另一种，一夜之间的突然变化应用〈转变〉。"}, {"text": "他慢慢演替成了班长。", "explanation": "这里应该用〈当选〉。演替指东西慢慢换成另一种，人担任职务应用〈当选〉。"}, {"text": "我的老房子一夜之间演替成了新楼。", "explanation": "这里应该用〈重建〉。演替指东西慢慢换成另一种，房屋的推倒重建是突然发生的，应用〈重建〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20856, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "演替", "is_correct": true, "explanation": "正确：指一种东西慢慢换成另一种，池水变干后此处植物群落逐步更替正是演替。"}, {"text": "积水", "is_correct": false, "explanation": "语义：池水已经变干，“积水”与句中的变化矛盾。"}, {"text": "结冰", "is_correct": false, "explanation": "语义：池水变干后已无水可结冰，与句意不符。"}, {"text": "施肥", "is_correct": false, "explanation": "搭配：施肥是人为给土地加肥，与池水变干这一自然变化不搭配。"}], "explanations": {"演替": "正确：指一种东西慢慢换成另一种，池水变干后此处植物群落逐步更替正是演替。", "积水": "语义：池水已经变干，“积水”与句中的变化矛盾。", "结冰": "语义：池水变干后已无水可结冰，与句意不符。", "施肥": "搭配：施肥是人为给土地加肥，与池水变干这一自然变化不搭配。"}, "sentence_index": 6, "correct_answer": "演替"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "电脑系统已经演替到了最新版本。", "explanation": "这里应该用〈更新〉。演替指东西慢慢换成另一种，软件版本的升级应用〈更新〉。"}, {"text": "这把钥匙一瞬间演替成了另一把。", "explanation": "这里应该用〈换〉。演替指东西慢慢换成另一种，一瞬间的更换应用〈换〉。"}, {"text": "这两个人慢慢演替成了朋友。", "explanation": "这里应该用〈结为〉。演替不用于人与人之间的关系，两人结成朋友应说〈结为〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20856, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这座山在几百年里慢慢被演替了。", "corrected_sentence": "这座山在几百年里慢慢演替了。", "error_description": "句式错误：“演替”是不及物动词，不能用“被”字句，应去掉“被”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20856, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沼泽边的草地明年发生了演替。", "corrected_sentence": "沼泽边的草地明年发生演替。", "error_description": "时态错误：“明年”指将来，“了”表示已完成，不能与“明年”搭配，应去掉“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9426855b-7d99-42da-a5b9-e53e892ccfad') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
