INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20886, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "法律是国家制定、大家都必须遵守的规则。", "primary_collocate": null, "pronunciation": "fǎ lǜ", "ipa": "fa˨˩ ly˥˩", "syllable_count": 2, "sentences": [{"text": "每个人都要遵守法律。", "target_word": "法律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这条法律是去年才有的。", "target_word": "法律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开车喝酒是不对的，法律也不允许。", "target_word": "法律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的法律规定，开车时不能打电话。", "target_word": "法律", "complexity_tier": "T3", "furigana": "zhè ge chéng shì de fǎ lǜ guī dìng, kāi chē shí bù néng dǎ diàn huà。", "sentence_source": "generated"}, {"text": "国家有法律，大家都不能做坏事。", "target_word": "法律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律告诉我们什么能做，什么不能做。", "target_word": "法律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩子也要知道一点法律。", "target_word": "法律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律面前，人人都一样。", "target_word": "法律", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他不遵守法律，警察来找他了。", "target_word": "法律", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "法律规定，没有驾照的人不能开车。", "target_word": "法律", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}], "register": "中性", "sense_fingerprint": "国家制定、大家必须遵守的规则", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6d8b840b-ee01-4694-9784-5eb6724c58e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20886, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "法律", "is_correct": true, "explanation": "正确：「遵守法律」指遵守国家制定的规则，与句意相符。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是可以遵守的规则，「遵守天气」不合逻辑。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：「遵守」常搭配规则、纪律、制度一类的词，不搭配「作业」。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家电，不是可以遵守的对象，「遵守冰箱」不成立。"}], "explanations": {"法律": "正确：「遵守法律」指遵守国家制定的规则，与句意相符。", "天气": "语义：天气不是可以遵守的规则，「遵守天气」不合逻辑。", "作业": "搭配：「遵守」常搭配规则、纪律、制度一类的词，不搭配「作业」。", "冰箱": "语义：冰箱是家电，不是可以遵守的对象，「遵守冰箱」不成立。"}, "sentence_index": 0, "correct_answer": "法律"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们球队的法律很严，队员都要按时训练。", "explanation": "这里应该用〈纪律〉。「法律」指国家制定的规则，球队内部的要求要用〈纪律〉。"}, {"text": "讲礼貌是一种法律。", "explanation": "这里应该用〈道德〉。「法律」是国家制定、强制执行的规则，「讲礼貌」属于道德规范，靠自觉遵守，不能说成法律。"}, {"text": "我们家的法律是晚上十点睡觉。", "explanation": "这里应该用〈规矩〉。「法律」只指国家制定的规则，家里的要求要用〈规矩〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20886, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "法律", "is_correct": true, "explanation": "正确：「法律」指国家的法律，“小孩子也要知道一点法律”指日常应懂的基本规则，符合句意。"}, {"text": "抽屉", "is_correct": false, "explanation": "语义：抽屉是家具的部件，不是可以“知道一点”的知识或规则，搭配不成立。"}, {"text": "厨房", "is_correct": false, "explanation": "语义：厨房是地方，不是可以“知道一点”的知识或规则，搭配不成立。"}, {"text": "葡萄", "is_correct": false, "explanation": "语义：葡萄是水果，不是可以“知道一点”的知识或规则，搭配不成立。"}], "explanations": {"法律": "正确：「法律」指国家的法律，“小孩子也要知道一点法律”指日常应懂的基本规则，符合句意。", "抽屉": "语义：抽屉是家具的部件，不是可以“知道一点”的知识或规则，搭配不成立。", "厨房": "语义：厨房是地方，不是可以“知道一点”的知识或规则，搭配不成立。", "葡萄": "语义：葡萄是水果，不是可以“知道一点”的知识或规则，搭配不成立。"}, "sentence_index": 6, "correct_answer": "法律"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "学校的法律不允许学生带手机。", "explanation": "这里应该用〈规定〉。「法律」指国家的法律，学校的要求要用〈规定〉。"}, {"text": "这里的法律是春节要包饺子。", "explanation": "这里应该用〈习俗〉。「法律」是国家制定的强制规则，春节包饺子是大家自然形成的习惯，要用〈习俗〉。"}, {"text": "牛顿发现了万有引力法律。", "explanation": "这里应该用〈定律〉。「法律」指国家制定、强制执行的规则，自然规律要用〈定律〉，如“万有引力定律”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20886, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这把法律保护每个消费者的权利。", "corrected_sentence": "这条法律保护每个消费者的权利。", "error_description": "错误：量词「把」用于有柄的器具，不能用于法律。正确：量词「条」，即“这条法律”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20886, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他虽然是老板，也要遵守了法律。", "corrected_sentence": "他虽然是老板，也要遵守法律。", "error_description": "错误：助动词「要」表示将来或意愿，动词「遵守」后不能加动态助词「了」。正确：“也要遵守法律”，「遵守」后直接接宾语「法律」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1b7604d9-eec6-4ed8-a3ae-2a5d6e1b51bf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
