INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20898, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "做过某件事后积累下来的知识和体会。", "primary_collocate": null, "pronunciation": "jīng yàn", "ipa": "tɕiŋ˥ jɛn˥˩", "syllable_count": 2, "sentences": [{"text": "他有十年的教书经验。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有开车的经验，不敢上路。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位医生经验很多。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师把自己的经验告诉了我们。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "做饭需要经验，多做就会了。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是第一次来，没有经验。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有经验的人都说这里夏天很热。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想学习他工作中的经验。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在这方面经验不多。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年轻人少了点经验，但是很努力。", "target_word": "经验", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一点", "label": "量词"}, {"form": "一些", "label": "量词"}, {"form": "經驗", "label": "繁体"}, {"form": "经验教训", "label": "复合"}], "register": "通用", "sense_fingerprint": "做过某事后积累的知识和体会", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dc47638d-8454-4a74-8064-965a8426d1e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20898, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "经验", "is_correct": true, "explanation": "经验（jīng yàn）指做过某事后积累的知识和体会，是正确答案。"}, {"text": "精研", "is_correct": false, "explanation": "yán（第二声）与 yàn（第四声）声调不同，精研意思是精心研究。"}, {"text": "竞演", "is_correct": false, "explanation": "jìng（第四声）与 jīng（第一声）声调不同，yǎn（第三声）与 yàn（第四声）声调也不同，竞演意思是竞技表演。"}, {"text": "经言", "is_correct": false, "explanation": "yán（第二声）与 yàn（第四声）声调不同，经言意思是经典的言论。"}], "explanations": {"经验": "经验（jīng yàn）指做过某事后积累的知识和体会，是正确答案。", "精研": "yán（第二声）与 yàn（第四声）声调不同，精研意思是精心研究。", "竞演": "jìng（第四声）与 jīng（第一声）声调不同，yǎn（第三声）与 yàn（第四声）声调也不同，竞演意思是竞技表演。", "经言": "yán（第二声）与 yàn（第四声）声调不同，经言意思是经典的言论。"}, "sentence_index": null, "correct_answer": "经验"}, "level_3": {"options": [{"text": "经验", "is_correct": true, "explanation": "“教书经验”指长期教书积累的知识和技能，与“十年的”的时长搭配。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“教书”之后不能接“颜色”，二者无法构成修饰关系。"}, {"text": "体重", "is_correct": false, "explanation": "语义：体重指人的身体重量，与“教书”和“十年”的时长语境无关。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气指气候状况，不能与“十年的教书”组成有意义的修饰语。"}], "explanations": {"经验": "“教书经验”指长期教书积累的知识和技能，与“十年的”的时长搭配。", "颜色": "搭配：“教书”之后不能接“颜色”，二者无法构成修饰关系。", "体重": "语义：体重指人的身体重量，与“教书”和“十年”的时长语境无关。", "天气": "语义：天气指气候状况，不能与“十年的教书”组成有意义的修饰语。"}, "sentence_index": 0, "correct_answer": "经验"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "科学家们正在做一项新经验，结果很重要。", "explanation": "这里应该用〈实验〉。经验指从实践中积累的知识和技能，科学研究中的试验要用实验。"}, {"text": "这部经验名著我读了三遍。", "explanation": "这里应该用〈经典〉。经验指从实践中积累的知识和技能，形容名著的地位要用经典。"}, {"text": "这批零件的经验报告还没有写完。", "explanation": "这里应该用〈检验〉。检验指用仪器或方法检查产品质量，经验指积累的知识和技能，不能用于质检报告。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20898, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "经验", "is_correct": true, "explanation": "“有经验的人”指有实践积累的人，与“都说这里夏天很热”的判断语境一致。"}, {"text": "伤口", "is_correct": false, "explanation": "语义：伤口是身体的损伤，不是人的某种属性，与“说这里夏天很热”无关。"}, {"text": "疤痕", "is_correct": false, "explanation": "语义：疤痕是皮肤的痕迹，不能说明人对气候的判断。"}, {"text": "年轮", "is_correct": false, "explanation": "搭配：“年轮”通常只用于树木，“有年轮的人”搭配不当。"}], "explanations": {"经验": "“有经验的人”指有实践积累的人，与“都说这里夏天很热”的判断语境一致。", "伤口": "语义：伤口是身体的损伤，不是人的某种属性，与“说这里夏天很热”无关。", "疤痕": "语义：疤痕是皮肤的痕迹，不能说明人对气候的判断。", "年轮": "搭配：“年轮”通常只用于树木，“有年轮的人”搭配不当。"}, "sentence_index": 6, "correct_answer": "经验"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这笔经验已经批下来了。", "explanation": "这里应该用〈经费〉。经费指用于事业或工作的钱，经验指积累的知识和技能，不指款项。"}, {"text": "我们公司的新经验今天上任了。", "explanation": "这里应该用〈经理〉。经理指负责管理的人员，经验指积累的知识和技能，不指担任职务的人。"}, {"text": "他经验了很多磨难。", "explanation": "这里应该用〈经受〉。经验是名词，表示承受磨难要用动词经受。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20898, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一位经验，做这件事很快。", "corrected_sentence": "他有一点经验，做这件事很快。", "error_description": "量词错误：“经验”是抽象名词，不能用指人的量词“位”计量，应说“一点经验”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20898, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她在这方面很多经验。", "corrected_sentence": "她在这方面有很多经验。", "error_description": "漏掉动词：“经验”作宾语，“很多经验”前缺少动词“有”，应说“她在这方面有很多经验”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'dbb0dd0a-742a-421e-8cd8-83dac50e8936') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
