INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20904, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "事物中包含的道理或作用。", "primary_collocate": null, "pronunciation": "yì yì", "ipa": "i˥˩ i˥˩", "syllable_count": 2, "sentences": [{"text": "这件事对我很有意义。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你知道植树的意义吗？", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "帮助别人让她觉得生活有意义。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个节日的意义是让家人在一起。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说这样做没有意义。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次比赛的意义比输赢更大。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们讲了这首诗的意义。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对老人来说，这张照片有特别的意义。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不明白这件事的意义。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这项工作意义重大，大家要认真做。", "target_word": "意义", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "事物所包含的道理、价值或作用", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7050c44d-4887-4a5d-8657-6743f77125d2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20904, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "意义", "is_correct": true, "explanation": "“意义”读作 yì yì，指事物所包含的道理或作用。"}, {"text": "疑义", "is_correct": false, "explanation": "“疑义”读作 yí yì，第一音节声调不同，意思是疑问，与“意义”不同。"}, {"text": "易于", "is_correct": false, "explanation": "“易于”读作 yì yú，第二音节韵母不同，意思是容易，与“意义”不同。"}, {"text": "一意", "is_correct": false, "explanation": "“一意”读作 yī yì，第一音节声调不同，意思是专一，与“意义”不同。"}], "explanations": {"意义": "“意义”读作 yì yì，指事物所包含的道理或作用。", "疑义": "“疑义”读作 yí yì，第一音节声调不同，意思是疑问，与“意义”不同。", "易于": "“易于”读作 yì yú，第二音节韵母不同，意思是容易，与“意义”不同。", "一意": "“一意”读作 yī yì，第一音节声调不同，意思是专一，与“意义”不同。"}, "sentence_index": null, "correct_answer": "意义"}, "level_3": {"options": [{"text": "意义", "is_correct": true, "explanation": "“意义”指事物的道理或价值，填入句中“对我很有……”的空缺处最为恰当。"}, {"text": "数量", "is_correct": false, "explanation": "语义：“数量”指数目多少，不能说“对我很有数量”，与句中的影响不符。"}, {"text": "体积", "is_correct": false, "explanation": "搭配：“体积”一般说“有体积”指物体的大小，不说“对我很有体积”。"}, {"text": "尺寸", "is_correct": false, "explanation": "语义：“尺寸”指物体的长宽大小，与“这件事对我的影响”这种抽象含义不合。"}], "explanations": {"意义": "“意义”指事物的道理或价值，填入句中“对我很有……”的空缺处最为恰当。", "数量": "语义：“数量”指数目多少，不能说“对我很有数量”，与句中的影响不符。", "体积": "搭配：“体积”一般说“有体积”指物体的大小，不说“对我很有体积”。", "尺寸": "语义：“尺寸”指物体的长宽大小，与“这件事对我的影响”这种抽象含义不合。"}, "sentence_index": 0, "correct_answer": "意义"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这种药的意义很大，效果很好。", "explanation": "这里应该用〈疗效〉。“意义”指事物的道理或价值，说药物的效果要用“疗效”，这句把“意义”用来指药效，搭配不当。"}, {"text": "这是我的一点小意义，请收下。", "explanation": "这里表示礼物的心意，应该用〈意思〉。“意义”指道理或价值，不能用来指送礼的心意。"}, {"text": "我们讨论了一只意义。", "explanation": "这里应该用〈个〉或〈种〉。“只”用于动物或成对的东西，“意义”是抽象名词，不能用“只”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20904, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "意义", "is_correct": true, "explanation": "“意义”指这首诗所包含的道理或价值，填入句中“老师讲了这首诗的……”最为恰当。"}, {"text": "页码", "is_correct": false, "explanation": "语义：“页码”是书页的编号，老师不会讲解“页码”，与句中的讲解内容不合。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：“墨水”是书写的材料，不是老师讲解的内容，与句中语境不符。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“这首诗的价格”一般不说，“讲价格”也与讲解诗歌的语境不搭配。"}], "explanations": {"意义": "“意义”指这首诗所包含的道理或价值，填入句中“老师讲了这首诗的……”最为恰当。", "页码": "语义：“页码”是书页的编号，老师不会讲解“页码”，与句中的讲解内容不合。", "墨水": "语义：“墨水”是书写的材料，不是老师讲解的内容，与句中语境不符。", "价格": "搭配：“这首诗的价格”一般不说，“讲价格”也与讲解诗歌的语境不搭配。"}, "sentence_index": 6, "correct_answer": "意义"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这块手表的意义很便宜，只要五十块。", "explanation": "这里应该用〈价钱〉。“意义”指道理或感情上的分量，说价钱要用“价钱”。"}, {"text": "这张桌子的意义很高，用了很多年也没坏。", "explanation": "这里应该用〈质量〉。“意义”指道理或作用，不能用来形容桌子的结实程度，说物品的坚固要用“质量”。"}, {"text": "这件事有一张深刻的意义。", "explanation": "这里应该用〈种〉。“张”用于纸、桌子等平面的东西，“意义”是抽象名词，不能用“张”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20904, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这件事有一只特殊的意义。", "corrected_sentence": "这件事有一种特殊的意义。", "error_description": "量词错误：“一只特殊的意义”应为“一种特殊的意义”。“只”用于动物或成对的东西，抽象的“意义”应用量词“种”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20904, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这次活动对学生很意义。", "corrected_sentence": "这次活动对学生很有意义。", "error_description": "漏词错误：“很意义”应为“很有意义”。“意义”是名词，前面要加动词“有”构成“有意义”，不能直接接在副词“很”后面。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d6691dd-639a-4347-b638-3782c3448a69') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
