INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20910, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "住在城市里的人。", "primary_collocate": null, "pronunciation": "shì mín", "ipa": "ʂʐ̩˥˩ min˧˥", "syllable_count": 2, "sentences": [{"text": "我是这个城市的市民。", "target_word": "市民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "市民在广场上跳舞。", "target_word": "市民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新来的市民要办居住证。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家医院为市民服务了几十年。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民们都排队买早餐。", "target_word": "市民", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这座城市有一千万市民。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民坐公交车可以打折。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "晚上市民喜欢去夜市吃东西。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "台风来了，市民要待在家里。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "市民给图书馆捐了很多书。", "target_word": "市民", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "市民们", "label": "复合"}], "register": "中性", "sense_fingerprint": "住在城市里的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '93755cc4-9c9f-4da2-a21c-6c25fdf039d7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20910, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "正确答案。市民指住在城市里的人，与「我是这个城市的」相合。"}, {"text": "农民", "is_correct": false, "explanation": "语义：「农民」指在农村种地的人，与「这个城市的」相矛盾。"}, {"text": "乡下人", "is_correct": false, "explanation": "语域：「乡下人」口语色彩较重，且指农村的人，与「这个城市的」相矛盾。"}, {"text": "外星人", "is_correct": false, "explanation": "语义：外星人不住在这座城市里，与「我是这个城市的」相矛盾。"}], "explanations": {"市民": "正确答案。市民指住在城市里的人，与「我是这个城市的」相合。", "农民": "语义：「农民」指在农村种地的人，与「这个城市的」相矛盾。", "乡下人": "语域：「乡下人」口语色彩较重，且指农村的人，与「这个城市的」相矛盾。", "外星人": "语义：外星人不住在这座城市里，与「我是这个城市的」相矛盾。"}, "sentence_index": 0, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们村的市民都很热情。", "explanation": "这里应该用〈村民〉。市民指住在城市里的人，住在村子里的人不能称为市民。"}, {"text": "这片草原上住着很多市民。", "explanation": "这里应该用〈牧民〉。草原上没有城市，不能说住着市民。"}, {"text": "市民都住在村子里。", "explanation": "这里应该用〈乡下人〉。市民指城市居民，不能用来指住在村子里的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20910, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "市民", "is_correct": true, "explanation": "正确答案。市民指住在城市里的人，能坐公交车并享受折扣。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会坐公交车，与句意相矛盾。"}, {"text": "大象", "is_correct": false, "explanation": "搭配：「坐公交车」的主语须是人，不能说“大象坐公交车”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会坐公交车，与句意相矛盾。"}], "explanations": {"市民": "正确答案。市民指住在城市里的人，能坐公交车并享受折扣。", "石头": "语义：石头不会坐公交车，与句意相矛盾。", "大象": "搭配：「坐公交车」的主语须是人，不能说“大象坐公交车”。", "窗户": "语义：窗户不会坐公交车，与句意相矛盾。"}, "sentence_index": 6, "correct_answer": "市民"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "市民大多在地里干活。", "explanation": "这里应该用〈农村人〉。市民指城市里的居民，不能用来说大多在地里干活的人。"}, {"text": "市民一家人一直在海上捕鱼。", "explanation": "这里应该用〈渔民〉。市民指城市居民，不能用来指一家人一直在海上捕鱼的人。"}, {"text": "市民都剃了光头，在寺里念经。", "explanation": "这里应该用〈和尚〉。市民指城市居民，不能用来指剃了光头、在寺里念经的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20910, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我爸爸是这个城市的市民们。", "corrected_sentence": "我爸爸是这个城市的市民。", "error_description": "多余的“们”：「市民们」表示多人，指单个人时不加“们”。“我爸爸”只指一人，应说“我爸爸是这个城市的市民”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20910, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "凡是本区的市民的都可以申请补贴。", "corrected_sentence": "凡是本区的市民都可以申请补贴。", "error_description": "多余的“的”：「市民」作主语时后面不加“的”，应说“凡是本区的市民都可以申请补贴”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '20fe75e4-bf15-406f-9ae9-36dc3f44fa4f') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20912, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
