INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20912, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "精神就是一个人心里想的东西，比如开心、难过。", "primary_collocate": null, "pronunciation": "jīng shén", "ipa": "tɕiŋ˥ ʂən˧˥", "syllable_count": 2, "sentences": [{"text": "他的精神受到很大的打击，整个人都变了。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试结束了，大家的精神都很放松。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他刚失去工作，精神上很难过。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友来陪我，我在精神上好多了。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "孩子需要吃饭，也需要精神上的快乐。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开心和难过都是精神的一部分。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她身体没有病，只是精神有点儿不安。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "听着音乐，我的精神慢慢安静下来了。", "target_word": "精神", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看书能让人的精神得到安慰。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我们不但要关心身体，也要关心精神。", "target_word": "精神", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "精神状态", "label": "复合"}, {"form": "精神压力", "label": "复合"}, {"form": "精神世界", "label": "复合"}], "register": "中性", "sense_fingerprint": "精神：一个人心里的感受和想法，如开心、难过", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9bf20c0d-3c61-4a52-8a10-ec6c7498801e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20912, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "精神", "is_correct": true, "explanation": "“精神”指心里的感受，“受到很大的打击”说的是心理受挫，句意通顺。"}, {"text": "行李", "is_correct": false, "explanation": "搭配：“打击”针对人的心理，“他的行李”不能受到打击。"}, {"text": "价格", "is_correct": false, "explanation": "语义：“价格”是商品的钱数，“他的价格”不能受到心理打击。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：“身高”是体形特征，不能受到心理上的打击。"}], "explanations": {"精神": "“精神”指心里的感受，“受到很大的打击”说的是心理受挫，句意通顺。", "行李": "搭配：“打击”针对人的心理，“他的行李”不能受到打击。", "价格": "语义：“价格”是商品的钱数，“他的价格”不能受到心理打击。", "身高": "体貌：“身高”是体形特征，不能受到心理上的打击。"}, "sentence_index": 0, "correct_answer": "精神"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我有一片很好的精神。", "explanation": "这里应该用〈种〉。〈片〉用于平面或区域，不能用于抽象的心理感受。"}, {"text": "他的精神哑了，说不出话来。", "explanation": "这里应该用〈嗓子〉。〈哑〉形容嗓音，精神是心理状态，不能说“哑”。"}, {"text": "我和朋友的精神很深。", "explanation": "这里应该用〈感情〉。精神指心里的感受和想法，不用“深”来形容人与人之间的关系。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20912, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "精神", "is_correct": true, "explanation": "“只是精神有点儿不安”指心里的感受，与“身体没有病”形成对照，句意通顺。"}, {"text": "头发", "is_correct": false, "explanation": "语义：“头发”是身体的一部分，不会有“不安”的感受。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：“体重”是身体的数值，不能用“不安”来形容。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”是外观，不能用“不安”来形容。"}], "explanations": {"精神": "“只是精神有点儿不安”指心里的感受，与“身体没有病”形成对照，句意通顺。", "头发": "语义：“头发”是身体的一部分，不会有“不安”的感受。", "体重": "体貌：“体重”是身体的数值，不能用“不安”来形容。", "颜色": "语义：“颜色”是外观，不能用“不安”来形容。"}, "sentence_index": 6, "correct_answer": "精神"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们要关心一朵精神。", "explanation": "这里应该用〈种〉。〈朵〉用于花等物体，精神是抽象的，不能用〈朵〉计量。"}, {"text": "她的精神很白，像牛奶一样。", "explanation": "这里应该用〈皮肤〉。〈白〉形容肤色，精神是心理状态，不能用来形容肤色。"}, {"text": "我们不但要吃饱，也要吃精神。", "explanation": "这里把〈精神〉当作〈食物〉来用。精神是抽象的心理状态，不能说“吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20912, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一种帮助别人精神。", "corrected_sentence": "他有一种帮助别人的精神。", "error_description": "漏用“的”：动词短语“帮助别人”修饰名词“精神”时要加“的”。错误形式为“帮助别人精神”，正确形式为“帮助别人的精神”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20912, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他在精神很需要朋友的帮助。", "corrected_sentence": "他在精神上很需要朋友的帮助。", "error_description": "漏用“上”：表示心理方面要说“在精神上”，只说“在精神”不符合习惯。错误形式为“在精神很需要”，正确形式为“在精神上很需要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '123cdbe1-3f2b-4a56-b0ff-c1ffedab4432') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
