INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "记录历史和知识的重要文字材料。", "primary_collocate": null, "pronunciation": "wén xiàn", "ipa": "wən˧˥ ɕjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "这篇文献介绍了古代的农业技术。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "图书馆里有很多珍贵的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老师让我们找一篇关于环保的文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文献是八百年前留下来的。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "研究者认真地阅读每一篇文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他在文献里找到了那位诗人的生平。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这些文献记录了村子几百年的变化。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "要写好报告，你得先读完相关文献。", "target_word": "文献", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "博物馆把这批文献保存得很好。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这类文献现在多数可以在网上免费下载。", "target_word": "文献", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一篇文献", "label": "量词"}, {"form": "参考文献", "label": "复合"}, {"form": "文献资料", "label": "复合"}, {"form": "文獻", "label": "繁体"}], "register": "书面", "sense_fingerprint": "记录历史和知识的重要文字材料", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '2cb2f094-77d0-4e9f-8b03-ce3ad85679b6') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (20914, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "文献", "is_correct": true, "explanation": "正确：“介绍了古代的农业技术”的主语是文献，指记录知识的文字材料，语义相合。"}, {"text": "节日", "is_correct": false, "explanation": "语义：节日是时间节点，不能介绍农业技术。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：量词“篇”不能修饰“冰箱”，且冰箱无法介绍技术。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：歌手是表演者，不能用来介绍古代的农业技术。"}], "explanations": {"文献": "正确：“介绍了古代的农业技术”的主语是文献，指记录知识的文字材料，语义相合。", "节日": "语义：节日是时间节点，不能介绍农业技术。", "冰箱": "搭配：量词“篇”不能修饰“冰箱”，且冰箱无法介绍技术。", "歌手": "语义：歌手是表演者，不能用来介绍古代的农业技术。"}, "sentence_index": 0, "correct_answer": "文献"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份文献的按键坏了，要换新电池。", "explanation": "这里应该用〈遥控器〉。文献是文字材料，没有按键和电池；按键坏了要换电池的是遥控器一类的电器。"}, {"text": "他在三十岁时吃掉了这篇文献。", "explanation": "这里应该用〈读〉。读指看文字材料；吃掉是对食物的动作，文献不能被吃掉。"}, {"text": "这些文献在本次比赛中拿了冠军。", "explanation": "这里应该用〈选手〉。文献是文字资料，不能参赛拿冠军；参赛获胜的是选手。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'e9d8c7c6-5c7a-4cd4-a855-8c926f86b869') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
